#!/bin/bash
# herdr-py: every file of the commit this script is in, but itself, written with mkdir and cat (https://github.com/pop310289/herdr-py).
# usage: bash this-script [FOLDER]   (default: ./herdr-py; the folder must not exist yet), then
#        cd herdr-py && ./scripts/install.sh
# Needs bash, mkdir, cat, base64, chmod, mktemp, grep and sha256sum (or shasum). Ends by checking every file's sha256.
set -eu
dest="${1:-herdr-py}"
if [ -e "$dest" ]; then echo "$dest already exists" >&2; exit 1; fi
mkdir -p "$dest"
cd "$dest"
mkdir -p .github/workflows bench/herdr_compare bench/p23 bench/p23/partial/count/count bench/p23/partial/csvtotals bench/p23/partial/fizzsum bench/p23/partial/median bench/p23/partial/roman bench/p23/partial/top3 bench/p23/reference/count/count bench/p23/reference/csvtotals bench/p23/reference/fizzsum bench/p23/reference/median bench/p23/reference/roman bench/p23/reference/top3 bench/p23/tasks/count bench/p23/tasks/count/work bench/p23/tasks/count/work/count bench/p23/tasks/csvtotals bench/p23/tasks/csvtotals/work bench/p23/tasks/fizzsum bench/p23/tasks/fizzsum/work bench/p23/tasks/median bench/p23/tasks/median/work bench/p23/tasks/roman bench/p23/tasks/roman/work bench/p23/tasks/top3 bench/p23/tasks/top3/work examples examples/coop examples/dag examples/dag/tasks examples/engine examples/notebook examples/self_improve examples/self_improve/scenarios examples/slide_team examples/slide_team/layout examples/slide_team/scaffold herdr_py herdr_py/web herdr_py/web/dashboard scripts tests
mkdir -p tests/fixtures/dashboard_run/work tests/fixtures/dashboard_run/work/codex tests/fixtures/dashboard_run/work/renders tests/fixtures/diagnose/claimed_success/state tests/fixtures/diagnose/claimed_success/work tests/fixtures/diagnose/clean/state tests/fixtures/diagnose/clean/work tests/fixtures/diagnose/clean_codex/work tests/fixtures/diagnose/clean_codex/work/codex tests/fixtures/diagnose/compacted_reply/state tests/fixtures/diagnose/compacted_reply/work tests/fixtures/diagnose/no_change/state tests/fixtures/diagnose/no_change/work tests/fixtures/diagnose/output_limit/state tests/fixtures/diagnose/output_limit/work tests/fixtures/diagnose/reasoning_only/state tests/fixtures/diagnose/reasoning_only/work tests/fixtures/diagnose/repeated_rejection/state tests/fixtures/diagnose/repeated_rejection/work tests/fixtures/diagnose/repeated_tool_error/state tests/fixtures/diagnose/repeated_tool_error/work tests/fixtures/diagnose/revisions_rejected/work
mkdir -p tests/fixtures/diagnose/revisions_rejected/work/codex tests/fixtures/diagnose/revisions_rejected_row/work tests/fixtures/diagnose/time_limit/state tests/fixtures/diagnose/time_limit/work tests/fixtures/diagnose/time_limit_codex/work tests/fixtures/diagnose/time_limit_codex/work/codex tests/fixtures/diagnose/turn_error/work tests/fixtures/diagnose/turn_error/work/codex tests/fixtures/diagnose/turn_error_opencode/state tests/fixtures/diagnose/turn_error_opencode/work tests/fixtures/diagnose/wrong_format/state tests/fixtures/diagnose/wrong_format/work tests/fixtures/diagnose/wrong_format_codex/work tests/fixtures/diagnose/wrong_format_codex/work/codex tools
cat > .github/workflows/tests.yml <<'HERDR_PY_EOF'
# The test suite on every push and pull request, on the Python 3.6 that RHEL 8 ships and on the newest
# stable Python, plus a check that the pushed commits carry no personal data (the repository is public).
# No secrets: the only credential is the token GitHub gives every run, limited here to reading the repository.
# Third-party actions are pinned to full commit SHAs (tags can be moved); the comment names the release.
name: tests

on: [push, pull_request]

permissions:
  contents: read

env:
  PYTHONDONTWRITEBYTECODE: "1"

jobs:
  python36:
    # RHEL 8's python3 is 3.6.8, always present as /usr/libexec/platform-python. The Red Hat Universal Base
    # Image 8 carries that same build, with Red Hat's patches, and is free to pull. actions/setup-python has no
    # 3.6 for current Ubuntu runners; the python:3.6 image on Docker Hub is upstream 3.6.15, last built in 2021.
    name: Python 3.6 (RHEL 8 platform-python, UBI 8)
    runs-on: ubuntu-latest
    timeout-minutes: 15
    container:
      image: registry.access.redhat.com/ubi8/ubi:8.10
    steps:
      # git before checkout: without it actions/checkout downloads a tarball instead of cloning, and the
      # privacy-check tests make git repositories of their own.
      - name: Install git
        run: dnf install -y --setopt=install_weak_deps=False git-core
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          persist-credentials: false
      - name: Interpreter
        run: /usr/libexec/platform-python --version
      - name: Tests
        run: /usr/libexec/platform-python -m unittest discover -s tests

  python-latest:
    name: Python, newest stable (ubuntu-latest)
    runs-on: ubuntu-latest
    timeout-minutes: 15
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          persist-credentials: false
      - uses: actions/setup-python@5fda3b95a4ea91299a34e894583c3862153e4b97  # v7.0.0
        with:
          python-version: "3.x"  # the newest stable 3.x release; pre-releases are not picked
          check-latest: true     # without it an older 3.x already on the runner would be used
      - name: Interpreter
        run: python --version
      - name: Tests
        run: python -m unittest discover -s tests

  privacy:
    name: Privacy check of the pushed commits
    runs-on: ubuntu-latest
    timeout-minutes: 5
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1  # v7.0.1
        with:
          fetch-depth: 0  # all history, so every commit of the push or pull request is there to read
          persist-credentials: false
      # The runner's own python3: the script is standard library only and its tests also run on 3.6 above.
      - name: No co-author or session trailers, home-directory paths or personal e-mail addresses
        run: python3 scripts/ci_privacy.py --github
HERDR_PY_EOF
cat > .gitignore <<'HERDR_PY_EOF'
__pycache__/
*.pyc
.DS_Store
HERDR_PY_EOF
