cat > herdr_py/client.py <<'HERDR_PY_EOF'
"""Talk to a running herdr-py daemon over its Unix socket (used by the CLI and the TUI; any program can do the same)."""
import itertools
import json
import os
import socket


class ClientError(Exception):
    def __init__(self, code, message):
        super().__init__(f"{code}: {message}")
        self.code = code


def default_state_dir():
    base = os.environ.get("XDG_STATE_HOME") or os.path.join(os.path.expanduser("~"), ".local", "state")
    return os.environ.get("HERDR_PY_STATE_DIR") or os.path.join(base, "herdr-py")


def default_socket():
    return os.environ.get("HERDR_PY_SOCKET") or os.path.join(default_state_dir(), "herdr-py.sock")


class Client:
    _ids = itertools.count(1)

    def __init__(self, path=None, timeout=None):
        self.path = path or default_socket()
        self.timeout = timeout

    def _connect(self):
        sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        sock.settimeout(self.timeout)
        try:
            sock.connect(self.path)
        except (FileNotFoundError, ConnectionRefusedError) as exc:
            sock.close()
            raise ClientError("server_not_running", f"no herdr-py daemon at {self.path} ({exc.strerror}); start one with `herdr-py serve`") from None
        return sock

    def call(self, method, **params):
        sock = self._connect()
        try:
            rid = f"c{next(self._ids)}"
            sock.sendall((json.dumps({"id": rid, "method": method, "params": params}) + "\n").encode())
            reader = sock.makefile("rb")
            line = reader.readline()
            if not line:
                raise ClientError("closed", "the daemon closed the connection")
            reply = json.loads(line)
            if "error" in reply:
                raise ClientError(reply["error"].get("code", "error"), reply["error"].get("message", ""))
            return reply["result"]
        finally:
            sock.close()

    def events(self):
        """Yield events forever (first item: {"subscribed": True, "agents": [...]})."""
        sock = self._connect()
        sock.settimeout(None)
        try:
            sock.sendall((json.dumps({"id": "sub", "method": "events.subscribe", "params": {}}) + "\n").encode())
            for line in sock.makefile("rb"):
                msg = json.loads(line)
                if "error" in msg:
                    raise ClientError(msg["error"].get("code", "error"), msg["error"].get("message", ""))
                yield msg.get("result") or msg.get("event")
        finally:
            sock.close()
HERDR_PY_EOF
cat > herdr_py/codex_agents.py <<'HERDR_PY_EOF'
"""Codex CLI sessions as team members (one of herdr-py's member backends, see members.py), with the same contract as
slide_team.Team.run_turn: run_turn(name, prompt, model, files, timeout) -> (last reply text, state).

One `codex exec --json` per turn; later turns use `codex exec resume <thread>`, so every member keeps its own
conversation. Checked with codex-cli 0.160.0 on 2026-10-07:
- events: thread.started {thread_id}, item.completed {item: {type: agent_message, text}}, turn.completed {usage},
  error / turn.failed on failures;
- `exec resume` keeps the first turn's sandbox and folder (it has no -s or -C) and accepts --json, -i and -m;
- stdin must be closed: otherwise exec waits with "Reading additional input from stdin...";
- -i/--image takes several values, so the prompt must come after "--" or it is read as an image path.
A turn over its time limit is stopped with everything Codex started (its own process group) and ends "timeout", not
"aborted", so a slow member is told apart from one that was killed. Every member runs read-only in its own empty folder,
unless a turn names a workdir (a DAG step's workspace, dag.py): then it runs there, in Codex's workspace-write sandbox
(access "write": writes only inside the folder; reads are not limited) or read-only. agents.json (for view.py) holds
each member's state, tokens and last words; events.jsonl keeps every event.
"""
import json
import os
import signal
import subprocess
import threading
import time


def default_codex():
    app = "/Applications/ChatGPT.app/Contents/Resources/codex-cli/CodexCLI.app/Contents/MacOS/codex"
    return os.environ.get("CODEX_BIN") or (app if os.path.exists(app) else "codex")


def stop(proc):
    """End Codex and anything it started (it runs in its own process group)."""
    try:
        os.killpg(proc.pid, signal.SIGKILL)
    except OSError:  # already gone
        pass


class CodexAgents:
    def __init__(self, root, codex=None, model=None, sandbox="read-only", fresh=False):
        """fresh=True: every turn is a new conversation (no resume); the caller's prompt carries everything."""
        self.root, self.codex, self.model, self.sandbox, self.fresh = root, codex or default_codex(), model, sandbox, fresh
        os.makedirs(root, exist_ok=True)
        self.threads, self.agents = {}, {}
        self.lock = threading.Lock()
        self.events = open(os.path.join(root, "events.jsonl"), "a", encoding="utf-8", buffering=1)

    def close(self):
        self.events.close()

    def forget(self, name):
        """This member's next turn starts a new conversation (teamrun.py: members with fresh sessions)."""
        self.threads.pop(name, None)

    def _publish(self):
        tmp = os.path.join(self.root, "agents.json.tmp")
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(self.agents, handle)
        os.replace(tmp, os.path.join(self.root, "agents.json"))  # the viewer never reads half a file

    def _set(self, name, **fields):
        with self.lock:
            agent = self.agents.setdefault(name, {"name": name, "state": "starting", "tokens": 0, "turns": 0,
                                                  "stream": {"kind": "text", "text": ""}})
            agent.update(fields)
            self._publish()

    def args(self, name, prompt, model=None, files=(), workdir=None, access=None):
        thread = None if (self.fresh or workdir) else self.threads.get(name)  # a workspace turn is always a new thread
        out = [self.codex, "exec"] + (["resume", thread] if thread else []) + ["--json", "--skip-git-repo-check"]
        if not thread:
            folder = workdir or os.path.join(self.root, name)
            os.makedirs(folder, exist_ok=True)
            # research is read-only here: Codex members get no web search (not checked with the real Codex CLI)
            sandbox = {"write": "workspace-write", "read": "read-only", "research": "read-only"}[access or "write"] if workdir else self.sandbox
            out += ["-s", sandbox, "-C", folder]
        if model or self.model:
            out += ["-m", model or self.model]
        for path in files:
            out += ["-i", os.path.abspath(path)]
        return out + ["--", prompt]  # -i takes several values: without "--" the prompt is read as one more image

    def run_turn(self, name, prompt, model=None, files=(), timeout=600, workdir=None, access=None):
        """workdir: run this turn in that folder (access "write", the default there, or "read")."""
        if access not in (None, "write", "read"):
            raise ValueError("access: write or read")
        argv = self.args(name, prompt, model, files, workdir=workdir, access=access)
        self._set(name, state="working")
        self.events.write(json.dumps({"t": round(time.time(), 2), "agent": name, "argv": argv[:-1] + ["<prompt>"]}) + "\n")
        err_path = os.path.join(self.root, name + ".stderr.log")  # a file, not a pipe: a full stderr pipe would stall Codex
        err = open(err_path, "a", encoding="utf-8")
        proc = subprocess.Popen(argv, cwd=self.root, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=err,
                                universal_newlines=True, encoding="utf-8", start_new_session=True)
        timed_out = []
        timer = threading.Timer(timeout, lambda: (timed_out.append(True), stop(proc)))
        timer.start()
        texts, state, used = [], "idle", 0
        try:
            for line in proc.stdout:
                try:
                    event = json.loads(line)
                except ValueError:
                    continue
                self.events.write(json.dumps({"t": round(time.time(), 2), "agent": name, "event": event}) + "\n")
                kind = event.get("type")
                if kind == "thread.started" and event.get("thread_id") and not workdir:  # never resume into a workspace
                    self.threads[name] = event["thread_id"]
                elif kind == "item.completed" and (event.get("item") or {}).get("type") == "agent_message":
                    texts.append(event["item"].get("text", ""))
                    self._set(name, stream={"kind": "text", "text": texts[-1][-300:]})
                elif kind == "turn.completed":
                    usage = event.get("usage") or {}
                    used = int(usage.get("input_tokens", 0)) + int(usage.get("output_tokens", 0))
                elif kind in ("error", "turn.failed"):
                    state = "error"
            proc.wait()
        finally:
            timer.cancel()
            proc.stdout.close()
            err.close()
        if timed_out:
            state = "timeout"
        elif proc.returncode and state != "error":
            state = "aborted" if proc.returncode < 0 else "error"
        if state != "idle":
            with open(err_path, encoding="utf-8") as handle:
                tail = handle.read()[-500:]
            row = {"t": round(time.time(), 2), "agent": name, "exit": proc.returncode, "stderr": tail}
            if timed_out:
                row["timeout"] = timeout
            self.events.write(json.dumps(row) + "\n")
        with self.lock:
            tokens = self.agents.get(name, {}).get("tokens", 0) + used
            turns = self.agents.get(name, {}).get("turns", 0) + 1
        self._set(name, state=state, tokens=tokens, turns=turns)
        return (texts[-1].strip() if texts else ""), state
HERDR_PY_EOF
cat > herdr_py/coop.py <<'HERDR_PY_EOF'
"""Cooperative loops: several members work on one task in rounds, a program judges every answer, and the team
knowledge base (teamkb.py) carries the verified answers and the failures from one round to the next.

    python3 -m herdr_py.coop --task task.md --judge "python3 judge.py" --mode C --rounds 3 --out runs/c1 \\
        --member a=codex --member b=claude:haiku --member c=opencode:ollama/qwen3-8b-32k:latest --socket SOCK \\
        --member 'd=command:python3 my_loop.py'
    python3 -m herdr_py.teamkb runs/c1/kb        # what was found, judged, built on and repeated

A rule-guided loop (one agent, fixed rules, a check after every step) becomes a team loop: the rules stay as the
judge, and each member's next prompt also carries what its teammates found and the judge verified. Modes, with the
same number of member turns in each so they can be compared (definitions §17, §18):
  S  single        the first member gets every turn and sees its own earlier answers;
  I  independent   every member sees only its own earlier answers (private entries);
  C  cooperative   every member sees the team's verified answers (with the answers themselves) and failures.
Rounds are waves: every brief is built from what was judged before the round started, then the members run at the
same time, then the program judges every answer. Every prompt is assembled by code from recorded entries; no model
summarises for another, and a member can only name as parents the entries it was shown.

The judge is a command that gets the answer file as its last argument. --judge-mode json (default): it prints one
JSON line {"status": "valid" | "invalid", "score": number, "detail": "..."} and exits 0; a judge that crashes, times
out or prints anything else is a judge error, not an invalid answer. --judge-mode exit: exit code 0 passes (score 1)
and anything else fails, for a pass/fail check you already have (then a crash looks like a fail).
--stop-on-infra-error ends the run after the round in which a member's backend broke (state error or aborted: the
CLI failed, not the answer) or the judge broke; summary.json says where and why, and the command exits 3. Timeouts
and invalid or missing answers are the members' own problems and do not stop the run.
The output folder holds kb/ (the knowledge base), run.jsonl (every turn: state, seconds, tokens, entry, verdict,
problems), members/ (the backends' logs), summary.json and view.html: one page with every member's every turn
(coopview.py), written again after every round, so it can be opened while the run goes on.
"""
import argparse
import collections
import json
import os
import re
import shlex
import subprocess
import sys
import threading
import time

from . import coopview
from .members import MemberError, Members, parse_member
from .teamkb import TeamKB, one_line

MODES = ("S", "I", "C")
ID = re.compile(r"\bk[0-9a-f]{12}\b")
FENCE = re.compile(r"^[ \t]*(```|~~~~)[^\n]*\n(.*?)^[ \t]*\1[ \t]*$", re.S | re.M)

ALONE = ("You work on this task alone. Below are your own earlier answers and failures, as checked by the judge "
         "(a program, not a person). Do better than them.")
TEAM = ("You are {member}, one of {n} members working on this task at the same time. Below are the team's answers and "
        "failures so far, as checked by the judge (a program, not a person). Build on the best ones when that helps, "
        "and do not repeat what failed.")
REPLY = """Reply in this format:
SUMMARY: <one sentence: what you tried>
PARENTS: <ids of the answers above that you built on, comma separated, or none>
```
<your answer, exactly in the format the task asks for>
```
Only the judge's score counts. If you could not produce an answer, reply with one line instead:
FAILED: <what went wrong and what you learned>"""
PROMPT = "{intro} This is {unit} {wave} of {waves}.\n\nTask:\n{task}\n\n{brief}\n\n{reply}"


def labelled(text, label):
    """The text after LABEL: on its own line (markdown bold or quote marks around the label are fine)."""
    m = re.search(r"(?mi)^[ \t>*_]*" + label + r"[ \t]*:[*_]*[ \t]*(.*)$", text or "")
    return m.group(1).strip().strip("*_ ").strip() if m else None


def parse_reply(text):
    """A member's reply -> {"kind": "result" | "failure" | None, "summary", "answer", "parents"}. The answer is the last
    fenced block; without one, a FAILED line is a failure; without either, there is nothing to record."""
    blocks = [m.group(2) for m in FENCE.finditer(text or "")]
    parents = list(collections.OrderedDict.fromkeys(ID.findall(labelled(text, "PARENTS") or "")))
    if blocks:
        return {"kind": "result", "summary": labelled(text, "SUMMARY") or "(no summary given)", "answer": blocks[-1],
                "parents": parents}
    failed = labelled(text, "FAILED")
    if failed:
        return {"kind": "failure", "summary": failed, "answer": None, "parents": parents}
    return {"kind": None, "summary": None, "answer": None, "parents": []}


def command_judge(command, timeout=120):
    """A judge command that prints a JSON verdict (see the module notes). check(path, cwd=None, env=None): the DAG
    runner (dag.py) runs it in a step's workspace with the step's environment."""
    argv = shlex.split(command) if isinstance(command, str) else list(command)

    def check(path, cwd=None, env=None):
        if path is None:
            return "invalid", None, "no answer"
        try:
            p = subprocess.run(argv + [path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True,
                               timeout=timeout, cwd=cwd, env=env)
        except subprocess.TimeoutExpired:
            raise RuntimeError(f"the judge did not finish within {timeout}s")
        if p.returncode != 0:
            raise RuntimeError(f"the judge exited with code {p.returncode}: {one_line(p.stderr or p.stdout, 300)}")
        lines = [line for line in p.stdout.splitlines() if line.strip()]
        if not lines:
            raise RuntimeError("the judge printed nothing")
        verdict = json.loads(lines[-1])
        if not isinstance(verdict, dict):
            raise RuntimeError(f"the judge printed {lines[-1][:200]!r}, not a JSON object")
        return verdict.get("status"), verdict.get("score"), verdict.get("detail", "")
    return check


def exit_judge(command, timeout=120):
    """A pass/fail judge: exit code 0 is valid with score 1, anything else invalid; its output is the detail."""
    argv = shlex.split(command) if isinstance(command, str) else list(command)

    def check(path, cwd=None, env=None):
        if path is None:
            return "invalid", None, "no answer"
        try:
            p = subprocess.run(argv + [path], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, universal_newlines=True,
                               timeout=timeout, cwd=cwd, env=env)
        except subprocess.TimeoutExpired:
            raise RuntimeError(f"the judge did not finish within {timeout}s")
        tail = "\n".join(p.stdout.strip().splitlines()[-8:])
        return ("valid", 1, tail) if p.returncode == 0 else ("invalid", None, tail or f"exit code {p.returncode}")
    return check


def used(before, after):
    return after - before if isinstance(before, int) and isinstance(after, int) else None


class CoopRun:
    """One run of one mode. members: an object with run_turn(name, prompt, timeout=...) -> (reply, state) and,
    optionally, tokens(name) (members.Members, or anything shaped like it)."""

    def __init__(self, task, judge, members, names, out, mode="C", rounds=3, results=3, failures=3, answer_bytes=6000,
                 answer_name="answer.txt", turn_timeout=900, judge_name="judge", stop_on_infra_error=False):
        if mode not in MODES:
            raise ValueError(f"mode: one of {', '.join(MODES)}")
        if not names:
            raise ValueError("no members")
        if not (isinstance(rounds, int) and rounds >= 1):
            raise ValueError("rounds: 1 or more")
        self.task, self.judge, self.members, self.names, self.mode, self.rounds = task, judge, members, list(names), mode, rounds
        self.results, self.failures, self.answer_bytes, self.answer_name = results, failures, answer_bytes, answer_name
        self.turn_timeout, self.judge_name, self.out = turn_timeout, judge_name, out
        self.stop_on_infra_error, self.stopped = stop_on_infra_error, None
        os.makedirs(out, exist_ok=True)
        self.kb = TeamKB(os.path.join(out, "kb"))
        self.scope = "team" if mode == "C" else "private"
        self.turns, self.progress = [], []
        self.log = open(os.path.join(out, "run.jsonl"), "a", encoding="utf-8", buffering=1)

    def waves(self):
        """S: one member, one turn per wave, as many turns as the team would get; I and C: every member every round."""
        if self.mode == "S":
            return [[self.names[0]] for _ in range(len(self.names) * self.rounds)]
        return [list(self.names) for _ in range(self.rounds)]

    def prompt(self, member, wave):
        brief, shown = self.kb.brief(member, self.results, self.failures, round=wave, answer_bytes=self.answer_bytes,
                                     with_ids=True)
        intro = TEAM.format(member=member, n=len(self.names)) if self.mode == "C" else ALONE
        unit = "turn" if self.mode == "S" else "round"
        return PROMPT.format(intro=intro, unit=unit, wave=wave, waves=len(self.waves()), task=self.task.strip(), brief=brief,
                             reply=REPLY), shown

    def turn(self, member, prompt, out):
        before, start = self.tokens(member), time.time()
        try:
            text, state = self.members.run_turn(member, prompt, timeout=self.turn_timeout)
        except Exception as exc:  # a member backend that breaks fails its turn; the run goes on
            text, state = f"({type(exc).__name__}: {exc})", "error"
        out[member] = (text, state, round(time.time() - start, 2), used(before, self.tokens(member)))

    def tokens(self, member):
        try:
            return self.members.tokens(member) if hasattr(self.members, "tokens") else None
        except Exception:  # counting tokens must never fail a turn
            return None

    def run(self):
        started = time.time()
        for wave, members in enumerate(self.waves(), 1):
            prompts = {m: self.prompt(m, wave) for m in members}  # built before anyone in this round runs
            replies = {}
            threads = [threading.Thread(target=self.turn, args=(m, prompts[m][0], replies)) for m in members]
            for t in threads:
                t.start()
            for t in threads:
                t.join()
            done = [self.record(m, wave, prompts[m][1], *replies[m]) for m in members]  # in member order, whoever finished first
            self.progress.append({"round": wave, "turns": len(self.turns), "best": self.kb.stats()["best"]})
            self.view()
            broken = [infra_problem(t) for t in done if infra_problem(t)]
            if broken and self.stop_on_infra_error:
                self.stopped = {"round": wave, "of": len(self.waves()), "why": broken}
                break
        self.log.close()
        summary = self.summary(time.time() - started)
        tmp = os.path.join(self.out, "summary.json.tmp")
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(summary, handle, ensure_ascii=False, indent=1)
        os.replace(tmp, os.path.join(self.out, "summary.json"))
        self.view()
        return summary

    def view(self):
        """Write view.html; a page that cannot be written is reported, it never ends the run."""
        try:
            coopview.save(self.out)
        except Exception as exc:  # noqa: BLE001 - the page is for people; the run's records are what count
            print(f"herdr-py coop: warning: view.html not written: {type(exc).__name__}: {exc}", file=sys.stderr)

    def record(self, member, wave, shown, text, state, seconds, tokens):
        turn = {"t": round(time.time(), 3), "round": wave, "member": member, "state": state, "seconds": seconds,
                "tokens": tokens}
        parsed = parse_reply(text) if state == "idle" else None
        if parsed is None:
            turn["problem"] = f"the turn ended {state}" + (f": {one_line(text, 300)}" if text else "")
        elif parsed["kind"] is None:
            turn["problem"] = "no fenced answer and no FAILED line"
            turn["reply_tail"] = text[-300:]
        else:
            parents = [p for p in parsed["parents"] if p in shown]
            before = len(self.kb)
            eid = self.kb.propose(member, parsed["kind"], one_line(parsed["summary"], 500), artifact=parsed["answer"],
                                  name=self.answer_name, parents=parents, round=wave, scope=self.scope)
            turn.update(entry=eid, kind=parsed["kind"], parents=parents, repeat=len(self.kb) == before)
            dropped = [p for p in parsed["parents"] if p not in shown]
            if dropped:
                turn["parents_dropped"] = dropped  # named but never shown to this member: not counted as built on
            if parsed["kind"] == "result":
                known = self.kb.verdict(eid) if turn["repeat"] else None
                status, score = known or self.kb.judge(eid, self.judge, judge=self.judge_name)
                turn.update(status=status, score=score)
        self.turns.append(turn)
        self.log.write(json.dumps(turn, ensure_ascii=False) + "\n")
        return turn

    def summary(self, seconds):
        s = self.kb.stats()
        valid = [e for e in self.kb.entries() if e["status"] == "valid"]
        best = max(valid, key=lambda e: (e["score"], -e["t"]), default=None)
        known = [t["tokens"] for t in self.turns if t["tokens"] is not None]
        summary = {"mode": self.mode, "members": self.names[:1] if self.mode == "S" else self.names, "rounds": self.rounds,
                   "turns": len(self.turns), "turn_states": dict(collections.Counter(t["state"] for t in self.turns)),
                   "answers": sum(1 for t in self.turns if t.get("kind") == "result"),
                   "failures_reported": sum(1 for t in self.turns if t.get("kind") == "failure"),
                   "repeats": sum(1 for t in self.turns if t.get("repeat")),
                   "no_answer": sum(1 for t in self.turns if t["state"] == "idle" and "problem" in t),
                   "valid": s["valid"], "invalid": s["invalid"], "judge_errors": s["infra_error"],
                   "best": best["score"] if best else None, "best_entry": best["id"] if best else None,
                   "best_member": best["member"] if best else None, "best_by_member": s["best_by_member"],
                   "adoption_rate": s["adoption_rate"], "improved_after_adoption": s["improved_after_adoption"],
                   "duplicate_rate": s["duplicate_rate"],
                   "parents_dropped": sum(len(t.get("parents_dropped", [])) for t in self.turns),
                   "progress": self.progress, "stopped": self.stopped, "seconds": round(seconds, 1),
                   "tokens": sum(known) if known else None, "tokens_known_for_turns": len(known)}
        if hasattr(self.members, "summary"):
            summary["member_stats"] = self.members.summary()
        return summary


def infra_problem(turn):
    """Why this turn shows that the setup broke (a member's backend or the judge), or None."""
    if turn["state"] in ("error", "aborted"):
        return f"{turn['member']} round {turn['round']}: the member's backend ended {turn['state']}"
    if turn.get("status") == "infra_error":
        return f"{turn['member']} round {turn['round']}: the judge failed on entry {turn['entry']}"
    return None


def report(summary, out):
    s = summary
    rate = lambda v: "-" if v is None else f"{v:.2f}"  # noqa: E731
    lines = [f"mode {s['mode']}: {s['turns']} turns ({', '.join(f'{n} {k}' for k, n in sorted(s['turn_states'].items()))}); "
             f"{s['answers']} answers: {s['valid']} valid, {s['invalid']} invalid, {s['judge_errors']} judge errors; "
             f"{s['failures_reported']} failures reported, {s['no_answer']} replies without an answer, "
             f"{s['repeats']} repeats of the member's own earlier entry",
             (f"best {s['best']:.10g} ({s['best_entry']} by {s['best_member']})" if s["best"] is not None else "no valid answer")
             + f"; adoption {rate(s['adoption_rate'])}, improved after adoption {rate(s['improved_after_adoption'])}, "
               f"duplicates {rate(s['duplicate_rate'])}, parents dropped {s['parents_dropped']}",
             "best after each round: " + ", ".join("-" if p["best"] is None else f"{p['best']:.6g}" for p in s["progress"]),
             f"tokens: {s['tokens'] if s['tokens'] is not None else 'not reported'}; {s['seconds']} s",
             f"entries: python3 -m herdr_py.teamkb {os.path.join(out, 'kb')}",
             f"every turn on one page: {os.path.join(out, 'view.html')}"]
    if s.get("stopped"):
        lines.insert(0, f"STOPPED after round {s['stopped']['round']} of {s['stopped']['of']}: " + "; ".join(s["stopped"]["why"]))
    return "\n".join(lines)


def main(argv=None):
    ap = argparse.ArgumentParser(prog="python3 -m herdr_py.coop", description=__doc__.split("\n\n")[0])
    ap.add_argument("--task", required=True, metavar="FILE", help="the task, as text the members read")
    ap.add_argument("--judge", required=True, metavar="COMMAND", help="the judge; the answer file is added as its last argument")
    ap.add_argument("--judge-mode", choices=["json", "exit"], default="json", help="how the judge reports (see above)")
    ap.add_argument("--judge-timeout", type=int, default=120, metavar="S")
    ap.add_argument("--member", action="append", default=[], metavar="NAME=BACKEND[:MODEL]",
                    help="a member: NAME=opencode|codex|claude[:MODEL] or NAME=command:COMMAND (repeat for each member)")
    ap.add_argument("--mode", choices=MODES, default="C", help="S single, I independent, C cooperative (default)")
    ap.add_argument("--rounds", type=int, default=3)
    ap.add_argument("--out", required=True, metavar="DIR", help="a new folder for this run")
    ap.add_argument("--socket", help="the herdr-py daemon's socket (opencode members)")
    ap.add_argument("--sessions", choices=["fresh", "keep"], default="fresh",
                    help="fresh (default): every turn is a new conversation; keep: members keep theirs")
    ap.add_argument("--turn-timeout", type=int, default=900, metavar="S")
    ap.add_argument("--show-results", type=int, default=3, metavar="N", help="verified answers in each brief")
    ap.add_argument("--show-failures", type=int, default=3, metavar="N", help="failures in each brief")
    ap.add_argument("--answer-bytes", type=int, default=6000, metavar="N", help="show answers up to this size (0: never)")
    ap.add_argument("--stop-on-infra-error", action="store_true",
                    help="end the run after a round in which a member's backend or the judge broke (exit code 3)")
    ap.add_argument("--answer-name", default="answer.txt", help="the answer file's name (its extension matters to some judges)")
    a = ap.parse_args(argv)
    problems = []
    if a.rounds < 1:
        problems.append("--rounds: 1 or more")
    if not a.member:
        problems.append("--member: give at least one")
    for path in ("run.jsonl", "kb", "summary.json"):
        if os.path.exists(os.path.join(a.out, path)):
            problems.append(f"--out: {a.out} already holds a run ({path}); give a new folder")
            break
    try:
        specs = [parse_member(m) for m in a.member]
        with open(a.task, encoding="utf-8") as handle:
            task = handle.read()
    except (MemberError, OSError) as exc:
        problems.append(str(exc))
    if problems:
        print("herdr-py coop: " + "; ".join(problems), file=sys.stderr)
        return 2
    try:
        members = Members(specs, os.path.join(a.out, "members"), socket=a.socket, sessions=a.sessions)
    except MemberError as exc:
        print(f"herdr-py coop: {exc}", file=sys.stderr)
        return 2
    judge = (command_judge if a.judge_mode == "json" else exit_judge)(a.judge, timeout=a.judge_timeout)
    names = members.names()
    if a.mode == "S" and len(names) > 1:
        print(f"mode S: {names[0]} gets all {len(names) * a.rounds} turns; {', '.join(names[1:])} do not run")
    run = CoopRun(task, judge, members, names, a.out, mode=a.mode, rounds=a.rounds, results=a.show_results,
                  failures=a.show_failures, answer_bytes=a.answer_bytes, answer_name=a.answer_name,
                  turn_timeout=a.turn_timeout, judge_name=a.judge, stop_on_infra_error=a.stop_on_infra_error)
    try:
        summary = run.run()
    finally:
        members.close()
    print(report(summary, a.out))
    return 3 if summary["stopped"] else 0


if __name__ == "__main__":
    sys.exit(main())
HERDR_PY_EOF
cat > herdr_py/coopview.py <<'HERDR_PY_EOF'
"""One HTML page for a cooperative run (coop.py): every member's every turn at a glance, to see what went wrong.

    python3 -m herdr_py.coopview RUN_DIR                 # writes RUN_DIR/view.html
    python3 -m herdr_py.coopview RUN_DIR --html page.html

coop.py writes RUN_DIR/view.html itself after every round, so the page can be opened while the run goes on (reload it).
The page is one file with its style inside and no script: it opens from disk anywhere. It only reads the run folder:
  run.jsonl              every turn: state, seconds, tokens, entry, verdict, parents, problems
  kb/events.jsonl        the entries (summaries, the judge's reasons, who built on whom)
  summary.json           the totals, once the run has ended (or stopped)
  members/codex/events.jsonl, members/claude/events.jsonl
                         the backends' logs: how many commands a Codex member ran in a turn, and how a turn that did
                         not end normally ended (exit code, the last lines of stderr)
Rows are rounds and columns are members, so a single-member run (mode S) is one column. Every text that came from a
member or a judge is escaped. Standard library only; Python 3.6+.
"""
import argparse
import collections
import html
import json
import os
import sys

from .viewstyle import TOKENS

SCORE_DIGITS = 13  # scores that differ in the 10th digit must not look equal

STYLE = TOKENS + """
:root { font-family: system-ui, -apple-system, "Segoe UI", "PingFang TC", "Noto Sans CJK TC", sans-serif; }
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--text); }
body { font-size: 15px; line-height: 1.45; }
main { max-width: 1400px; margin: 0 auto; padding: 12px 16px 48px; }
h1 { font-size: 20px; margin: 4px 0; }
h2 { font-size: 14px; color: var(--muted); margin: 22px 0 8px; text-transform: uppercase; letter-spacing: .04em; }
.sub { color: var(--muted); font-size: 14px; overflow-wrap: anywhere; }
.stopped { margin: 10px 0; padding: 10px 14px; border: 2px solid var(--bad); border-radius: 10px; font-weight: 600; }
.tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 8px; }
.tile { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 8px 12px;
  box-shadow: inset 0 1px 0 var(--hi); }
.tile b { display: block; font-size: 20px; font-variant-numeric: tabular-nums; }
.tile span { color: var(--muted); font-size: 13px; }
.tile.bad b { color: var(--bad); }
.wrap { overflow-x: auto; }
table { border-collapse: separate; border-spacing: 6px; }
th { color: var(--muted); font-size: 13px; font-weight: 600; text-align: left; padding: 0 4px; white-space: nowrap; }
td.cell { vertical-align: top; min-width: 220px; max-width: 340px; background: var(--panel); border: 1px solid var(--line);
  border-left: 5px solid var(--idle); border-radius: 8px; padding: 6px 10px; }
td.cell.valid { border-left-color: var(--ok); }
td.cell.invalid, td.cell.failure, td.cell.noanswer, td.cell.timeout { border-left-color: var(--warn); }
td.cell.error, td.cell.aborted, td.cell.infra { border-left-color: var(--bad); }
td.cell.best { box-shadow: inset 0 0 0 2px var(--ok); }
.badge { display: inline-block; padding: 1px 8px; border-radius: 999px; font-size: 13px; font-weight: 600;
  background: var(--idle); color: var(--chip-ink); }
.valid .badge { background: var(--ok); } .error .badge, .aborted .badge, .infra .badge { background: var(--bad); }
.invalid .badge, .failure .badge, .noanswer .badge, .timeout .badge { background: var(--warn); }
.score { font-weight: 700; font-variant-numeric: tabular-nums; margin-left: 6px; }
.meta { color: var(--muted); font-size: 13px; font-variant-numeric: tabular-nums; }
.from { font-size: 13px; margin-top: 2px; }
.why { font-size: 13px; margin-top: 4px; overflow-wrap: anywhere; }
details { margin-top: 4px; font-size: 13px; }
summary { cursor: pointer; color: var(--muted); }
pre { white-space: pre-wrap; overflow-wrap: anywhere; margin: 4px 0; padding: 6px; background: var(--bg);
  border-radius: 6px; font-size: 12px; max-height: 240px; overflow-y: auto; }
code { font-size: 12px; }
ul.plain { margin: 0; padding-left: 18px; }
ul.plain li { margin: 2px 0; overflow-wrap: anywhere; }
table.list { border-spacing: 0; width: 100%; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; }
table.list td.nw { white-space: nowrap; }
table.list td.id { white-space: nowrap; font-family: ui-monospace, Menlo, monospace; font-size: 12px; }
table.list th, table.list td { padding: 5px 8px; border-bottom: 1px solid var(--line); font-size: 13px; text-align: left;
  vertical-align: top; overflow-wrap: anywhere; }
svg text { fill: var(--muted); font-size: 12px; }
.legend { color: var(--muted); font-size: 13px; margin: 4px 0 0; }
"""


def esc(value):
    return html.escape("" if value is None else str(value), quote=True)


def read_jsonl(path):
    rows, bad = [], 0
    if os.path.exists(path):
        with open(path, encoding="utf-8", errors="replace") as handle:
            for line in handle:
                if not line.strip():
                    continue
                try:
                    rows.append(json.loads(line))
                except ValueError:
                    bad += 1  # a line still being written
    return rows, bad


def entries_of(run_dir):
    proposals, verdicts = collections.OrderedDict(), {}
    for e in read_jsonl(os.path.join(run_dir, "kb", "events.jsonl"))[0]:
        if e.get("type") == "propose" and e.get("id") not in proposals:
            proposals[e["id"]] = e
        elif e.get("type") == "verdict" and e.get("id") in proposals:
            verdicts[e["id"]] = e
    out = collections.OrderedDict()
    for eid, p in proposals.items():
        v = verdicts.get(eid, {})
        out[eid] = dict(p, status=v.get("status", "unjudged"), score=v.get("score"), detail=v.get("detail", ""))
    first = {}
    for e in out.values():
        e["adopted_by"] = [c["id"] for c in out.values() if e["id"] in (c.get("parents") or [])]
        e["duplicate_of"] = first.get(e.get("sha")) if e.get("sha") else None
        if e.get("sha") and e["sha"] not in first:
            first[e["sha"]] = e["id"]
    return out


def backend_turns(run_dir):
    """member -> [one dict per turn the backend started]: commands run, exit row (non-normal ends), from the logs of
    the Codex and Claude backends. The n-th turn a backend started for a member is that member's n-th turn."""
    found = collections.defaultdict(list)
    for kind in ("codex", "claude"):
        rows = read_jsonl(os.path.join(run_dir, "members", kind, "events.jsonl"))[0]
        for row in rows:
            name = row.get("agent")
            if name is None:
                continue
            if "argv" in row:
                found[name].append({"backend": kind, "commands": 0, "exit": None, "timeout": None, "stderr": ""})
                continue
            if not found[name]:
                continue
            turn = found[name][-1]
            event = row.get("event") or {}
            if event.get("type") == "item.completed" and (event.get("item") or {}).get("type") == "command_execution":
                turn["commands"] += 1
            if "exit" in row:
                turn.update(exit=row.get("exit"), timeout=row.get("timeout"), stderr=row.get("stderr") or "")
    return found


def outcome(turn, entries):
    """(css class, badge text, one line saying why) for a turn."""
    state = turn.get("state")
    if state != "idle":
        return state if state in ("timeout", "error", "aborted") else "error", state, turn.get("problem", "")
    if "problem" in turn:
        return "noanswer", "no answer", turn["problem"]
    entry = entries.get(turn.get("entry"), {})
    if turn.get("kind") == "failure":
        return "failure", "FAILED", entry.get("summary", "")
    status = turn.get("status")
    if status == "valid":
        return "valid", "valid", ""
    if status == "invalid":
        return "invalid", "invalid", entry.get("detail", "")
    if status == "infra_error":
        return "infra", "judge error", entry.get("detail", "")
    return "noanswer", status or "?", ""


def fmt_num(value, digits=6):
    if value is None:
        return "-"
    if isinstance(value, float):
        return f"{value:.{digits}g}"
    return str(value)


def fmt_tokens(value):
    if value is None:
        return "tokens -"
    return f"{value / 1000:.1f}k tok" if value >= 1000 else f"{value} tok"


def cell(turn, entries, backend, best_id, unit="round"):
    css, badge, why = outcome(turn, entries)
    entry = entries.get(turn.get("entry"), {})
    classes = ["cell", css] + (["best"] if best_id and turn.get("entry") == best_id else [])
    head = f'<span class="badge">{esc(badge)}</span>'
    if turn.get("score") is not None:
        head += f'<span class="score">{esc(fmt_num(turn["score"], SCORE_DIGITS))}</span>'
    if turn.get("repeat"):
        head += ' <span class="meta" title="the same entry again: recorded once, not judged again">resent</span>'
    meta = [f"{turn.get('seconds', 0):.0f} s", fmt_tokens(turn.get("tokens"))]
    if backend is not None:
        meta.append(f"{backend['commands']} commands")
    parts = [head, f'<div class="meta">{esc(" · ".join(meta))}</div>']
    if turn.get("entry"):
        parts.append(f'<div class="meta"><code>{esc(turn["entry"])}</code></div>')
    for parent in turn.get("parents") or []:
        p = entries.get(parent, {})
        mine = p.get("member") == turn.get("member")
        parts.append(f'<div class="from">{"↳ own" if mine else "↳ built on"} <code>{esc(parent)}</code> by {esc(p.get("member"))} '
                     f'({unit} {esc(p.get("round"))}, {esc(fmt_num(p.get("score"), SCORE_DIGITS))})</div>')
    if turn.get("parents_dropped"):
        parts.append(f'<div class="why">named entries it was never shown (ignored): {esc(", ".join(turn["parents_dropped"]))}</div>')
    if why:
        parts.append(f'<div class="why">{esc(why[:400])}</div>')
    more = []
    if entry.get("summary") and turn.get("kind") == "result":
        more.append(f"<div>summary: {esc(entry['summary'])}</div>")
    if turn.get("reply_tail"):
        more.append(f"<div>end of the reply:</div><pre>{esc(turn['reply_tail'])}</pre>")
    if backend is not None and (backend["exit"] is not None or backend["timeout"]):
        line = f"exit {backend['exit']}" + (f", stopped at the {backend['timeout']} s limit" if backend["timeout"] else "")
        more.append(f"<div>{esc(backend['backend'])}: {esc(line)}</div>")
        if backend["stderr"].strip():
            more.append(f"<pre>{esc(backend['stderr'][-500:])}</pre>")
    if more:
        parts.append("<details><summary>details</summary>" + "".join(more) + "</details>")
    return f'<td class="{" ".join(classes)}">' + "".join(parts) + "</td>"


def progress_svg(progress):
    """Best verified score after each round, as a small line chart (or nothing to draw)."""
    points = [(i + 1, p) for i, p in enumerate(progress) if p is not None]
    if not points:
        return '<p class="sub">No verified answer yet.</p>'
    w, h, pad = 640, 160, 36
    lo, hi = min(p for _, p in points), max(p for _, p in points)
    span = (hi - lo) or abs(hi) or 1.0
    lo, hi = lo - span * 0.1, hi + span * 0.1
    n = max(len(progress), 2)
    x = lambda i: pad + (w - 2 * pad) * (i - 1) / (n - 1)  # noqa: E731
    y = lambda v: h - pad + (pad * 2 - h) * (v - lo) / (hi - lo)  # noqa: E731
    line = " ".join(f"{x(i):.1f},{y(v):.1f}" for i, v in points)
    dots = "".join(f'<circle cx="{x(i):.1f}" cy="{y(v):.1f}" r="3.5" fill="var(--accent)"><title>round {i}: {v:.10g}</title></circle>'
                   for i, v in points)
    top, bottom = max(p for _, p in points), min(p for _, p in points)
    labels = (f'<text x="{pad}" y="{h - 8}">round 1</text><text x="{w - pad}" y="{h - 8}" text-anchor="end">round {len(progress)}</text>'
              f'<text x="4" y="{y(top) - 6:.1f}">{top:.{SCORE_DIGITS}g}</text>'
              + (f'<text x="4" y="{y(bottom) + 16:.1f}">{bottom:.{SCORE_DIGITS}g}</text>' if bottom != top else ""))
    scale = (f'<p class="legend">The axis does not start at 0: from the first to the best point is {top - bottom:+.3g}.</p>'
             if bottom != top else "")
    return (f'<svg viewBox="0 0 {w} {h}" width="{w}" height="{h}" role="img" aria-label="best verified score after each round">'
            f'<polyline points="{line}" fill="none" stroke="var(--accent)" stroke-width="2"/>{dots}{labels}</svg>' + scale)


def build(run_dir):
    """The page as a string."""
    turns, bad_lines = read_jsonl(os.path.join(run_dir, "run.jsonl"))
    entries = entries_of(run_dir)
    summary = None
    if os.path.exists(os.path.join(run_dir, "summary.json")):
        with open(os.path.join(run_dir, "summary.json"), encoding="utf-8") as handle:
            summary = json.load(handle)
    backends = backend_turns(run_dir)
    members = list(collections.OrderedDict.fromkeys(t["member"] for t in turns))
    if summary and summary.get("members"):
        members = list(collections.OrderedDict.fromkeys(list(summary["members"]) + members))
    by_cell, seen = {}, collections.Counter()
    for t in turns:
        index = seen[t["member"]]
        seen[t["member"]] += 1
        found = backends.get(t["member"]) or []
        by_cell[(t["round"], t["member"])] = (t, found[index] if index < len(found) else None)
    rounds = sorted({t["round"] for t in turns})
    valid = [e for e in entries.values() if e["status"] == "valid"]
    best = max(valid, key=lambda e: e["score"], default=None)
    mode = (summary or {}).get("mode", "?")
    counts = collections.Counter(outcome(t, entries)[0] for t in turns)
    tokens = [t["tokens"] for t in turns if t.get("tokens") is not None]
    tiles = [("best verified score", fmt_num(best["score"], SCORE_DIGITS) if best else "-", ""),
             ("turns", len(turns), ""), ("valid answers", counts["valid"], ""),
             ("invalid", counts["invalid"], "bad" if counts["invalid"] else ""),
             ("no answer / FAILED", counts["noanswer"] + counts["failure"], "bad" if counts["noanswer"] + counts["failure"] else ""),
             ("timeouts", counts["timeout"], "bad" if counts["timeout"] else ""),
             ("backend or judge errors", counts["error"] + counts["aborted"] + counts["infra"],
              "bad" if counts["error"] + counts["aborted"] + counts["infra"] else ""),
             ("tokens", f"{sum(tokens):,}" if tokens else "-", ""),
             ("seconds in turns", f"{sum(t.get('seconds', 0) for t in turns):,.0f}", "")]
    if summary:
        rate = lambda v: "-" if v is None else f"{v:.2f}"  # noqa: E731
        tiles += [("adoption rate", rate(summary.get("adoption_rate")), ""),
                  ("improved after adoption", rate(summary.get("improved_after_adoption")), ""),
                  ("duplicate rate", rate(summary.get("duplicate_rate")), "")]
    out = ["<!doctype html>", '<html lang="en"><head><meta charset="utf-8">',
           '<meta name="viewport" content="width=device-width, initial-scale=1">',
           f"<title>coop {esc(mode)} · {esc(os.path.basename(os.path.abspath(run_dir)))}</title>",
           f"<style>{STYLE}</style></head><body><main>",
           f"<h1>Cooperative run · mode {esc(mode)}</h1>",
           f'<div class="sub">{esc(os.path.abspath(run_dir))} · {len(members)} member(s) · {len(rounds)} round(s)'
           + ("" if summary else " · <b>still running</b> (reload for news)") + "</div>"]
    stopped = (summary or {}).get("stopped")
    if stopped:
        out.append(f'<div class="stopped">Stopped after round {esc(stopped.get("round"))} of {esc(stopped.get("of"))}: '
                   + esc("; ".join(stopped.get("why") or [])) + "</div>")
    if bad_lines:
        out.append(f'<div class="sub">{bad_lines} line(s) of run.jsonl could not be read (still being written?)</div>')
    out.append('<div class="tiles">' + "".join(
        f'<div class="tile {css}"><b>{esc(v)}</b><span>{esc(k)}</span></div>' for k, v, css in tiles) + "</div>")
    out.append("<h2>Every turn</h2>")
    out.append('<p class="legend">green: valid · amber: invalid, FAILED, no answer or timeout · red: the backend or the '
               'judge broke · outlined: the best answer · “built on” names a teammate\'s entry; “own” its own earlier one</p>')
    out.append('<div class="wrap"><table><tr><th></th>' + "".join(f"<th>{esc(m)}</th>" for m in members) + "</tr>")
    for r in rounds:
        row = [f"<th>{'turn' if mode == 'S' else 'round'} {esc(r)}</th>"]
        for m in members:
            if (r, m) in by_cell:
                t, b = by_cell[(r, m)]
                row.append(cell(t, entries, b, best["id"] if best else None, "turn" if mode == "S" else "round"))
            else:
                row.append("<td></td>")
        out.append("<tr>" + "".join(row) + "</tr>")
    out.append("</table></div>")
    out.append("<h2>Best after each round</h2>")
    progress = [p.get("best") for p in (summary or {}).get("progress", [])]
    if not progress:  # still running: from the turns so far
        best_so_far, progress = None, []
        for r in rounds:
            for (rr, _), (t, _) in by_cell.items():
                if rr == r and t.get("status") == "valid" and t.get("score") is not None:
                    best_so_far = t["score"] if best_so_far is None else max(best_so_far, t["score"])
            progress.append(best_so_far)
    out.append(progress_svg(progress))
    edges = []
    for e in entries.values():
        for parent in e.get("parents") or []:
            p = entries.get(parent)
            if p and p.get("member") != e.get("member"):
                gain = (e["score"] - p["score"]) if e.get("score") is not None and p.get("score") is not None else None
                edges.append(f"<li>{esc(e['member'])} (round {esc(e.get('round'))}, {esc(e['status'])}) built on "
                             f"{esc(p['member'])}'s <code>{esc(parent)}</code> (round {esc(p.get('round'))})"
                             + ("" if gain is None else f": {gain:+.6g}") + "</li>")
    out.append("<h2>Who built on whom</h2>")
    out.append('<ul class="plain">' + ("".join(edges) or "<li>No member built on a teammate's entry.</li>") + "</ul>")
    out.append("<h2>Entries in the knowledge base</h2>")
    out.append('<div class="wrap"><table class="list"><tr><th>id</th><th>member</th><th>round</th><th>kind</th><th>verdict</th>'
               "<th>parents</th><th>used by</th><th>repeats</th><th>summary / judge</th></tr>")
    for e in entries.values():
        verdict = e["status"] + (f" {fmt_num(e['score'], SCORE_DIGITS)}" if e.get("score") is not None else "")
        text = e.get("summary", "") + (f" — {e['detail']}" if e.get("detail") and e["status"] != "valid" else "")
        ids = lambda values: "<br>".join(esc(v) for v in values)  # noqa: E731
        out.append(f'<tr><td class="id">{esc(e["id"])}</td><td class="nw">{esc(e.get("member"))}</td><td class="nw">{esc(e.get("round"))}</td>'
                   f'<td class="nw">{esc(e.get("kind"))}</td><td>{esc(verdict)}</td><td class="id">{ids(e.get("parents") or [])}</td>'
                   f'<td class="id">{ids(e["adopted_by"])}</td><td class="id">{esc(e["duplicate_of"] or "")}</td>'
                   f"<td>{esc(text[:300])}</td></tr>")
    out.append("</table></div>")
    out.append('<p class="sub">Written by herdr_py.coopview from run.jsonl, kb/ and the members\' logs; '
               "scores are the judge's, never a member's own claim.</p></main></body></html>")
    return "\n".join(out)


def save(run_dir, out_path=None):
    """Write the page (atomically) and return its path."""
    out_path = out_path or os.path.join(run_dir, "view.html")
    page = build(run_dir)
    tmp = out_path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as handle:
        handle.write(page)
    os.replace(tmp, out_path)
    return out_path


def main(argv=None):
    ap = argparse.ArgumentParser(prog="python3 -m herdr_py.coopview", description=__doc__.split("\n\n")[0])
    ap.add_argument("run_dir", metavar="RUN_DIR", help="a folder made by python3 -m herdr_py.coop --out")
    ap.add_argument("--html", metavar="FILE", help="where to write the page (default RUN_DIR/view.html)")
    a = ap.parse_args(argv)
    if not os.path.isfile(os.path.join(a.run_dir, "run.jsonl")):
        print(f"herdr-py coopview: no run in {a.run_dir} (run.jsonl is missing)", file=sys.stderr)
        return 2
    print(save(a.run_dir, a.html))
    return 0


if __name__ == "__main__":
    sys.exit(main())
HERDR_PY_EOF
cat > herdr_py/core.py <<'HERDR_PY_EOF'
"""The hub: every agent herdr-py drives, kept in sync with OpenCode's own events.

State of an agent (what UIs show):
  starting  created, first prompt sent, OpenCode has not reported busy yet
  working   OpenCode says the session is busy
  retry     OpenCode is retrying a provider error
  blocked   a permission request or question (the agent's own or a subagent's) is waiting for an answer
  idle      the session is idle and no follow-up is queued
  aborted   herdr-py aborted it (time budget or a user request); the next prompt clears it
  error     OpenCode reported a session error; the next prompt clears it

Only sessions created by herdr-py (and their subagent sessions) are touched: requests from other sessions on the same
OpenCode server are ignored.
"""
import base64
import collections
import json
import mimetypes
import os
import queue
import threading
import time

from .policy import REPLIES, describe

CHILD_STATE_EVENTS = {"permission.asked", "permission.replied", "question.asked", "question.replied", "question.rejected"}
FINAL = {"idle", "aborted", "error"}
STATES = ("starting", "working", "retry", "blocked", "idle", "aborted", "error")


class HubError(Exception):
    pass


MAX_FILE_BYTES = 8 * 1024 * 1024


def file_parts(paths):
    """Local files -> OpenCode file parts with data URLs (read by the daemon, so paths are the daemon's paths)."""
    parts = []
    for path in paths or ():
        size = os.path.getsize(path)
        if size > MAX_FILE_BYTES:
            raise HubError(f"{path} is {size} bytes; attachments are limited to {MAX_FILE_BYTES}")
        mime = mimetypes.guess_type(path)[0] or "application/octet-stream"
        with open(path, "rb") as handle:
            data = base64.b64encode(handle.read()).decode()
        parts.append({"mime": mime, "url": f"data:{mime};base64,{data}", "filename": os.path.basename(path)})
    return parts


class Agent:
    def __init__(self, name, session_id, model=None, budget_s=None, followups=(), created=None, directory=None, deny=(),
                 tools=None):
        self.name, self.session_id, self.model = name, session_id, model
        self.directory = directory        # the folder its session works in, when not the server's (a DAG step's clone)
        self.deny = set(deny)             # permission kinds refused before the policy is asked (a step that only reads)
        self.tools = dict(tools or {})    # tool switches sent with every prompt ({"*": False}: no tools, it only answers)
        self.budget_s = budget_s
        self.followups = list(followups)
        self.created = created or time.time()
        self.base = "starting"            # from session.status / session.idle
        self.sticky = None                # "aborted" or "error" until the next prompt
        self.since = self.created
        self.history = []                 # [(t, state)]
        self.children = set()
        self.pending = collections.OrderedDict()   # request id -> {"kind": "permission"|"question", "request": ..., "child": bool}
        self.activity = collections.OrderedDict()  # key -> (t, text, tone)
        self.stream = {"part": None, "kind": "", "text": ""}
        self.tokens = 0
        self.turns = 0                    # prompts sent
        self.idles = 0                    # turns finished (busy -> idle)
        self.awaiting_busy = False        # a prompt was sent and OpenCode has not reported busy yet
        self.ending = False               # we aborted a turn OpenCode was working on, and its end has not arrived yet
        self.working_since = None         # start of the current busy period (for the time budget)
        self.decisions = []               # [(t, request id, description, action, by)]
        self.seq = 0                      # +1 on every state change (waits compare against a baseline, as in herdr)
        self.past_sessions = []           # earlier OpenCode sessions of this name (start with fresh=True)
        self.last_heard = None            # when OpenCode last said something about this agent (or a prompt was sent)
        self.retry_since = None           # set while OpenCode retries a failed call to the model provider
        self.provider_wait = 0.0          # seconds this session lost to the model provider (provider_retry)

    @property
    def state(self):
        if self.sticky:
            return self.sticky
        if self.pending:
            return "blocked"
        return self.base

    def view(self, now=None):
        now = now or time.time()
        return {"name": self.name, "session_id": self.session_id, "state": self.state, "since": round(self.since, 3),
                "seconds_in_state": round(now - self.since, 1), "tokens": self.tokens, "turns": self.turns,
                "followups_left": len(self.followups), "budget_s": self.budget_s, "children": sorted(self.children),
                "seq": self.seq, "completions": self.idles,
                "pending": [{"id": rid, "kind": p["kind"], "child": p["child"], "description": p["description"]}
                            for rid, p in self.pending.items()],
                "activity": [{"t": round(t, 3), "text": text, "tone": tone} for t, text, tone in list(self.activity.values())[-6:]],
                "stream": {"kind": self.stream["kind"], "text": self.stream["text"][-400:]},
                "model": self.model, "past_sessions": self.past_sessions[-5:], "directory": self.directory,
                "deny": sorted(self.deny), "tools": dict(self.tools), "provider_wait_s": round(self.provider_wait, 1)}


class Hub:
    def __init__(self, client, policy, log_path=None, state_path=None, model=None, questions="ask",
                 clock=time.time, run=None, max_queue=2000, max_agents=None, max_prompts=None, settle_s=5.0):
        self.max_agents, self.max_prompts = max_agents, max_prompts  # guards against a runaway manager agent
        self.client, self.policy, self.model = client, policy, model
        self.questions = questions        # "ask" or "reject"
        self.settle_s = settle_s          # how long a prompt after an abort waits for the aborted turn's end (settle)
        self.clock = clock
        self.run = run or (lambda fn: threading.Thread(target=fn, daemon=True).start())
        self.lock = threading.RLock()
        self.changed = threading.Condition(self.lock)
        self.agents = collections.OrderedDict()   # name -> Agent
        self.by_session = {}                      # root session id -> name
        self.child_root = {}                      # subagent session id -> root session id
        self.part_kind = {}                       # part id -> part type
        self.subscribers = []
        self.max_queue = max_queue
        self.state_path = state_path
        self.connected = False
        self.log = open(log_path, "a", encoding="utf-8", buffering=1) if log_path else None  # one line per write

    # ---------------------------------------------------------------- bookkeeping
    def record(self, entry):
        if self.log:
            self.log.write(json.dumps({"t": round(self.clock(), 3), **entry}, ensure_ascii=False) + "\n")

    def emit(self, event):
        event = {"t": round(self.clock(), 3), **event}
        dead = []
        for q in self.subscribers:
            try:
                q.put_nowait(event)
            except queue.Full:  # a subscriber that falls behind is told so and dropped, never silently skipped
                try:
                    q.get_nowait()
                    q.put_nowait({"t": event["t"], "type": "events_lost"})
                except (queue.Empty, queue.Full):
                    pass
                dead.append(q)
        for q in dead:
            self.subscribers.remove(q)
        self.changed.notify_all()

    def subscribe(self):
        q = queue.Queue(self.max_queue)
        with self.lock:
            self.subscribers.append(q)
        return q

    def unsubscribe(self, q):
        with self.lock:
            if q in self.subscribers:
                self.subscribers.remove(q)

    def note(self, agent, key, text, tone=""):
        agent.activity[key] = (self.clock(), text, tone)
        agent.activity.move_to_end(key)
        while len(agent.activity) > 12:
            agent.activity.popitem(last=False)

    def refresh(self, agent, reason=""):
        """Record a state change (if any) and tell subscribers."""
        state = agent.state
        if not agent.history or agent.history[-1][1] != state:
            agent.seq += 1
            agent.since = self.clock()
            agent.history.append((agent.since, state))
            self.record({"hub": "state", "agent": agent.name, "state": state, "reason": reason})
            self.emit({"type": "agent.state", "agent": agent.name, "state": state, "reason": reason})
        else:
            self.emit({"type": "agent.update", "agent": agent.name})

    def save(self):
        """Write the state file. The snapshot, the write and the rename happen under the hub's lock: two saves at once
        (two members started together) once shared the temporary file, and one rename found it gone."""
        if not self.state_path:
            return
        with self.lock:
            data = {"version": 1, "agents": [{"name": a.name, "session_id": a.session_id, "model": a.model, "budget_s": a.budget_s,
                                               "followups": a.followups, "turns": a.turns, "idles": a.idles, "created": a.created,
                                               "children": sorted(a.children), "past_sessions": a.past_sessions,
                                               "directory": a.directory, "deny": sorted(a.deny), "tools": a.tools}
                                              for a in self.agents.values()]}
            tmp = f"{self.state_path}.{os.getpid()}.tmp"
            with open(tmp, "w", encoding="utf-8") as handle:
                json.dump(data, handle, ensure_ascii=False, indent=1)
            os.replace(tmp, self.state_path)

    def close(self):
        if self.log:
            self.log.close()
            self.log = None

    # ---------------------------------------------------------------- public API
    def agent(self, name):
        agent = self.agents.get(name)
        if agent is None:
            raise HubError(f"no agent named {name!r}")
        return agent

    def list(self):
        with self.lock:
            now = self.clock()
            return [a.view(now) for a in self.agents.values()]

    def get(self, name):
        with self.lock:
            return self.agent(name).view(self.clock())

    def start(self, name, prompt, budget_s=None, followups=(), model=None, title=None, files=(), fresh=False, directory=None,
              deny=(), tools=None):
        """Create an agent (an OpenCode session) and send its first prompt. fresh=True with a name that exists gives that
        agent a new session instead: OpenCode compacts a long session at a moment nobody chooses, so a caller that puts
        everything the turn needs into the prompt can start every turn clean. The role's counters (tokens, turns,
        decisions) carry on; the old session and its subagents are dropped, and their late events are ignored.
        directory: the session works in that folder instead of the server's (OpenCode's ?directory=); deny: permission
        kinds this agent is refused whatever the policy says (["edit", "bash"] for a step that only reads); tools: OpenCode's
        tool switches, sent with every prompt to this agent ({"*": False}: no tools, for a turn that only answers)."""
        if tools is not None and not (isinstance(tools, dict) and all(isinstance(k, str) and isinstance(v, bool)
                                                                        for k, v in tools.items())):
            raise HubError('tools: {"tool name or *": true or false}')
        with self.lock:
            old = self.agents.get(name)
            if old is not None:
                if not fresh:
                    raise HubError(f"agent {name!r} already exists")
                if old.state not in FINAL or old.awaiting_busy:
                    raise HubError(f"agent {name!r} is {old.state}: abort it or wait for it before giving it a new session")
            elif self.max_agents is not None and len(self.agents) >= self.max_agents:
                raise HubError(f"max_agents ({self.max_agents}) reached")
        session = self.client.create_session(title or f"herdr-py: {name}", directory=directory)
        with self.lock:
            agent = Agent(name, session["id"], model or (old.model if old else self.model), budget_s, followups, created=self.clock(),
                          directory=directory, deny=deny, tools=tools)
            if old is not None:
                agent.tokens, agent.turns, agent.idles, agent.decisions = old.tokens, old.turns, old.idles, old.decisions
                agent.seq, agent.history = old.seq, old.history
                agent.past_sessions = old.past_sessions + [old.session_id]
                for sid in [old.session_id] + sorted(old.children):
                    self.by_session.pop(sid, None)
                    self.child_root.pop(sid, None)
            self.agents[name] = agent
            self.by_session[agent.session_id] = name
            self.record({"hub": "start", "agent": name, "session": agent.session_id,
                         **({"renewed_from": old.session_id} if old is not None else {})})
        self.save()
        self.prompt(name, prompt, source="start", files=files)
        return self.get(name)

    def settle(self, agent):
        """Called with the lock held: after an abort of a turn OpenCode was working on, wait (up to settle_s) for that
        turn's end. OpenCode reports it (MessageAbortedError, then idle) on its own time; arriving after the next prompt
        it was read as that turn's end, so a supervisor checked work that had not been done yet."""
        deadline = time.time() + self.settle_s
        while agent.ending and time.time() < deadline:
            self.changed.wait(min(0.5, max(0.0, deadline - time.time())))
        if agent.ending:
            agent.ending = False
            self.note(agent, f"unsettled-{self.clock()}", f"the aborted turn's end did not come in {self.settle_s:g} s", "warn")
            self.record({"hub": "unsettled", "agent": agent.name, "waited_s": self.settle_s})

    def prompt(self, name, text, source="user", files=()):
        parts = file_parts(files)  # read before changing any state, so a bad path leaves the agent as it was
        with self.lock:
            agent = self.agent(name)
            if self.max_prompts is not None and agent.turns >= self.max_prompts:
                raise HubError(f"max_prompts ({self.max_prompts}) reached for {name}")
            self.settle(agent)
            agent.sticky = None
            agent.awaiting_busy = True
            agent.last_heard = self.clock()  # silence from here on is either the model working or the provider stalling
            agent.turns += 1
            if agent.base in FINAL or agent.base == "starting":
                agent.base = "starting"
            self.note(agent, f"prompt-{agent.turns}", f"prompt #{agent.turns} ({source}): {text[:60]}", "info")
            self.record({"hub": "prompt", "agent": name, "source": source, "text": text})
            self.refresh(agent, "prompt")
            session_id, model, directory, tools = agent.session_id, agent.model, agent.directory, agent.tools
        self.client.prompt(session_id, text, model=model, files=parts, directory=directory, tools=tools)
        self.save()
        return self.get(name)

    def folder(self, directory):
        """The names OpenCode lists in `directory`; HubError when it cannot see that folder (an OpenCode in a container
        without the folder mounted at the same path)."""
        try:
            entries = self.client.files(".", directory=directory)
        except Exception as exc:
            raise HubError(f"OpenCode cannot list {directory}: {exc}") from None
        return sorted(e["name"] for e in entries if isinstance(e, dict) and e.get("name"))

    def abort(self, name, reason="user"):
        with self.lock:
            agent = self.agent(name)
            session_id, directory = agent.session_id, agent.directory
            agent.ending = agent.base in ("working", "retry") and not agent.awaiting_busy  # OpenCode will report its end
        try:
            self.client.abort(session_id, directory=directory)
        except Exception:
            with self.lock:
                agent.ending = False  # nothing was aborted, so no end is coming
            raise
        with self.lock:
            agent.sticky = "aborted"
            agent.followups = []
            agent.working_since = None
            self.note(agent, f"abort-{self.clock()}", f"aborted ({reason})", "warn")
            self.record({"hub": "abort", "agent": name, "reason": reason})
            self.refresh(agent, f"abort: {reason}")
        self.save()
        return self.get(name)

    def reply(self, request_id, reply, message=None, by="human"):
        """Answer a pending permission ("once"/"always"/"reject") or dismiss a pending question ("reject")."""
        with self.lock:
            agent, pending = self.find_pending(request_id)
            if pending is None:
                raise HubError(f"no pending request {request_id!r}")
        if pending["kind"] == "question":
            if reply != "reject":
                raise HubError("questions can only be dismissed (reply 'reject') in herdr-py 0.1")
            self.client.reject_question(request_id, directory=agent.directory)
        else:
            if reply not in ("once", "always", "reject"):
                raise HubError("reply must be once, always or reject")
            self.client.reply_permission(request_id, reply, message, directory=agent.directory)
        with self.lock:
            agent.decisions.append((self.clock(), request_id, pending["description"], reply, by))
            verdict = {"once": "allowed once", "always": "allowed always", "reject": "rejected"}[reply]
            self.note(agent, request_id, f"{'child ' if pending['child'] else ''}{pending['description'][:48]} -> {verdict} ({by})",
                      "ok" if reply != "reject" else "bad")
            self.record({"hub": "decision", "agent": agent.name, "request": request_id, "reply": reply, "by": by,
                         "description": pending["description"]})
            self.emit({"type": "permission.decided", "agent": agent.name, "request": request_id, "reply": reply, "by": by})
        return {"agent": agent.name, "request": request_id, "reply": reply}

    def find_pending(self, request_id):
        for agent in self.agents.values():
            if request_id in agent.pending:
                return agent, agent.pending[request_id]
        return None, None

    def pending(self, name=None):
        with self.lock:
            agents = [self.agent(name)] if name else list(self.agents.values())
            return [{"agent": a.name, "id": rid, "kind": p["kind"], "child": p["child"], "description": p["description"]}
                    for a in agents for rid, p in a.pending.items()]

    def prompt_and_wait(self, name, text, until=("idle",), timeout=None, activity_s=5.0, source="user", files=()):
        """Send a prompt and wait for the turn it starts to finish (herdr's `agent prompt --wait`).

        Within `activity_s` OpenCode must report the session busy (or a request); otherwise HubError("prompt_stalled"):
        the prompt may still have been delivered, so read the agent before sending it again. A finished turn means
        the completion count went past its value before the prompt; an idle from an older turn never counts.
        """
        with self.lock:
            baseline = self.agent(name).idles
        self.prompt(name, text, source=source, files=files)
        deadline = None if timeout is None else time.time() + timeout
        activity_deadline = time.time() + activity_s
        until = set(until)
        with self.lock:
            while True:
                agent = self.agent(name)
                started = not agent.awaiting_busy or agent.pending or agent.sticky
                if not started and time.time() > activity_deadline:
                    raise HubError(f"prompt_stalled: {name} showed no activity within {activity_s}s; "
                                   f"the prompt may still be delivered, read it before sending again")
                # `idles > baseline` is a second guard: on_idle already ignores idles while awaiting_busy, so an idle
                # from an older turn cannot get here (mutation testing found `>=` equivalent for that reason)
                if started and (agent.state in ("aborted", "error") or
                                (agent.state in until and (agent.state != "idle" or agent.idles > baseline))):
                    return agent.view(self.clock())
                if deadline is not None and time.time() > deadline:
                    raise HubError(f"timeout waiting for {name} to finish (state: {agent.state})")
                self.changed.wait(0.25)

    def wait(self, name, until=("idle",), timeout=None):
        """Block until the agent reaches one of the states in `until` (a prompt still waiting for OpenCode to start does
        not count as idle). Returns the agent view, or raises HubError on timeout."""
        until = set(until)
        deadline = None if timeout is None else time.time() + timeout
        with self.lock:
            while True:
                agent = self.agent(name)
                if agent.state in until and not (agent.awaiting_busy and agent.state == "idle"):
                    return agent.view(self.clock())
                remaining = None if deadline is None else deadline - time.time()
                if remaining is not None and remaining <= 0:
                    raise HubError(f"timeout waiting for {name} to reach {sorted(until)} (state: {agent.state})")
                self.changed.wait(0.5 if remaining is None else min(0.5, remaining))

    def transcript(self, name, limit=20):
        with self.lock:
            session_id, directory = self.agent(name).session_id, self.agent(name).directory
        out = []
        for message in (self.client.messages(session_id, directory=directory) or [])[-limit:]:
            role = (message.get("info") or {}).get("role", "?")
            for part in message.get("parts") or []:
                if part.get("type") == "text" and part.get("text"):
                    item = {"role": role, "kind": "text", "text": part["text"]}
                    if part.get("synthetic"):  # written by OpenCode itself: after compacting a session in the middle of
                        item["synthetic"] = True  # a turn it adds "Continue if you have next steps ...", not a prompt
                    out.append(item)
                elif part.get("type") == "compaction":
                    out.append({"role": role, "kind": "compaction"})
                elif part.get("type") == "tool":
                    state = part.get("state") or {}
                    out.append({"role": role, "kind": "tool", "tool": part.get("tool"), "status": state.get("status"),
                                "input": state.get("input"), "output": (state.get("output") or "")[-2000:]})
        return out

    # ---------------------------------------------------------------- automation (called every ~0.25 s)
    def tick(self):
        actions = []
        with self.lock:
            now = self.clock()
            for agent in self.agents.values():
                if agent.budget_s and agent.working_since and not agent.sticky and now - agent.working_since > agent.budget_s:
                    actions.append(("abort", agent.name, f"time budget {agent.budget_s}s"))
                    agent.working_since = None
                elif agent.followups and agent.state == "idle" and not agent.awaiting_busy and agent.idles >= agent.turns:
                    actions.append(("prompt", agent.name, agent.followups.pop(0)))
        for kind, name, arg in actions:
            try:
                if kind == "abort":
                    self.abort(name, reason=arg)
                else:
                    self.prompt(name, arg, source="follow-up")
            except Exception as exc:  # an automation that fails must be visible, not swallowed
                with self.lock:
                    agent = self.agents.get(name)
                    if agent:
                        self.note(agent, f"auto-error-{self.clock()}", f"automation failed: {exc}", "bad")
                        self.refresh(agent, "automation error")
                self.record({"hub": "automation_error", "agent": name, "action": kind, "error": str(exc)})

    # ---------------------------------------------------------------- OpenCode events
    def root_of(self, session_id, kind=None, props=None, directory=None):
        """Root session id for one of our sessions or its subagents; None for sessions we do not own."""
        if session_id in self.by_session:
            return session_id
        if session_id in self.child_root:
            return self.child_root[session_id]
        props = props or {}
        info = props.get("info") or {}
        parent = info.get("parentID") if kind in ("session.created", "session.updated") and info.get("id") == session_id else None
        if parent is None and kind in CHILD_STATE_EVENTS:  # a subagent's request can arrive before session.created
            try:
                parent = (self.client.session(session_id, directory=directory) or {}).get("parentID")
            except Exception:
                parent = None
        seen = 0
        while parent is not None and seen < 8:  # subagents can start their own subagents
            if parent in self.by_session or parent in self.child_root:
                root = parent if parent in self.by_session else self.child_root[parent]
                self.child_root[session_id] = root
                agent = self.agents[self.by_session[root]]
                agent.children.add(session_id)
                self.note(agent, f"child-{session_id}", f"subagent started ({session_id[-8:]})", "info")
                return root
            try:
                parent = (self.client.session(parent, directory=directory) or {}).get("parentID")
            except Exception:
                return None
            seen += 1
        return None

    def on_event(self, event):
        kind, props = event.get("type", ""), event.get("properties") or {}
        if kind in ("server.heartbeat", "server.connected"):
            return
        part = props.get("part") or {}
        session_id = props.get("sessionID") or part.get("sessionID") or (props.get("info") or {}).get("sessionID") \
            or (props.get("info") or {}).get("id")
        with self.lock:
            root = self.root_of(session_id, kind, props, event.get("directory")) if session_id else None
            if root is None:
                return
            if self.log and kind != "message.part.delta":
                self.record({"opencode": event})
            agent = self.agents[self.by_session[root]]
            now = self.clock()
            if kind == "session.status":
                status = props.get("status") or {}
                if status.get("type") == "retry":
                    self.provider_retry(agent, status, now)
                elif agent.retry_since is not None:  # working again, or the turn ended: the retry is over
                    agent.provider_wait += max(0.0, now - agent.retry_since)
                    agent.retry_since = None
            agent.last_heard = now
            self.handle(agent, kind, props, part, child=session_id != root)

    def provider_retry(self, agent, status, now):
        """OpenCode says a call to the model provider failed and it will retry (a provider timeout, a rate limit). The
        silence before this report, and the time until the session works again, were the provider's, not the agent's:
        provider_wait counts them, so a caller can leave them out of the agent's time limit. Only what the provider
        reported as a failure counts; a model that is merely slow to answer is the agent's own time."""
        since = agent.retry_since if agent.retry_since is not None else agent.last_heard
        if since is not None:
            agent.provider_wait += max(0.0, now - since)
        agent.retry_since = now
        message = str(status.get("message") or "")
        self.note(agent, f"provider-{now}", f"provider failed, retry {status.get('attempt')}: {message[:48]}", "warn")
        self.record({"hub": "provider_retry", "agent": agent.name, "attempt": status.get("attempt"), "message": message[:300],
                     "provider_wait_s": round(agent.provider_wait, 1)})

    def handle(self, agent, kind, props, part, child):
        if kind == "message.part.updated":
            self.part_kind[part.get("id")] = part.get("type")
            if part.get("type") == "tool":
                state = part.get("state") or {}
                inp = state.get("input") or {}
                target = inp.get("command") or inp.get("description") or state.get("title") or inp.get("filePath") or ""
                mark = {"completed": "done", "error": "failed"}.get(state.get("status"), "...")
                tone = {"completed": "", "error": "bad"}.get(state.get("status"), "dim")
                self.note(agent, part.get("callID"), f"{'child ' if child else ''}{part.get('tool')} {str(target)[:50]} {mark}", tone)
                self.emit({"type": "agent.update", "agent": agent.name})
            elif part.get("type") == "step-finish":
                agent.tokens += (part.get("tokens") or {}).get("total") or 0
            return
        if kind == "message.part.delta":
            if not child and props.get("field") == "text" and self.part_kind.get(props.get("partID")) in ("text", "reasoning"):
                if agent.stream["part"] != props["partID"]:
                    agent.stream = {"part": props["partID"], "text": "",
                                    "kind": "reasoning" if self.part_kind[props["partID"]] == "reasoning" else "reply"}
                agent.stream["text"] = (agent.stream["text"] + props.get("delta", ""))[-2000:]
                self.emit({"type": "agent.output", "agent": agent.name, "kind": agent.stream["kind"], "delta": props.get("delta", "")})
            return
        if kind == "permission.asked":
            self.on_request(agent, "permission", props, child)
            return
        if kind == "question.asked":
            self.on_request(agent, "question", props, child)
            return
        if kind in ("permission.replied", "question.replied", "question.rejected"):
            request_id = props.get("requestID") or props.get("id")
            if agent.pending.pop(request_id, None) is not None:
                self.refresh(agent, kind)
            return
        if child:
            return  # a subagent going busy or idle does not change its parent's state
        if kind == "session.status":
            status = (props.get("status") or {}).get("type")
            if status == "busy":
                self.on_busy(agent)
            elif status == "retry":
                agent.base = "retry"
                self.refresh(agent, "retry")
            elif status == "idle":
                self.on_idle(agent)
        elif kind == "session.idle":
            self.on_idle(agent)
        elif kind == "session.error":
            if agent.sticky != "aborted":
                agent.sticky = "error"
                error = props.get("error") or {}
                self.note(agent, f"error-{self.clock()}", f"error: {(error.get('data') or {}).get('message') or error.get('name') or error}"[:80], "bad")
            self.on_idle(agent, "session.error")  # an error ends the turn; the idle that usually follows is a duplicate

    def on_busy(self, agent):
        if agent.awaiting_busy or agent.base != "working":
            agent.awaiting_busy = False
            if agent.base != "retry":
                agent.working_since = self.clock()
            agent.base = "working"
            self.refresh(agent, "busy")

    def on_idle(self, agent, reason="idle"):
        if agent.awaiting_busy or agent.base == "idle":
            if agent.sticky and agent.history and agent.history[-1][1] != agent.state:
                self.refresh(agent, reason)
            return  # stale idle from before our prompt reached OpenCode, or a duplicate
        agent.base = "idle"
        agent.idles += 1
        agent.working_since = None
        agent.ending = False
        self.refresh(agent, reason)
        self.save()

    def on_request(self, agent, kind, props, child):
        request_id = props.get("id")
        if not request_id or request_id in agent.pending:
            return
        description = describe(props) if kind == "permission" else "question: " + "; ".join(
            q.get("question", "") for q in props.get("questions") or [])[:80]
        if kind == "permission" and props.get("permission") in agent.deny:
            action, message, rule = "deny", f"This step only reads: {props.get('permission')} is not allowed here.", "agent.deny"
        elif kind == "permission":
            action, message, rule = self.policy.decide(props, agent=agent.name)
        else:
            action, message, rule = ("deny", "dismissed", None) if self.questions == "reject" else ("ask", "", None)
        agent.pending[request_id] = {"kind": kind, "request": props, "child": child, "description": description,
                                     "asked": self.clock(), "action": action}
        self.note(agent, request_id, f"{'child ' if child else ''}asks: {description[:56]}", "warn")
        self.record({"hub": "asked", "agent": agent.name, "request": request_id, "kind": kind, "child": child,
                     "description": description, "policy": action, "rule": rule})
        self.emit({"type": "permission.asked", "agent": agent.name, "request": request_id, "kind": kind, "child": child,
                   "description": description, "policy": action})
        self.refresh(agent, f"{kind}.asked")
        if action != "ask":
            reply = REPLIES[action] if kind == "permission" else "reject"
            by = rule if rule == "agent.deny" else (f"policy rule {rule}" if rule is not None else "policy default")
            self.run(lambda: self.safe_reply(request_id, reply, message, by))

    def safe_reply(self, request_id, reply, message, by):
        try:
            self.reply(request_id, reply, message, by=by)
        except Exception as exc:
            self.record({"hub": "reply_error", "request": request_id, "error": str(exc)})
            with self.lock:
                agent, _ = self.find_pending(request_id)
                if agent:
                    self.note(agent, f"reply-error-{request_id}", f"could not answer {request_id}: {exc}"[:80], "bad")
                    self.refresh(agent, "reply error")

    # ---------------------------------------------------------------- reconnect / restart
    def on_stream_state(self, state, detail):
        with self.lock:
            self.connected = state == "connected"
            self.record({"hub": "stream", "state": state, "detail": detail})
            self.emit({"type": "server.stream", "state": state, "detail": detail})
        if state == "connected":
            self.run(self.resync)

    def resync(self):
        """Rebuild what may have been missed while the event stream was down: session states and pending requests."""
        with self.lock:
            folders = [None] + sorted({a.directory for a in self.agents.values() if a.directory})
        statuses, permissions, questions = {}, [], []
        try:
            for folder in folders:  # OpenCode answers these per folder
                statuses.update(self.client.statuses(directory=folder))
                permissions += [p for p in self.client.pending_permissions(directory=folder) if p not in permissions]
                questions += [q for q in self.client.pending_questions(directory=folder) if q not in questions]
        except Exception as exc:
            self.record({"hub": "resync_error", "error": str(exc)})
            return
        with self.lock:
            for agent in self.agents.values():
                status = (statuses.get(agent.session_id) or {}).get("type", "idle")
                if status == "busy" and agent.base != "working":
                    self.on_busy(agent)
                elif status == "idle" and agent.base in ("working", "retry") and not agent.awaiting_busy:
                    self.on_idle(agent)
            live = {p["id"] for p in permissions} | {q["id"] for q in questions}
            for agent in self.agents.values():
                for request_id in [r for r in agent.pending if r not in live]:
                    agent.pending.pop(request_id)
                    self.refresh(agent, "resync: request gone")
        for kind, items in (("permission.asked", permissions), ("question.asked", questions)):
            for item in items:
                self.on_event({"type": kind, "properties": item})

    def load(self):
        """Re-attach to the sessions in the state file (after a daemon restart)."""
        if not self.state_path or not os.path.exists(self.state_path):
            return 0
        with open(self.state_path, encoding="utf-8") as handle:
            data = json.load(handle)
        with self.lock:
            for item in data.get("agents", []):
                agent = Agent(item["name"], item["session_id"], item.get("model"), item.get("budget_s"),
                              item.get("followups") or [], item.get("created"), directory=item.get("directory"),
                              deny=item.get("deny") or (), tools=item.get("tools"))
                agent.turns, agent.idles = item.get("turns", 0), item.get("idles", 0)
                agent.base = "idle"
                agent.children = set(item.get("children") or [])
                agent.past_sessions = list(item.get("past_sessions") or [])
                self.agents[agent.name] = agent
                self.by_session[agent.session_id] = agent.name
                for child in agent.children:
                    self.child_root[child] = agent.session_id
                self.note(agent, "reattached", "re-attached after restart", "info")
                self.refresh(agent, "re-attached")
        return len(data.get("agents", []))
HERDR_PY_EOF
cat > herdr_py/dag.py <<'HERDR_PY_EOF'
"""DAG dispatch: the steps of one plan, each done by one member in its own workspace and passed or failed by a judge
program. A step starts only when every step it needs has passed, and sees only what those steps produced.

    python3 -m herdr_py.dag plan.json --check                  # check the plan, print its steps level by level
    python3 -m herdr_py.dag plan.json --out runs/p1 [--parallel 4] [--socket SOCK]
    python3 -m herdr_py.dag plan.json --out runs/p1 --resume   # go on after a crash: passed steps are not run again
    python3 -m herdr_py.dag --recheck runs/p1                  # judge every passed step again in a fresh clone

plan.json (paths are relative to the plan's folder):
    {"name": "two-ways-then-merge",
     "repo": "../myproject",        optional: every step works in its own clone of this git repository...
     "base": "HEAD",                ...starting from this commit (resolved once, when the run starts)
     "nodes": [
       {"id": "W1", "member": "w1=codex", "task": "tasks/w1.md", "judge": "python3 judges/tests.py"},
       {"id": "W2", "member": "w2=claude", "task": "tasks/w2.md", "judge": "python3 judges/tests.py"},
       {"id": "W3", "member": "w3=claude", "task": "tasks/merge.md", "needs": ["W1", "W2"],
        "judge": "python3 judges/tests.py", "retries": 1, "timeout": 900, "access": "write", "judge_mode": "json",
        "start": "base"}]}

A member is NAME=BACKEND[:MODEL] or NAME=command:COMMAND (members.py); one name is one member, and a member does one
step at a time. With a repo, each attempt of each step gets its own clone (git clone --shared): clones share
objects, not branches, so a step's clone holds no other step's work. A step's clone also gets the output commit of
each step it needs, as refs/dag/<id>, and its prompt shows those steps' summaries and diffs: nothing from any other
step. Where the clone's files start ("start"): a step that needs nothing starts at the base commit; a step that needs
one step continues from that step's output; a step that needs several starts at the base, and the member compares and
combines them (two ways of doing one thing usually touch the same files). "start" can name one of the needs, "base",
or "merge": the program merges the needs' outputs first, and a conflict fails the step, naming the files. Codex members work there in the workspace-write sandbox, Claude members with file tools only (their
modules say what the real CLIs refuse), opencode members in a session of that folder, with every call outside it
refused, and every edit and command too in a read step (members.py, DaemonMembers). When the member's turn
ends, the program commits everything in the clone; that commit is the step's output and what the judge checks (a
step with "access": "read" keeps no changes: its output is its start commit and its reply). Without a repo the reply
is the output and members work where they always do.

The judge follows coop.py's contract: the reply file is its last argument, it runs in the step's clone (in replies/
without a repo) with HERDR_DAG_* telling it the step, the commit and what the step built on; judge_mode json: it prints
{"status": "valid" | "invalid", "score": ..., "detail": ...} (a crash is a judge error, not a fail); exit: exit code 0
passes. Files named in a judge command resolve against the plan's folder, outside every clone, so a member cannot edit
the judge it is checked by; they are hashed when the run starts and checked before every verdict.

An attempt that fails (invalid, or the member timed out) is tried again while retries last, from the failed attempt's
commit and with the judge's words in the prompt. A step whose need failed is blocked. When the setup breaks (a member
backend ends error or aborted, the judge fails, a clone cannot be made) no new step starts (--keep-going: only that
step fails); --resume runs such a step again. Every dispatch, return, commit and verdict is written to events.jsonl as
it happens; --resume rebuilds the state from it, and refuses when the plan, a task or a judge file changed.
summary.json counts what the invariants need (definitions §21): dispatches made before every need had
passed and passed steps dispatched again (both must be 0, worked out from events.jsonl alone), member tool events that
name another step's workspace (must be 0 where a backend logs them: codex, claude), and how parallel the run was.
Exit codes: 0 every step passed, 1 some did not, 2 a bad plan or arguments, 3 stopped because the setup broke.
"""
import argparse
import collections
import concurrent.futures
import hashlib
import json
import os
import re
import shlex
import shutil
import subprocess
import sys
import threading
import time

from . import dagview
from .coop import command_judge, exit_judge
from .members import BROKEN, MemberError, Members, parse_member
from .teamkb import one_line

NODE_ID = re.compile(r"^[A-Za-z][A-Za-z0-9_-]{0,31}$")
FIELDS = {"id", "member", "task", "judge", "needs", "retries", "timeout", "judge_timeout", "access", "judge_mode", "start"}
ACCESS = ("write", "read")
JUDGE_MODES = ("json", "exit")
GIT_ID = {"GIT_AUTHOR_NAME": "herdr-py dag", "GIT_AUTHOR_EMAIL": "dag@herdr-py.invalid",
          "GIT_COMMITTER_NAME": "herdr-py dag", "GIT_COMMITTER_EMAIL": "dag@herdr-py.invalid"}
OUT_BRANCH = "dag-out"  # the branch a step's output commit is on, in the step's clone

PROMPT = """You are {member}, doing step {node} of the plan "{plan}".{position}

Task:
{task}
{upstream}{retry}
{place}
Reply with a short summary of what you did and what the next steps should know."""
PLACE_WRITE = ("Your folder, {folder}, is a git clone made for this step only, at commit {start} ({origin}). Change the files there. You do "
               "not need to commit: when your turn ends, everything in the folder is committed for you, and a judge "
               "program checks that commit. Only the judge's verdict counts.")
PLACE_READ = ("Your folder, {folder}, is a git clone made for this step only, at commit {start} ({origin}). Read what you need there; changes "
              "are not kept. A judge program checks your reply. Only the judge's verdict counts.")
PLACE_TEXT = "Your reply is your result: a judge program checks it. Only the judge's verdict counts."


class PlanError(ValueError):
    pass


class WorkspaceError(RuntimeError):
    pass


class MergeConflict(Exception):
    """The outputs a step should start from do not merge: the plan's problem, not a broken setup."""


def sha256_text(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def sha256_file(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for block in iter(lambda: handle.read(1 << 20), b""):
            digest.update(block)
    return digest.hexdigest()


def git(*args, env=None):
    try:
        p = subprocess.run(["git"] + list(args), stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True,
                           env=env)
    except FileNotFoundError:
        raise WorkspaceError("git is not installed")
    if p.returncode != 0:
        words = [a for a in args if not a.startswith("-") and "/" not in a][:2]
        raise WorkspaceError(f"git {' '.join(words)}: {one_line(p.stderr or p.stdout, 300)}")
    return p.stdout.strip()


def has_commit(folder, sha):
    return bool(sha) and os.path.isdir(folder) and subprocess.run(
        ["git", "-C", folder, "cat-file", "-e", sha + "^{commit}"], stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL).returncode == 0


def find_cycle(nodes, order):
    """One cycle in the needs as a list of ids (first id repeated at the end), or None."""
    color, stack = {n: 0 for n in order}, []

    def visit(n):
        color[n] = 1
        stack.append(n)
        for m in nodes[n]["needs"]:
            if color.get(m) == 1:
                return stack[stack.index(m):] + [m]
            if color.get(m) == 0:
                found = visit(m)
                if found:
                    return found
        stack.pop()
        color[n] = 2
        return None

    for n in order:
        if color[n] == 0:
            found = visit(n)
            if found:
                return found
    return None


def levels(plan):
    """{id: level}: 0 for a step that needs nothing, else one more than the deepest step it needs."""
    out = {}

    def level(n):
        if n not in out:
            out[n] = 1 + max([level(m) for m in plan["nodes"][n]["needs"]] or [-1])
        return out[n]

    for n in plan["order"]:
        level(n)
    return out


def resolve_args(command, folder):
    """A command as arguments; an argument naming a file in the plan's folder becomes its absolute path (judges and
    command members run inside a step's clone, where a relative path would mean something else)."""
    return [os.path.join(folder, a) if not os.path.isabs(a) and os.path.isfile(os.path.join(folder, a)) else a
            for a in shlex.split(command)]


def load_plan(path):
    """Read and check a plan; every problem is reported at once (PlanError)."""
    folder = os.path.dirname(os.path.abspath(path))
    try:
        with open(path, encoding="utf-8") as handle:
            raw = json.load(handle)
    except (OSError, ValueError) as exc:
        raise PlanError(f"{path}: {exc}")
    if not isinstance(raw, dict) or not isinstance(raw.get("nodes"), list) or not raw["nodes"]:
        raise PlanError(f"{path}: a JSON object with a non-empty \"nodes\" list")
    problems, nodes, order, given_start = [], {}, [], {}
    for i, n in enumerate(raw["nodes"], 1):
        if not isinstance(n, dict):
            problems.append(f"node {i}: an object")
            continue
        nid = n.get("id")
        if not isinstance(nid, str) or not NODE_ID.match(nid):
            problems.append(f"node {i}: the id is letters, digits, - and _, starting with a letter")
            continue
        if nid in nodes:
            problems.append(f"node {nid}: two nodes have this id")
            continue
        where = f"node {nid}"
        unknown = sorted(set(n) - FIELDS)
        if unknown:
            problems.append(f"{where}: unknown fields {', '.join(unknown)}")
        for key in ("member", "task", "judge"):
            if not isinstance(n.get(key), str) or not n[key].strip():
                problems.append(f"{where}: {key} is required")
        member = None
        if isinstance(n.get("member"), str):
            try:
                member = parse_member(n["member"])
            except MemberError as exc:
                problems.append(f"{where}: {exc}")
        task = os.path.join(folder, n["task"]) if isinstance(n.get("task"), str) and n["task"].strip() else None
        if task and not os.path.isfile(task):
            problems.append(f"{where}: task file {n['task']} not found")
        needs = n.get("needs", [])
        if not isinstance(needs, list) or not all(isinstance(x, str) for x in needs):
            problems.append(f"{where}: needs is a list of node ids")
            needs = []
        numbers = {}
        for key, default, least in (("retries", 0, 0), ("timeout", 900, 1), ("judge_timeout", 600, 1)):
            value = n.get(key, default)
            if not isinstance(value, int) or isinstance(value, bool) or value < least:
                problems.append(f"{where}: {key} is a whole number, {least} or more")
                value = default
            numbers[key] = value
        access, mode = n.get("access", "write"), n.get("judge_mode", "json")
        if access not in ACCESS:
            problems.append(f"{where}: access is write or read")
        if mode not in JUDGE_MODES:
            problems.append(f"{where}: judge_mode is json or exit")
        nodes[nid] = dict(numbers, id=nid, member=member, task=task, judge=n.get("judge"), access=access, judge_mode=mode,
                          needs=list(collections.OrderedDict.fromkeys(needs)))
        given_start[nid] = n.get("start")
        order.append(nid)
    for nid in order:
        for need in nodes[nid]["needs"]:
            if need == nid:
                problems.append(f"node {nid}: needs itself")
            elif need not in nodes:
                problems.append(f"node {nid}: needs {need}, which is not a node")
        given, needs = given_start[nid], nodes[nid]["needs"]
        if given is not None and given not in ["base", "merge"] + needs:
            problems.append(f"node {nid}: start is base, merge or one of its needs")
        if given == "merge" and len(needs) < 2:
            problems.append(f"node {nid}: start merge needs two or more needs")
        nodes[nid]["start"] = given or ("base" if len(needs) != 1 else needs[0])
    members = {}
    for nid in order:
        m = nodes[nid]["member"]
        if m and members.setdefault(m["name"], (nid, m))[1] != m:
            problems.append(f"node {nid}: member {m['name']} is not the same as in node {members[m['name']][0]}")
    repo = raw.get("repo")
    if repo is None:
        problems += [f"node {nid}: start only means something with a repo" for nid in order if given_start[nid] is not None]
    if repo is not None:
        repo = os.path.normpath(os.path.join(folder, repo)) if isinstance(repo, str) and repo.strip() else None
        if shutil.which("git") is None:
            problems.append("repo: git is not installed, and a plan with a repository needs it")
        elif not repo or subprocess.run(["git", "-C", repo, "rev-parse", "--git-dir"], stdout=subprocess.DEVNULL,
                                        stderr=subprocess.DEVNULL).returncode != 0:
            problems.append(f"repo: {raw.get('repo')!r} is not a git repository")
    base = raw.get("base", "HEAD")
    if not isinstance(base, str) or not base.strip():
        problems.append("base: a commit, branch or tag")
    if not problems:
        cycle = find_cycle(nodes, order)
        if cycle:
            problems.append("the needs make a cycle: " + " -> ".join(cycle))
    if problems:
        raise PlanError("; ".join(problems))
    for nid in order:
        nodes[nid]["judge_argv"] = resolve_args(nodes[nid]["judge"], folder)
        m = nodes[nid]["member"]
        if m["backend"] == "command":
            nodes[nid]["member"] = dict(m, command=" ".join(shlex.quote(a) for a in resolve_args(m["command"], folder)))
    name = raw["name"] if isinstance(raw.get("name"), str) and raw["name"].strip() else os.path.splitext(os.path.basename(path))[0]
    return {"name": name, "path": os.path.abspath(path), "folder": folder, "repo": repo, "base": base, "nodes": nodes,
            "order": order}


def judge_files(plan):
    """{absolute path: sha256} of every file a judge command names."""
    found = {}
    for nid in plan["order"]:
        for arg in plan["nodes"][nid]["judge_argv"]:
            if os.path.isabs(arg) and os.path.isfile(arg):
                found[arg] = sha256_file(arg)
    return found


def recorded_nodes(plan):
    """What the run records about each step, to tell later whether the plan changed."""
    return {n: {"member": dict(plan["nodes"][n]["member"]), "needs": plan["nodes"][n]["needs"],
                "task": sha256_file(plan["nodes"][n]["task"]), "judge": plan["nodes"][n]["judge"],
                "judge_argv": plan["nodes"][n]["judge_argv"], "judge_mode": plan["nodes"][n]["judge_mode"],
                "judge_timeout": plan["nodes"][n]["judge_timeout"], "access": plan["nodes"][n]["access"],
                "retries": plan["nodes"][n]["retries"], "timeout": plan["nodes"][n]["timeout"],
                "start": plan["nodes"][n]["start"]} for n in plan["order"]}


def make_workspace(repo, path, start, fetch=()):
    """A clone of repo at commit start with no remote left, and each (ref, folder, sha) of fetch brought in from that
    folder's output branch as refs/dag/<ref> (it must be the recorded commit)."""
    git("clone", "--quiet", "--shared", "--no-checkout", repo, path)
    git("-C", path, "remote", "remove", "origin")
    for ref, folder, sha in fetch:
        git("-C", path, "fetch", "--quiet", "--no-tags", folder, f"refs/heads/{OUT_BRANCH}:refs/dag/{ref}")
        got = git("-C", path, "rev-parse", f"refs/dag/{ref}")
        if got != sha:
            raise WorkspaceError(f"{ref}: its clone is at {got[:12]}, the run recorded {sha[:12]}")
    if fetch:  # git notes where it fetched from: no file in a clone may name another step's clone
        fetch_head = os.path.join(path, git("-C", path, "rev-parse", "--git-path", "FETCH_HEAD"))
        if os.path.exists(fetch_head):
            os.remove(fetch_head)
    git("-C", path, "checkout", "--quiet", "-B", "dag-work", start)


def merge_needs(path, refs):
    """Merge refs/dag/<ref> for each ref into the clone's branch; a conflict is undone and raised as MergeConflict."""
    p = subprocess.run(["git", "-C", path, "-c", "commit.gpgsign=false", "merge", "--quiet", "--no-edit", "--no-verify",
                        "-m", "herdr-py dag: start from " + ", ".join(refs)] + [f"refs/dag/{r}" for r in refs],
                       stdout=subprocess.PIPE, stderr=subprocess.STDOUT, universal_newlines=True, env=dict(os.environ, **GIT_ID))
    if p.returncode != 0:
        files = git("-C", path, "diff", "--name-only", "--diff-filter=U").split()
        subprocess.run(["git", "-C", path, "merge", "--abort"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        raise MergeConflict(f"the outputs of {', '.join(refs)} do not merge cleanly"
                            + (f" (conflicts in {', '.join(files)})" if files else f": {one_line(p.stdout, 200)}"))
    return git("-C", path, "rev-parse", "HEAD")


def commit_all(path, start, message):
    """Commit everything in the clone (whatever the member did to its branches) and point the output branch at it.
    Returns (sha, files changed since start)."""
    git("-C", path, "add", "-A")
    git("-C", path, "-c", "commit.gpgsign=false", "commit", "--quiet", "--allow-empty", "--no-verify", "-m", message,
        env=dict(os.environ, **GIT_ID))
    sha = git("-C", path, "rev-parse", "HEAD")
    git("-C", path, "branch", "-f", OUT_BRANCH, sha)
    changed = [line for line in git("-C", path, "diff", "--name-only", start, sha).splitlines() if line]
    return sha, changed


def judge_once(node, reply_path, cwd, env):
    """One verdict under coop.py's contract: (status, score, detail); a judge that breaks is infra_error."""
    check = (command_judge if node["judge_mode"] == "json" else exit_judge)(node["judge_argv"], timeout=node["judge_timeout"])
    try:
        status, score, detail = check(reply_path, cwd=cwd, env=env)
    except Exception as exc:  # the judge itself broke: not a fail of the step
        return "infra_error", None, str(exc)
    if status not in ("valid", "invalid"):
        return "infra_error", None, f"the judge said status {status!r}"
    return status, score, detail


def judge_env(plan_name, nid, attempt, base, sha, workspace, upstream):
    return dict(os.environ, HERDR_DAG_PLAN=plan_name, HERDR_DAG_NODE=nid, HERDR_DAG_ATTEMPT=str(attempt),
                HERDR_DAG_BASE=base or "", HERDR_DAG_COMMIT=sha or "", HERDR_DAG_WORKSPACE=workspace or "",
                HERDR_DAG_UPSTREAM=json.dumps(upstream, sort_keys=True))


class DagRun:
    """One run of one plan. members: an object with run_turn(name, prompt, timeout=..., workdir=..., access=...) ->
    (reply, state) and, optionally, tokens(name) (members.Members, or anything shaped like it)."""

    def __init__(self, plan, members, out, parallel=4, resume=False, keep_going=False, diff_bytes=12000,
                 reply_bytes=3000):
        if not (isinstance(parallel, int) and parallel >= 1):
            raise ValueError("parallel: 1 or more")
        out = os.path.abspath(out)  # members are given absolute folders
        self.plan, self.members, self.out, self.parallel = plan, members, out, parallel
        self.keep_going, self.diff_bytes, self.reply_bytes = keep_going, diff_bytes, reply_bytes
        self.events_path = os.path.join(out, "events.jsonl")
        if os.path.exists(self.events_path) and not resume:
            raise ValueError(f"{out} already holds a run: give a new folder, or --resume")
        if resume and not os.path.exists(self.events_path):
            raise ValueError(f"{out} holds no run to resume")
        for sub in ("replies", "workspaces"):
            os.makedirs(os.path.join(out, sub), exist_ok=True)
        self.lock = threading.Lock()
        self.member_locks = collections.defaultdict(threading.Lock)
        self.events, self.stopped, self.resumed_passed = [], None, set()
        self.state = {n: {"state": "waiting", "attempt": 0, "tries": 0, "sha": None, "score": None, "reply": None,
                          "workspace": None, "detail": None, "prev": None, "seconds": 0.0, "busy": 0.0, "tokens": None}
                      for n in plan["order"]}
        if resume:
            self.restore()
        self.log = open(self.events_path, "a", encoding="utf-8", buffering=1)
        if resume:
            self.emit("run.resume", passed=sorted(self.resumed_passed))
        else:
            self.start()

    # -- records -------------------------------------------------------------------------------------------------

    def emit(self, kind, **fields):
        with self.lock:
            event = dict(fields, t=round(time.time(), 3), seq=len(self.events) + 1, kind=kind)
            self.events.append(event)
            self.log.write(json.dumps(event, ensure_ascii=False, sort_keys=True) + "\n")
            return event

    def start(self):
        plan = self.plan
        self.base = git("-C", plan["repo"], "rev-parse", "--verify", plan["base"] + "^{commit}") if plan["repo"] else None
        self.judges = judge_files(plan)
        nodes = recorded_nodes(plan)
        with open(os.path.join(self.out, "plan.json"), "w", encoding="utf-8") as handle:
            json.dump({"name": plan["name"], "repo": plan["repo"], "base": self.base, "order": plan["order"], "nodes": nodes},
                      handle, ensure_ascii=False, indent=1)
        self.first = self.emit("run.start", plan=plan["name"], repo=plan["repo"], base=self.base, nodes=nodes,
                               order=plan["order"], judge_files=self.judges, parallel=self.parallel)

    def restore(self):
        """Rebuild the state from events.jsonl; the plan, its tasks and its judges must be what the run started with."""
        with open(self.events_path, encoding="utf-8") as handle:
            self.events = [json.loads(line) for line in handle if line.strip()]
        first = next((e for e in self.events if e["kind"] == "run.start"), None)
        if first is None:
            raise ValueError(f"{self.events_path}: no run.start")
        if recorded_nodes(self.plan) != first["nodes"]:
            raise ValueError("the plan or a task file changed since the run started: start a new run")
        if judge_files(self.plan) != first["judge_files"]:
            raise ValueError("a judge file changed since the run started: start a new run")
        self.first, self.base, self.judges = first, first["base"], first["judge_files"]
        for e in self.events:
            st = self.state.get(e.get("node"))
            if st is None:
                continue
            kind = e["kind"]
            if kind == "node.dispatch":
                st.update(attempt=max(st["attempt"], e["attempt"]), state="waiting")
            elif kind == "node.verdict":
                st["tries"] += 1
            elif kind == "node.retry":
                st.update(prev=e.get("prev"), detail=e.get("detail"))
            elif kind == "node.pass":
                st.update(state="passed", sha=e.get("sha"), score=e.get("score"), reply=e.get("reply"),
                          workspace=e.get("workspace"))
            elif kind == "node.fail":
                # a step that failed because the setup broke runs again; a step the judge failed stays failed
                st.update(state="waiting" if e.get("infra") else "failed", detail=e.get("why"))
            elif kind == "node.return":
                st["seconds"] += e.get("seconds") or 0
        for n, st in self.state.items():
            if st["state"] == "passed":
                kept = (has_commit(os.path.join(self.out, st["workspace"]), st["sha"]) if st["workspace"]
                        else bool(st["reply"]) and os.path.isfile(os.path.join(self.out, "replies", st["reply"] + ".txt")))
                if kept:
                    self.resumed_passed.add(n)
                else:
                    st.update(state="waiting")  # its output is gone: it has to run again (summary: dispatched_after_pass)

    # -- one step ------------------------------------------------------------------------------------------------

    def store(self, text):
        digest = sha256_text(text)
        path = os.path.join(self.out, "replies", digest + ".txt")
        if not os.path.exists(path):
            with open(path + ".tmp", "w", encoding="utf-8") as handle:
                handle.write(text)
            os.replace(path + ".tmp", path)
        return digest

    def reply_text(self, digest):
        with open(os.path.join(self.out, "replies", digest + ".txt"), encoding="utf-8") as handle:
            return handle.read()

    def upstream_text(self, node, workspace):
        parts = []
        for uid in node["needs"]:
            up, st = self.plan["nodes"][uid], self.state[uid]
            score = f" with score {st['score']}" if st["score"] is not None else ""
            summary = self.reply_text(st["reply"]).strip() if st["reply"] else ""
            if len(summary) > self.reply_bytes:
                summary = summary[:self.reply_bytes] + " [...]"
            lines = [f"Step {uid} (done by {up['member']['name']}) passed the judge{score}. Its summary:", summary or "(none)"]
            if workspace and st["sha"]:
                stat = git("-C", workspace, "diff", "--stat", self.base, st["sha"])
                diff = git("-C", workspace, "diff", self.base, st["sha"])
                if len(diff) > self.diff_bytes:
                    diff = diff[:self.diff_bytes] + f"\n[... {len(diff) - self.diff_bytes} more bytes: git diff {self.base[:12]} refs/dag/{uid}]"
                lines += [f"Its result is commit {st['sha']}, in your clone as refs/dag/{uid}. What it changed from the base:",
                          stat or "(no changes)", "```diff", diff, "```"]
            parts.append("\n".join(lines))
        return ("\nWhat the steps before yours produced:\n\n" + "\n\n".join(parts) + "\n") if parts else ""

    def prompt(self, nid, start, workspace, origin=None):
        node, st = self.plan["nodes"][nid], self.state[nid]
        with open(node["task"], encoding="utf-8") as handle:
            task = handle.read().strip()
        position = f" It builds on {', '.join(node['needs'])}." if node["needs"] else ""
        retry = ""
        if st["prev"]:
            retry = (f"\nYour previous attempt did not pass the judge: {one_line(st['detail'] or 'no reason given', 1500)}\n"
                     + ("Your folder starts from that attempt's commit, so you can fix it.\n" if workspace else ""))
        if not workspace:
            place = PLACE_TEXT
        else:
            place = (PLACE_WRITE if node["access"] == "write" else PLACE_READ).format(start=start[:12], origin=origin, folder=workspace)
        return PROMPT.format(member=node["member"]["name"], node=nid, plan=self.plan["name"], position=position, task=task,
                             upstream=self.upstream_text(node, workspace), retry=retry, place=place)

    def tokens(self, name):
        try:
            return self.members.tokens(name) if hasattr(self.members, "tokens") else None
        except Exception:  # counting tokens must never fail a step
            return None

    def judge(self, nid, attempt, reply_path, cwd, sha, workspace, upstream):
        for path, digest in self.judges.items():
            if not os.path.isfile(path) or sha256_file(path) != digest:
                return "infra_error", None, f"the judge file {path} changed during the run"
        env = judge_env(self.plan["name"], nid, attempt, self.base, sha, workspace, upstream)
        return judge_once(self.plan["nodes"][nid], reply_path, cwd, env)

    def fail(self, nid, attempt, why, dispatch=None, infra=False):
        self.state[nid].update(state="failed", detail=why)
        self.emit("node.fail", node=nid, attempt=attempt, dispatch=dispatch, why=why, infra=infra)
        if infra:
            self.halt(f"{nid}: {why}")

    def step(self, nid):
        """Run one step until it passes, fails or the run stops; its whole time (clones, member, commit, judge) is busy."""
        began = time.time()
        try:
            return self.attempts(nid)
        finally:
            self.state[nid]["busy"] += time.time() - began

    def attempts(self, nid):
        """The attempts of one step; every outcome is in events.jsonl."""
        node, st = self.plan["nodes"][nid], self.state[nid]
        name = node["member"]["name"]
        while True:
            st["attempt"] += 1
            attempt = st["attempt"]
            dispatch = sha256_text(f"{self.first['plan']}/{self.first['t']}/{nid}/{attempt}")[:16]
            rel = os.path.join("workspaces", f"{nid}-{attempt}")
            workspace = os.path.join(self.out, rel) if self.plan["repo"] else None
            upstream = {u: self.state[u]["sha"] or self.state[u]["reply"] for u in node["needs"]}
            start, origin = None, None
            try:
                if workspace:
                    if os.path.exists(workspace):  # left by an attempt that a crash cut short
                        shutil.rmtree(workspace)
                    if st["prev"]:
                        start, origin = st["prev"]["sha"], "your previous attempt"
                    elif node["start"] in ("base", "merge"):
                        start, origin = self.base, "the base commit"
                    else:
                        start, origin = self.state[node["start"]]["sha"], f"the output of step {node['start']}"
                    fetch = [(u, os.path.join(self.out, self.state[u]["workspace"]), self.state[u]["sha"]) for u in node["needs"]]
                    if st["prev"]:
                        fetch.append(("previous", os.path.join(self.out, st["prev"]["workspace"]), st["prev"]["sha"]))
                    make_workspace(self.plan["repo"], workspace, start, fetch)
                    if node["start"] == "merge" and not st["prev"]:
                        start, origin = merge_needs(workspace, node["needs"]), "the outputs of " + " and ".join(node["needs"]) + " merged"
                prompt = self.prompt(nid, start, workspace, origin)
            except MergeConflict as exc:
                return self.fail(nid, attempt, str(exc))
            except (WorkspaceError, OSError) as exc:
                return self.fail(nid, attempt, f"the step's clone could not be made: {exc}", infra=True)
            self.emit("node.dispatch", node=nid, attempt=attempt, dispatch=dispatch, member=name, start=start,
                      workspace=rel if workspace else None, upstream=upstream,
                      input=sha256_text(json.dumps([prompt, start, upstream], sort_keys=True)))
            st["state"] = "running"
            place = {"workdir": workspace, "access": node["access"]} if workspace else {}
            with self.member_locks[name]:
                before, began = self.tokens(name), time.time()
                try:
                    reply, state = self.members.run_turn(name, prompt, timeout=node["timeout"], **place)
                except Exception as exc:  # a member backend that breaks fails this attempt
                    reply, state = f"({type(exc).__name__}: {exc})", "error"
                seconds, after = round(time.time() - began, 2), self.tokens(name)
            used = after - before if isinstance(before, int) and isinstance(after, int) else None
            st["seconds"] += seconds
            if used is not None:
                st["tokens"] = (st["tokens"] or 0) + used
            digest = self.store(reply or "")
            self.emit("node.return", node=nid, attempt=attempt, dispatch=dispatch, state=state, seconds=seconds,
                      tokens=used, reply=digest)
            sha, broken = start, None
            if workspace:
                try:
                    if node["access"] == "write":
                        sha, changed = commit_all(workspace, start, f"herdr-py dag: {self.plan['name']} {nid} attempt {attempt}")
                    else:  # a read step keeps no changes: its output commit is where it started
                        git("-C", workspace, "branch", "-f", OUT_BRANCH, start)
                        changed = []
                    self.emit("node.commit", node=nid, attempt=attempt, dispatch=dispatch, sha=sha, changed=changed)
                except WorkspaceError as exc:
                    broken = f"the step's clone could not be committed: {exc}"
            if state in BROKEN:
                return self.fail(nid, attempt, f"the member's backend ended {state}: {one_line(reply, 300)}", dispatch, infra=True)
            if broken:
                status, score, detail = "invalid", None, broken
            elif state == "idle":
                st["state"] = "judging"
                status, score, detail = self.judge(nid, attempt, os.path.join(self.out, "replies", digest + ".txt"),
                                                   workspace or os.path.join(self.out, "replies"), sha, workspace, upstream)
            else:
                status, score, detail = "invalid", None, f"the member's turn ended {state} (limit {node['timeout']} s)"
            if status == "infra_error":
                return self.fail(nid, attempt, f"the judge failed: {one_line(detail, 300)}", dispatch, infra=True)
            st["tries"] += 1
            self.emit("node.verdict", node=nid, attempt=attempt, dispatch=dispatch, status=status, score=score,
                      detail=one_line(detail, 600))
            if status == "valid":
                st.update(state="passed", sha=sha, score=score, reply=digest, workspace=rel if workspace else None)
                self.emit("node.pass", node=nid, attempt=attempt, dispatch=dispatch, sha=sha, score=score, reply=digest,
                          workspace=rel if workspace else None)
                return None
            if st["tries"] <= node["retries"] and not self.stopped:
                st.update(prev={"sha": sha, "workspace": rel} if workspace else {"reply": digest}, detail=detail)
                self.emit("node.retry", node=nid, attempt=attempt, dispatch=dispatch, detail=one_line(detail, 600),
                          prev=st["prev"])
                continue
            return self.fail(nid, attempt, f"did not pass after {st['tries']} attempt(s): {one_line(detail, 300)}", dispatch)

    def halt(self, why):
        """The setup broke: no new step starts (unless keep_going); running steps finish."""
        if not self.keep_going and not self.stopped:
            self.stopped = why
            self.emit("run.stop", why=why)

    # -- the run -------------------------------------------------------------------------------------------------

    def ready(self):
        return [n for n in self.plan["order"] if self.state[n]["state"] == "waiting"
                and all(self.state[m]["state"] == "passed" for m in self.plan["nodes"][n]["needs"])]

    def block(self):
        """Mark waiting steps whose need failed or was blocked; repeat until nothing changes."""
        changed = True
        while changed:
            changed = False
            for n in self.plan["order"]:
                bad = [m for m in self.plan["nodes"][n]["needs"] if self.state[m]["state"] in ("failed", "blocked")]
                if self.state[n]["state"] == "waiting" and bad:
                    self.state[n].update(state="blocked", detail="needs " + ", ".join(bad))
                    self.emit("node.blocked", node=n, why="needs " + ", ".join(bad) + ", which did not pass")
                    changed = True

    def run(self):
        began = time.time()
        with concurrent.futures.ThreadPoolExecutor(self.parallel) as pool:
            running = {}
            while True:
                self.block()
                if not self.stopped:
                    for n in self.ready():
                        if len(running) >= self.parallel:
                            break
                        self.state[n]["state"] = "running"
                        running[pool.submit(self.step, n)] = n
                if not running:
                    break
                done, _ = concurrent.futures.wait(running, return_when=concurrent.futures.FIRST_COMPLETED)
                for future in done:
                    n = running.pop(future)
                    exc = future.exception()
                    if exc is not None:  # a bug in this runner, not in the member: say so and stop
                        self.fail(n, self.state[n]["attempt"], f"the runner failed: {type(exc).__name__}: {exc}", infra=True)
                self.view()
        summary = self.summary(time.time() - began)
        self.emit("run.end", **{k: summary[k] for k in ("passed", "failed", "blocked", "waiting", "stopped")})
        self.log.close()
        tmp = os.path.join(self.out, "summary.json.tmp")
        with open(tmp, "w", encoding="utf-8") as handle:
            json.dump(summary, handle, ensure_ascii=False, indent=1)
        os.replace(tmp, os.path.join(self.out, "summary.json"))
        self.view()
        return summary

    def view(self):
        """Write view.html; a page that cannot be written is reported, it never ends the run."""
        try:
            dagview.save(self.out)
        except Exception as exc:  # noqa: BLE001 - the page is for people; events.jsonl is what counts
            print(f"herdr-py dag: warning: view.html not written: {type(exc).__name__}: {exc}", file=sys.stderr)

    def summary(self, seconds):
        counts = collections.Counter(st["state"] for st in self.state.values())
        busy = sum(st["busy"] for st in self.state.values())
        known = [st["tokens"] for st in self.state.values() if st["tokens"] is not None]
        summary = {"plan": self.plan["name"], "base": self.base, "passed": counts["passed"], "failed": counts["failed"],
                   "blocked": counts["blocked"], "waiting": counts["waiting"] + counts["running"] + counts["judging"],
                   "stopped": self.stopped, "seconds": round(seconds, 1), "busy_seconds": round(busy, 1),
                   "member_seconds": round(sum(st["seconds"] for st in self.state.values()), 1),
                   "parallelism": round(busy / seconds, 2) if seconds > 0 else None,
                   "tokens": sum(known) if known else None,
                   "nodes": {n: {"state": st["state"], "attempts": st["attempt"], "sha": st["sha"], "score": st["score"],
                                 "member": self.plan["nodes"][n]["member"]["name"], "seconds": round(st["seconds"], 1),
                                 "tokens": st["tokens"], "detail": st["detail"]} for n, st in self.state.items()},
                   "out_of_bounds": out_of_bounds(self.out, self.events)}
        summary.update(invariants(self.events, self.first["nodes"]))
        return summary


def invariants(events, nodes):
    """What the invariants count, from the events alone: dispatches made before every need had passed, and steps
    dispatched again after they had passed (both must be 0). nodes: {id: {"needs": [...]}}."""
    passed, early, again = set(), 0, 0
    for e in events:
        if e["kind"] == "node.pass":
            passed.add(e["node"])
        elif e["kind"] == "node.dispatch":
            if any(m not in passed for m in nodes[e["node"]]["needs"]):
                early += 1
            if e["node"] in passed:
                again += 1
    return {"released_early": early, "dispatched_after_pass": again}


def out_of_bounds(out, events):
    """Member tool events (codex, claude and opencode logs under members/) that name another step's workspace while a
    step ran: {"count": n, "examples": [...], "measured": [backends with logs]}; command members keep no such log."""
    homes = {}
    for e in events:
        if e["kind"] == "node.dispatch" and e.get("workspace"):
            path = os.path.join(out, e["workspace"])
            homes[(e["node"], e["attempt"])] = {path, os.path.realpath(path)}
    ends = {(e["node"], e["attempt"]): e["t"] for e in events if e["kind"] == "node.return"}
    windows = [(e["member"], e["t"], ends.get((e["node"], e["attempt"]), float("inf")), homes[(e["node"], e["attempt"])])
               for e in events if e["kind"] == "node.dispatch" and e.get("workspace")]
    count, examples, measured = 0, [], []
    for backend in ("codex", "claude", "opencode"):
        path = os.path.join(out, "members", backend, "events.jsonl")
        if not os.path.isfile(path):
            continue
        measured.append(backend)
        with open(path, encoding="utf-8", errors="replace") as handle:
            for line in handle:
                try:
                    row = json.loads(line)
                except ValueError:
                    continue
                if not isinstance(row, dict) or "event" not in row:
                    continue
                text = json.dumps(row["event"])
                for member, t0, t1, home in windows:
                    if row.get("agent") != member or not (t0 <= row.get("t", 0) <= t1 + 1):
                        continue
                    for key, others in homes.items():
                        if others is home:
                            continue
                        if any(other + os.sep in text or text.endswith(other) or (other + '"') in text for other in others):
                            count += 1
                            if len(examples) < 5:
                                examples.append(f"{member} touched {key[0]}-{key[1]}")
    return {"count": count, "examples": examples, "measured": measured}


def recheck(out):
    """Judge every passed step again in a fresh clone of its output commit, with the recorded judge.
    Returns [{"node", "recorded", "now", "score_recorded", "score_now", "detail"}], one per passed step."""
    out = os.path.abspath(out)
    with open(os.path.join(out, "events.jsonl"), encoding="utf-8") as handle:
        events = [json.loads(line) for line in handle if line.strip()]
    first = next(e for e in events if e["kind"] == "run.start")
    dispatched = {(e["node"], e["attempt"]): e for e in events if e["kind"] == "node.dispatch"}
    latest = {}
    for e in events:
        if e["kind"] == "node.pass":
            latest[e["node"]] = e
    changed = [p for p, digest in first["judge_files"].items() if not os.path.isfile(p) or sha256_file(p) != digest]
    rows = []
    for nid, e in latest.items():
        node = first["nodes"][nid]
        reply = os.path.join(out, "replies", e["reply"] + ".txt")
        if changed:
            rows.append({"node": nid, "recorded": "valid", "now": "infra_error", "score_recorded": e.get("score"),
                         "score_now": None, "detail": "judge files changed since the run: " + ", ".join(changed)})
            continue
        cwd, workspace = os.path.join(out, "replies"), None
        if e.get("workspace"):
            workspace = os.path.join(out, "recheck", f"{nid}-{e['attempt']}")
            if os.path.exists(workspace):
                shutil.rmtree(workspace)
            make_workspace(first["repo"], workspace, e["sha"], [("output", os.path.join(out, e["workspace"]), e["sha"])])
            cwd = workspace
        upstream = dispatched[(nid, e["attempt"])].get("upstream") or {}
        env = judge_env(first["plan"], nid, e["attempt"], first["base"], e.get("sha"), workspace, upstream)
        status, score, detail = judge_once(node, reply, cwd, env)
        rows.append({"node": nid, "recorded": "valid", "now": status, "score_recorded": e.get("score"), "score_now": score,
                     "detail": one_line(detail, 300)})
    return rows


def report(summary):
    s = summary
    lines = [f"plan {s['plan']}: {s['passed']} passed, {s['failed']} failed, {s['blocked']} blocked, {s['waiting']} not run"
             + (f"; STOPPED: {s['stopped']}" if s["stopped"] else ""),
             f"{s['seconds']} s wall, {s['busy_seconds']} s of step work, {s['member_seconds']} s of it in member turns "
             f"(parallelism {s['parallelism']}); "
             f"tokens {s['tokens'] if s['tokens'] is not None else 'not reported'}",
             f"invariants: started before their needs passed {s['released_early']}, passed steps dispatched again "
             f"{s['dispatched_after_pass']}, workspace crossings {s['out_of_bounds']['count']} "
             f"(measured for: {', '.join(s['out_of_bounds']['measured']) or 'no member logs'})"]
    for n, v in s["nodes"].items():
        lines.append(f"  {n:<12} {v['state']:<8} attempts {v['attempts']}  {v['member']}"
                     + (f"  commit {v['sha'][:12]}" if v["sha"] else "") + (f"  score {v['score']}" if v["score"] is not None else "")
                     + (f"  ({one_line(v['detail'], 120)})" if v["detail"] and v["state"] != "passed" else ""))
    return "\n".join(lines)


def print_check(plan):
    lv = levels(plan)
    print(f"plan {plan['name']}: {len(plan['order'])} steps"
          + (f", each in a clone of {plan['repo']} at {plan['base']}" if plan["repo"] else ", no repository"))
    for level in range(max(lv.values()) + 1):
        row = [n for n in plan["order"] if lv[n] == level]
        print(f"  level {level}: " + ", ".join(
            f"{n} ({plan['nodes'][n]['member']['name']}"
            + (f", after {', '.join(plan['nodes'][n]['needs'])}" if plan["nodes"][n]["needs"] else "") + ")" for n in row))


def main(argv=None):
    ap = argparse.ArgumentParser(prog="python3 -m herdr_py.dag", description=__doc__.split("\n\n")[0])
    ap.add_argument("plan", nargs="?", help="the plan (JSON)")
    ap.add_argument("--out", metavar="DIR", help="the run's folder (new, or the one to --resume)")
    ap.add_argument("--check", action="store_true", help="check the plan and print its steps; run nothing")
    ap.add_argument("--resume", action="store_true", help="go on with the run in --out")
    ap.add_argument("--parallel", type=int, default=4, metavar="N", help="steps at the same time (default 4)")
    ap.add_argument("--keep-going", action="store_true", help="a broken backend or judge fails only its step")
    ap.add_argument("--socket", help="the herdr-py daemon's socket (opencode members)")
    ap.add_argument("--recheck", metavar="DIR", help="judge every passed step of that run again in a fresh clone")
    a = ap.parse_args(argv)
    if a.recheck:
        try:
            rows = recheck(a.recheck)
        except (OSError, ValueError, KeyError, StopIteration, WorkspaceError) as exc:
            print(f"herdr-py dag: recheck: {type(exc).__name__}: {exc}", file=sys.stderr)
            return 2
        for r in rows:
            print(f"  {r['node']:<12} recorded {r['recorded']}, now {r['now']}"
                  + (f" (score {r['score_recorded']} -> {r['score_now']})" if r["score_recorded"] != r["score_now"] else "")
                  + (f": {r['detail']}" if r["now"] != "valid" else ""))
        wrong = [r for r in rows if r["now"] != "valid"]
        print(f"{len(rows)} passed steps judged again, {len(wrong)} did not hold")
        return 2 if any(r["now"] == "infra_error" for r in wrong) else (1 if wrong else 0)
    if not a.plan:
        ap.error("give the plan")
    try:
        plan = load_plan(a.plan)
    except PlanError as exc:
        print(f"herdr-py dag: {exc}", file=sys.stderr)
        return 2
    if a.check:
        print_check(plan)
        return 0
    if not a.out:
        ap.error("--out: the run's folder")
    specs = list(collections.OrderedDict((plan["nodes"][n]["member"]["name"], plan["nodes"][n]["member"])
                                         for n in plan["order"]).values())
    try:
        members = Members(specs, os.path.join(os.path.abspath(a.out), "members"), socket=a.socket, sessions="fresh",
                          cwd=plan["folder"])
    except MemberError as exc:
        print(f"herdr-py dag: {exc}", file=sys.stderr)
        return 2
    try:
        run = DagRun(plan, members, a.out, parallel=a.parallel, resume=a.resume, keep_going=a.keep_going)
    except (ValueError, WorkspaceError) as exc:
        members.close()
        print(f"herdr-py dag: {exc}", file=sys.stderr)
        return 2
    try:
        summary = run.run()
    finally:
        members.close()
    print(report(summary))
    print(f"every step on one page: {os.path.join(os.path.abspath(a.out), 'view.html')}")
    if summary["stopped"]:
        return 3
    return 0 if summary["passed"] == len(plan["order"]) else 1


if __name__ == "__main__":
    sys.exit(main())
