cat > herdr_py/web/dashboard/index.html <<'HERDR_PY_EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="color-scheme" content="dark light">
<title>Team run</title>
<link rel="icon" href="icon.svg" type="image/svg+xml">
<link rel="stylesheet" href="dashboard.css">
</head>
<body>
<a class="skip" href="#timeline">Skip to the conversation</a>
<header class="bar">
  <div class="brand">
    <h1>Team run</h1>
    <span id="run-name" class="run-name"></span>
  </div>
  <div class="tools">
    <span id="conn" class="conn" role="status" aria-live="polite">connecting…</span>
    <button id="theme" type="button" class="small">Theme: auto</button>
  </div>
</header>
<main class="layout">
  <section class="status" aria-labelledby="status-h">
    <h2 id="status-h" class="sr-only">Status</h2>
    <p id="progress" class="progress">Waiting for the first update…</p>
    <ul id="tiles" class="tiles"></ul>
  </section>

  <section class="members-sec" aria-labelledby="members-h">
    <h2 id="members-h">Members</h2>
    <p id="members-note" class="note" hidden></p>
    <ul id="members" class="members"></ul>
  </section>

  <section class="scores-sec" aria-labelledby="scores-h">
    <h2 id="scores-h">Scores per row</h2>
    <p class="note">The chart shows the picture match: the share of colour squares that match the original (1 = identical).
      A revision is kept only when its score rises; in strict mode (the default) that score also checks borders and text
      colour, so a rejected point can sit above the kept line. The conversation gives both numbers.</p>
    <ul class="legend" aria-label="Legend">
      <li><svg class="key" viewBox="0 0 24 12" aria-hidden="true"><line class="kept-line" x1="1" y1="6" x2="23" y2="6"></line></svg>kept version</li>
      <li><svg class="key" viewBox="0 0 12 12" aria-hidden="true"><circle class="dot-accepted" cx="6" cy="6" r="4.5"></circle></svg>accepted</li>
      <li><svg class="key" viewBox="0 0 12 12" aria-hidden="true"><circle class="dot-rejected" cx="6" cy="6" r="4"></circle></svg>rejected</li>
      <li><svg class="key" viewBox="0 0 12 12" aria-hidden="true"><path class="cross" d="M2 2 L10 10 M10 2 L2 10"></path></svg>could not be drawn</li>
    </ul>
    <p id="scores-empty" class="note">No scores yet: a row gets one when the program has drawn its first version.</p>
    <div id="charts" class="charts"></div>
    <div id="tip" class="tip" role="tooltip" hidden></div>
  </section>

  <section class="pictures-sec" aria-labelledby="pictures-h">
    <h2 id="pictures-h">Ours and the original</h2>
    <p id="pictures-empty" class="note">No picture yet: one appears every time the program keeps a version.</p>
    <div id="pictures" hidden>
      <div class="stepper">
        <button id="prev" type="button" class="small" aria-label="Earlier picture">‹</button>
        <input id="step" type="range" min="0" max="0" value="0" step="1" aria-label="Kept picture">
        <button id="next" type="button" class="small" aria-label="Later picture">›</button>
      </div>
      <p id="step-label" class="caption" aria-live="polite"></p>
      <div class="pair">
        <figure>
          <img id="pic-ours" alt="" decoding="async">
          <p id="miss-ours" class="note" hidden></p>
          <figcaption id="cap-ours"></figcaption>
        </figure>
        <figure>
          <img id="pic-original" alt="" decoding="async">
          <p id="miss-original" class="note" hidden></p>
          <figcaption id="cap-original"></figcaption>
        </figure>
      </div>
    </div>
  </section>

  <section class="talk-sec" aria-labelledby="talk-h">
    <h2 id="talk-h">Conversation</h2>
    <div class="filters">
      <label class="field">Member
        <select id="f-member"><option value="">everyone</option></select>
      </label>
      <fieldset class="kinds">
        <legend>Kinds</legend>
        <label><input type="checkbox" name="kind" value="message" checked> message</label>
        <label><input type="checkbox" name="kind" value="check" checked> check</label>
        <label><input type="checkbox" name="kind" value="control" checked> control</label>
        <label><input type="checkbox" name="kind" value="end" checked> end</label>
      </fieldset>
    </div>
    <p id="talk-count" class="note"></p>
    <ol id="timeline" class="timeline" tabindex="0" role="log" aria-label="Conversation, oldest first"></ol>
    <button id="latest" type="button" class="small latest" hidden>New lines below: jump to the latest</button>
  </section>

  <section class="lessons-sec" aria-labelledby="lessons-h">
    <h2 id="lessons-h">Lessons</h2>
    <p id="lessons-empty" class="note">None yet: the program adds one for every kind of mistake it catches, and puts the
      list at the top of every later prompt.</p>
    <ol id="lessons" class="lessons"></ol>
  </section>
</main>

<template id="member-tpl">
  <li class="member">
    <div class="m-head"><strong class="m-name"></strong><span class="chip"></span><span class="m-since note"></span></div>
    <dl class="m-stats">
      <div><dt>tokens</dt><dd class="m-tokens"></dd></div>
      <div><dt>turns</dt><dd class="m-turns"></dd></div>
      <div><dt>sessions</dt><dd class="m-sessions"></dd></div>
    </dl>
    <dl class="m-counters" hidden></dl>
    <p class="m-pending" hidden></p>
    <p class="m-words-label note"></p>
    <p class="m-words"></p>
  </li>
</template>
<script src="dashboard.js"></script>
</body>
</html>
HERDR_PY_EOF
cat > herdr_py/web/index.html <<'HERDR_PY_EOF'
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>herdr-py</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<header class="bar">
  <h1>herdr-py</h1>
  <span id="conn" class="conn" aria-live="polite">connecting…</span>
</header>
<main>
  <section id="needs" class="needs" hidden>
    <h2>Needs you <span id="needs-count" class="count"></span></h2>
    <ul id="needs-list" class="needs-list"></ul>
  </section>
  <section>
    <h2>Agents</h2>
    <p id="empty" class="muted" hidden>No agents yet. Start one below or with <code>herdr-py start</code>.</p>
    <ul id="agents" class="agents"></ul>
  </section>
  <details class="new">
    <summary>Start an agent</summary>
    <form id="new-agent">
      <label>Name <input name="name" required pattern="[A-Za-z0-9_.-]{1,40}" autocomplete="off"></label>
      <label>Prompt <textarea name="prompt" rows="3" required></textarea></label>
      <label>Time budget (seconds, optional) <input name="budget_s" type="number" min="1" inputmode="numeric"></label>
      <label>Follow-ups (one per line, optional) <textarea name="followups" rows="2"></textarea></label>
      <button type="submit" class="primary">Start</button>
    </form>
  </details>
  <p id="toast" class="toast" role="status" aria-live="polite"></p>
</main>
<template id="agent-tpl">
  <li class="agent">
    <div class="head"><strong class="name"></strong><span class="chip"></span><span class="meta muted"></span></div>
    <ul class="activity"></ul>
    <p class="stream muted"></p>
    <div class="actions">
      <button type="button" class="act-prompt">Prompt</button>
      <button type="button" class="act-abort danger">Abort</button>
    </div>
    <form class="prompt-form" hidden>
      <textarea rows="2" required placeholder="Tell the agent what to do next"></textarea>
      <button type="submit" class="primary">Send</button>
    </form>
  </li>
</template>
<script src="app.js"></script>
</body>
</html>
HERDR_PY_EOF
cat > herdr_py/web/style.css <<'HERDR_PY_EOF'
:root {
  color-scheme: dark;
  --bg: #121418; --panel: #1b1e24; --line: #2c313a; --text: #e3e6eb; --muted: #9aa3ae;
  --accent: #3b74c4; --ok: #3f9c5a; --warn: #c79a2e; --bad: #d0505c; --chip-text: #101214;
  --radius: 12px; --gap: 12px; --tap: 44px;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang TC", "Noto Sans CJK TC", sans-serif;
}
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) {
    color-scheme: light;
    --bg: #f5f6f8; --panel: #ffffff; --line: #dde1e6; --text: #15181d; --muted: #5d6673;
    --accent: #2f63ad; --ok: #2f8048; --warn: #9a7414; --bad: #b8323f; --chip-text: #ffffff;
  }
}
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--text); }
body { font-size: 16px; line-height: 1.45; -webkit-text-size-adjust: 100%; }
.bar { position: sticky; top: 0; z-index: 2; display: flex; align-items: center; justify-content: space-between;
  gap: var(--gap); padding: 12px 16px; padding-top: max(12px, env(safe-area-inset-top));
  background: var(--panel); border-bottom: 1px solid var(--line); }
.bar h1 { margin: 0; font-size: 18px; }
.conn { font-size: 13px; color: var(--muted); }
.conn.ok::before, .conn.bad::before { content: "●"; margin-right: 6px; }
.conn.ok::before { color: var(--ok); }
.conn.bad::before { color: var(--bad); }
main { max-width: 760px; margin: 0 auto; padding: 8px 16px 48px; }
h2 { font-size: 15px; color: var(--muted); margin: 18px 0 8px; text-transform: uppercase; letter-spacing: .04em; }
.count { display: inline-block; min-width: 22px; padding: 0 6px; border-radius: 11px; background: var(--bad); color: #fff;
  text-align: center; font-size: 13px; }
ul { list-style: none; margin: 0; padding: 0; }
.needs-list li, .agent { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
  padding: 12px; margin-bottom: var(--gap); }
.needs-list li { border-color: var(--bad); }
.needs-list p { margin: 6px 0 10px; overflow-wrap: anywhere; font-family: ui-monospace, Menlo, monospace; font-size: 14px; }
.head { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.name { font-size: 17px; }
.chip { padding: 2px 10px; border-radius: 999px; font-size: 13px; font-weight: 600; background: var(--muted); color: var(--chip-text); }
.chip[data-state="working"], .chip[data-state="starting"], .chip[data-state="retry"] { background: var(--warn); }
.chip[data-state="blocked"], .chip[data-state="error"] { background: var(--bad); color: #fff; }
.chip[data-state="idle"] { background: var(--ok); color: #fff; }
.meta { font-size: 13px; }
.muted { color: var(--muted); }
.activity { margin: 8px 0 0; font-family: ui-monospace, Menlo, monospace; font-size: 13px; }
.activity li { overflow-wrap: anywhere; padding: 2px 0; border-top: 1px dashed var(--line); }
.activity li[data-tone="ok"] { color: var(--ok); }
.activity li[data-tone="bad"], .activity li[data-tone="warn"] { color: var(--bad); }
.activity li[data-tone="dim"] { color: var(--muted); }
.stream { margin: 8px 0 0; font-size: 13px; overflow-wrap: anywhere; max-height: 4.5em; overflow: hidden; }
.actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 10px; }
button { min-height: var(--tap); padding: 0 16px; border-radius: 10px; border: 1px solid var(--line); background: transparent;
  color: var(--text); font: inherit; font-size: 15px; cursor: pointer; }
button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }
button.danger { border-color: var(--bad); color: var(--bad); }
button:disabled { opacity: .45; cursor: default; }
.prompt-form, #new-agent { display: grid; gap: 8px; margin-top: 10px; }
label { display: grid; gap: 4px; font-size: 14px; color: var(--muted); }
input, textarea { width: 100%; min-height: var(--tap); padding: 10px; border-radius: 10px; border: 1px solid var(--line);
  background: var(--bg); color: var(--text); font: inherit; font-size: 16px; }
details.new { margin-top: 18px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 12px; }
details.new summary { cursor: pointer; min-height: 28px; font-weight: 600; }
.toast { position: fixed; left: 16px; right: 16px; bottom: max(16px, env(safe-area-inset-bottom)); margin: 0 auto; max-width: 520px;
  text-align: center; pointer-events: none; color: var(--text); }
.toast:not(:empty) { padding: 10px 14px; background: var(--panel); border: 1px solid var(--line); border-radius: 10px; }
code { font-family: ui-monospace, Menlo, monospace; }
