"""Hub and policy tests against the fake OpenCode server (real HTTP client, real event stream)."""
import json
import os
import tempfile
import threading
import time
import unittest

from herdr_py.core import Hub, HubError
from herdr_py.opencode import OpenCode, start_stream_thread
from herdr_py.policy import Policy, PolicyError, describe, target_of

from fake_opencode import FakeOpenCode

RULES = [{"permission": "bash", "match": r"ls( -\w+)*", "action": "allow"},
         {"permission": "bash", "match": r"rm .*", "action": "deny", "message": "no deleting"},
         {"permission": "external_directory", "action": "deny"}]


def wait_for(cond, timeout=6.0, what="condition"):
    deadline = time.time() + timeout
    while time.time() < deadline:
        if cond():
            return
        time.sleep(0.02)
    raise AssertionError(f"timed out waiting for {what}")


class Clock:
    def __init__(self):
        self.now = 1000.0

    def __call__(self):
        return self.now


class HubTest(unittest.TestCase):
    def setUp(self):
        self.fake = FakeOpenCode(password="pw").start()
        self.client = OpenCode(self.fake.url, password="pw")
        self.tmp = tempfile.TemporaryDirectory()
        self.clock = Clock()
        self.hub = self.make_hub()
        self.stop, _ = start_stream_thread(self.client, self.hub.on_event, self.hub.on_stream_state)
        wait_for(lambda: self.fake.stream_count() == 1, what="event stream")

    def make_hub(self, **kw):
        return Hub(self.client, Policy(RULES, default="ask"), log_path=os.path.join(self.tmp.name, "events.jsonl"),
                   state_path=os.path.join(self.tmp.name, "state.json"), clock=self.clock, run=lambda fn: fn(), **kw)

    def tearDown(self):
        self.stop.set()
        self.fake.stop()
        self.hub.close()
        self.tmp.cleanup()

    def state(self, name="a"):
        return self.hub.get(name)["state"]

    def start(self, name="a", **kw):
        self.hub.start(name, "do it", **kw)
        return self.hub.agents[name].session_id

    def test_a_turn_goes_starting_working_idle_and_ignores_a_stale_idle(self):
        sid = self.start()
        self.assertEqual(self.state(), "starting")
        self.assertEqual(self.fake.prompts[0][1]["parts"][0]["text"], "do it")
        self.fake.emit("session.idle", sessionID=sid)  # left over from before the prompt reached OpenCode
        time.sleep(0.2)
        self.assertEqual(self.state(), "starting")
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        self.fake.emit("session.status", sessionID=sid, status={"type": "idle"})
        wait_for(lambda: self.state() == "idle")
        view = self.hub.get("a")
        self.assertEqual((view["turns"], self.hub.agents["a"].idles), (1, 1))

    def test_time_lost_to_the_model_provider_is_counted_apart(self):
        sid = self.start()
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        lost = lambda: self.hub.get("a")["provider_wait_s"]  # noqa: E731
        self.clock.now += 300  # the provider says nothing for 300 s, then OpenCode reports the failure and retries
        self.fake.emit("session.status", sessionID=sid,
                       status={"type": "retry", "attempt": 1, "message": "Provider response headers timed out after 300000ms"})
        wait_for(lambda: lost() == 300.0, what="the silence before the retry")
        self.clock.now += 2
        self.fake.emit("session.status", sessionID=sid, status={"type": "retry", "attempt": 2, "message": "Rate limit exceeded"})
        wait_for(lambda: lost() == 302.0, what="the second retry, counted once")
        self.clock.now += 5
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: lost() == 307.0, what="the retry until working again")
        self.clock.now += 100  # a slow model with no failure reported is the agent's own time
        self.fake.emit("session.status", sessionID=sid, status={"type": "idle"})
        wait_for(lambda: self.state() == "idle")
        self.assertEqual(lost(), 307.0)
        with open(os.path.join(self.tmp.name, "events.jsonl")) as handle:
            rows = [json.loads(line) for line in handle if '"provider_retry"' in line]
        self.assertEqual([(r["attempt"], r["provider_wait_s"]) for r in rows], [(1, 300.0), (2, 302.0)])
        self.assertIn("timed out", rows[0]["message"])

    def test_provider_time_counts_from_the_prompt_not_from_the_last_turn(self):
        sid = self.start()
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        self.fake.emit("session.status", sessionID=sid, status={"type": "idle"})
        wait_for(lambda: self.state() == "idle")
        self.clock.now += 3600  # an hour between turns: not the provider's
        self.hub.prompt("a", "next")
        self.clock.now += 300  # no busy reported: the provider fails first
        self.fake.emit("session.status", sessionID=sid, status={"type": "retry", "attempt": 1, "message": "Rate limit exceeded"})
        wait_for(lambda: self.state() == "retry")
        self.assertEqual(self.hub.get("a")["provider_wait_s"], 300.0)

    def test_the_transcript_marks_what_opencode_wrote_itself(self):
        sid = self.start()
        self.fake.messages[sid] = [
            {"info": {"role": "user"}, "parts": [{"type": "text", "text": "do it"}]},
            {"info": {"role": "user"}, "parts": [{"type": "compaction", "auto": True}]},
            {"info": {"role": "assistant", "mode": "compaction", "summary": True}, "parts": [{"type": "text", "text": "## Objective"}]},
            {"info": {"role": "user"}, "parts": [{"type": "text", "text": "Continue if you have next steps", "synthetic": True}]}]
        got = [(m["role"], m["kind"], m.get("synthetic", False)) for m in self.hub.transcript("a")]
        self.assertEqual(got, [("user", "text", False), ("user", "compaction", False), ("assistant", "text", False),
                               ("user", "text", True)])

    def test_policy_allows_denies_and_leaves_ask_for_a_human(self):
        sid = self.start()
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        ok = self.fake.ask_permission(sid, "bash", "ls -la")
        bad = self.fake.ask_permission(sid, "bash", "rm -rf /")
        wait_for(lambda: len(self.fake.replies) == 2, what="two policy replies")
        replies = {r[0]: r for r in self.fake.replies}
        self.assertEqual(replies[ok][1], "once")
        self.assertEqual(replies[bad][1:], ("reject", "no deleting"))
        human = self.fake.ask_permission(sid, "bash", "curl -sI https://example.com")
        wait_for(lambda: self.state() == "blocked", what="blocked")
        self.assertEqual([p["id"] for p in self.hub.pending()], [human])
        time.sleep(0.2)
        self.assertNotIn(human, {r[0] for r in self.fake.replies})  # nobody answered for the human
        self.hub.reply(human, "reject", "not now")
        wait_for(lambda: self.state() == "working", what="back to working")
        self.assertIn((human, "reject", "not now"), self.fake.replies)

    def test_requests_from_sessions_we_did_not_create_are_never_answered(self):
        self.start()
        self.fake.sessions["ses_other"] = {"id": "ses_other"}
        foreign = self.fake.ask_permission("ses_other", "bash", "ls")
        time.sleep(0.4)
        self.assertNotIn(foreign, {r[0] for r in self.fake.replies})
        self.assertEqual(self.hub.pending(), [])

    def test_subagent_requests_are_mapped_to_the_root_agent(self):
        sid = self.start()
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        child = self.fake.child(sid)
        ok = self.fake.ask_permission(child, "bash", "ls")
        wait_for(lambda: ok in {r[0] for r in self.fake.replies}, what="child request answered")
        self.assertIn(child, self.hub.get("a")["children"])
        self.fake.emit("session.idle", sessionID=child)
        time.sleep(0.2)
        self.assertEqual(self.state(), "working")  # a subagent finishing does not finish its parent
        early = self.fake.child(sid, announce=False)  # its request arrives before session.created
        far = self.fake.ask_permission(early, "external_directory", patterns=["/think/*"])
        wait_for(lambda: far in {r[0] for r in self.fake.replies}, what="early child request")
        self.assertEqual({r[0]: r[1] for r in self.fake.replies}[far], "reject")
        middle = self.fake.child(sid, announce=False)
        grandchild = self.fake.child(middle, announce=False)  # two unknown levels
        deep = self.fake.ask_permission(grandchild, "bash", "ls -1")
        wait_for(lambda: deep in {r[0] for r in self.fake.replies}, what="grandchild request")
        self.assertEqual(self.hub.root_of(grandchild), sid)

    def test_followups_then_time_budget_abort(self):
        sid = self.start(followups=["second"], budget_s=10)
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        self.fake.emit("session.status", sessionID=sid, status={"type": "idle"})
        wait_for(lambda: self.state() == "idle")
        self.hub.tick()
        self.assertEqual([p[1]["parts"][0]["text"] for p in self.fake.prompts], ["do it", "second"])
        self.assertEqual(self.state(), "starting")
        self.hub.tick()
        self.assertEqual(len(self.fake.prompts), 2)  # a follow-up is sent once
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        self.clock.now += 9
        self.hub.tick()
        self.assertEqual(self.fake.aborts, [])  # within budget
        self.clock.now += 2
        self.hub.tick()
        self.assertEqual(self.fake.aborts, [sid])
        self.assertEqual(self.state(), "aborted")
        self.fake.emit("session.error", sessionID=sid, error={"name": "MessageAbortedError"})
        self.fake.emit("session.idle", sessionID=sid)
        time.sleep(0.2)
        self.assertEqual(self.state(), "aborted")  # the abort's own error does not turn it into "error"

    def test_an_error_sticks_until_the_next_prompt(self):
        sid = self.start()
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        self.fake.emit("session.error", sessionID=sid, error={"name": "ProviderError", "data": {"message": "boom"}})
        wait_for(lambda: self.state() == "error")
        self.hub.prompt("a", "again")
        self.assertEqual(self.state(), "starting")

    def test_resync_after_a_dropped_stream(self):
        sid = self.start()
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        human = self.fake.ask_permission(sid, "bash", "curl x")
        wait_for(lambda: self.state() == "blocked")
        self.fake.drop_streams()
        wait_for(lambda: self.fake.stream_count() == 0, what="stream dropped")
        self.fake.pending.pop(human)  # answered elsewhere while we were away
        missed = self.fake.ask_permission(sid, "bash", "ls", announce=False)  # asked while we were away
        wait_for(lambda: missed in {r[0] for r in self.fake.replies}, timeout=8, what="missed request answered after resync")
        wait_for(lambda: self.hub.pending() == [], what="stale request dropped")

    def test_saves_from_many_threads_at_once_never_fail(self):
        # 2026-10-10: two members of an OpenCode team started at the same moment; both saved the state, and one save
        # renamed state.json.tmp after the other had already moved it away (FileNotFoundError), failing that turn
        self.start("a")
        errors = []

        def save_many():
            for _ in range(150):
                try:
                    self.hub.save()
                except Exception as exc:  # noqa: BLE001 - what the test counts
                    errors.append(f"{type(exc).__name__}: {exc}")
        threads = [threading.Thread(target=save_many) for _ in range(8)]
        for th in threads:
            th.start()
        for th in threads:
            th.join()
        self.assertEqual(errors[:3], [])
        with open(os.path.join(self.tmp.name, "state.json")) as handle:
            self.assertEqual([a["name"] for a in json.load(handle)["agents"]], ["a"])

    def test_state_file_reattaches_agents_and_children(self):
        sid = self.start()
        child = self.fake.child(sid)
        self.fake.ask_permission(child, "bash", "ls")
        wait_for(lambda: child in self.hub.get("a")["children"])
        self.hub.save()
        again = self.make_hub()
        self.assertEqual(again.load(), 1)
        self.assertEqual(again.agents["a"].session_id, sid)
        self.assertEqual(again.root_of(child), sid)
        again.close()

    def test_fresh_start_gives_a_finished_agent_a_new_session_and_ignores_the_old_one(self):
        old = self.start()
        self.fake.emit("session.status", sessionID=old, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        with self.assertRaises(HubError):  # still working: a new session would orphan the running turn
            self.hub.start("a", "again", fresh=True)
        self.fake.emit("session.status", sessionID=old, status={"type": "idle"})
        wait_for(lambda: self.state() == "idle")
        with self.assertRaises(HubError):  # without fresh the name is still taken
            self.hub.start("a", "again")
        self.hub.max_agents = 1  # a new session for the same name is not a new agent
        self.hub.start("a", "again", fresh=True)
        agent = self.hub.agents["a"]
        self.assertNotEqual(agent.session_id, old)
        self.assertEqual((agent.past_sessions, agent.turns, len(self.hub.agents)), ([old], 2, 1))
        self.assertEqual(self.fake.prompts[-1][0], agent.session_id)
        self.assertEqual(self.state(), "starting")
        self.fake.emit("session.status", sessionID=old, status={"type": "busy"})  # a late event from the old session
        time.sleep(0.2)
        self.assertEqual(self.state(), "starting")
        self.fake.emit("session.status", sessionID=agent.session_id, status={"type": "busy"})
        wait_for(lambda: self.state() == "working")
        self.hub.save()
        again = self.make_hub()
        again.load()
        self.assertEqual(again.agents["a"].past_sessions, [old])
        again.close()

    def test_a_slow_subscriber_is_told_events_were_lost(self):
        hub = self.make_hub(max_queue=3)
        q = hub.subscribe()
        with hub.lock:
            for i in range(5):
                hub.emit({"type": "x", "i": i})
        items = []
        while not q.empty():
            items.append(q.get())
        self.assertEqual(items[-1]["type"], "events_lost")
        self.assertNotIn(q, hub.subscribers)
        hub.close()

    def test_wait_returns_on_the_state_and_times_out_otherwise(self):
        sid = self.start()
        with self.assertRaises(HubError):
            self.hub.wait("a", until=["idle"], timeout=0.3)
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        self.fake.emit("session.idle", sessionID=sid)
        self.assertEqual(self.hub.wait("a", until=["idle"], timeout=5)["state"], "idle")

    def test_the_log_is_written_line_by_line(self):
        self.start()
        lines = open(os.path.join(self.tmp.name, "events.jsonl")).read().splitlines()  # not closed yet: must be flushed
        self.assertTrue(any(json.loads(l).get("hub") == "start" for l in lines))


    def test_tool_switches_go_with_every_prompt_and_stay_in_the_state_file(self):
        planner = self.hub.start("p", "plan", tools={"*": False})["session_id"]
        worker = self.hub.start("w", "work")["session_id"]
        self.hub.prompt("p", "once more")
        sent = {}
        for sid, body in self.fake.prompts:
            sent.setdefault(sid, []).append(body.get("tools"))
        self.assertEqual(sent[planner], [{"*": False}, {"*": False}])
        self.assertEqual(sent[worker], [None])  # no switches: OpenCode's own defaults
        self.assertEqual((self.hub.get("p")["tools"], self.hub.get("w")["tools"]), ({"*": False}, {}))
        self.hub.save()
        again = self.make_hub()  # a daemon restarted on the same state file
        self.addCleanup(again.close)
        self.assertEqual(again.load(), 2)
        again.prompt("p", "after a restart")
        self.assertEqual(self.fake.prompts[-1], (planner, dict(self.fake.prompts[-1][1], tools={"*": False})))
        for bad in ({"*": "no"}, ["*"], {1: False}):
            with self.assertRaises(HubError):
                self.hub.start("x", "go", tools=bad)
        self.assertNotIn("x", [a["name"] for a in self.hub.list()])


    def test_a_prompt_after_an_abort_waits_for_the_aborted_turns_end(self):
        # OpenCode reports an aborted turn's end (MessageAbortedError, then idle) on its own time; read after the next
        # prompt it was that turn's end, and the late error marked the new turn "error" (seen on RHEL 8 in test_team)
        for name, statuses, state in (("a", ["busy"], "working"), ("r", ["busy", "retry"], "retry")):  # or retrying
            sid = self.hub.start(name, "work")["session_id"]
            for status in statuses:  # as OpenCode reports them: busy first, retry when the provider failed
                self.fake.emit("session.status", sessionID=sid, status={"type": status})
            wait_for(lambda: self.state(name) == state, what=state)
            self.hub.abort(name)
            late = threading.Timer(0.3, lambda sid=sid: (self.fake.emit("session.error", sessionID=sid, error={"name": "MessageAbortedError"}),
                                                         self.fake.emit("session.idle", sessionID=sid)))
            started = time.monotonic()  # before the timer starts: read after it, a busy machine that held this thread up
            late.start()                # in between shortened the wait measured (0.23 s seen under the push gate's tests)
            self.addCleanup(late.cancel)
            self.hub.prompt(name, "again")
            waited = time.monotonic() - started
            self.assertTrue(0.25 <= waited < 2, waited)  # it waited for that end, no longer
            time.sleep(0.2)
            self.assertEqual(self.state(name), "starting")  # the new turn, waiting for OpenCode to start it: not "error"

    def test_a_prompt_after_an_abort_goes_on_when_the_end_never_comes(self):
        self.hub.settle_s = 0.3
        sid = self.hub.start("a", "work")["session_id"]
        self.fake.emit("session.status", sessionID=sid, status={"type": "busy"})
        wait_for(lambda: self.state() == "working", what="busy")
        self.hub.abort("a")
        started = time.time()
        self.hub.prompt("a", "again")
        self.assertLess(abs(time.time() - started - 0.3), 0.25)
        self.assertIn("the aborted turn's end did not come in 0.3 s", [a["text"] for a in self.hub.get("a")["activity"]])
        idle = self.hub.start("b", "work")["session_id"]
        self.fake.turn(idle, "done")
        wait_for(lambda: self.state("b") == "idle", what="b idle")
        self.hub.abort("b")  # nothing to end: the next prompt does not wait
        started = time.time()
        self.hub.prompt("b", "again")
        self.assertLess(time.time() - started, 0.2)
        busy = self.hub.start("c", "work")["session_id"]
        self.fake.emit("session.status", sessionID=busy, status={"type": "busy"})
        wait_for(lambda: self.state("c") == "working", what="c busy")
        real = self.client.abort
        self.client.abort = lambda *a, **k: (_ for _ in ()).throw(OSError("connection refused"))
        try:
            with self.assertRaises(OSError):
                self.hub.abort("c")  # nothing was aborted, so no end is coming: the next prompt does not wait
        finally:
            self.client.abort = real
        started = time.time()
        self.hub.prompt("c", "again")
        self.assertLess(time.time() - started, 0.2)


class PolicyTest(unittest.TestCase):
    def test_first_matching_rule_wins_and_regex_must_match_the_whole_target(self):
        p = Policy(RULES, default="ask")
        self.assertEqual(p.decide({"permission": "bash", "metadata": {"command": "ls -la"}})[0], "allow")
        self.assertEqual(p.decide({"permission": "bash", "metadata": {"command": "ls -la; rm -rf /"}})[0], "ask")
        self.assertEqual(p.decide({"permission": "bash", "metadata": {"command": "rm x"}})[:2], ("deny", "no deleting"))
        self.assertEqual(p.decide({"permission": "external_directory", "patterns": ["/tmp/*"], "metadata": {"command": "ls"}})[0], "deny")
        self.assertEqual(p.decide({"permission": "edit", "patterns": ["a.py"]})[0], "ask")

    def test_agent_globs_and_bad_rules(self):
        p = Policy([{"permission": "*", "agent": "trusted-*", "action": "allow"}], default="deny")
        self.assertEqual(p.decide({"permission": "bash", "metadata": {"command": "x"}}, agent="trusted-1")[0], "allow")
        self.assertEqual(p.decide({"permission": "bash", "metadata": {"command": "x"}}, agent="other")[0], "deny")
        with self.assertRaises(PolicyError):
            Policy([{"permission": "bash", "action": "maybe"}])
        with self.assertRaises(PolicyError):
            Policy([{"permission": "bash", "match": "(", "action": "allow"}])

    def test_descriptions_show_the_type_not_just_the_command(self):
        req = {"permission": "external_directory", "patterns": ["/think/*"], "metadata": {"command": "ls"}}
        self.assertEqual(target_of(req), "/think/*")
        self.assertEqual(describe(req), "access outside the project: /think/* (via ls)")
        self.assertEqual(describe({"permission": "bash", "metadata": {"command": "ls"}, "patterns": ["ls"]}), "run ls")


if __name__ == "__main__":
    unittest.main()


class FolderTest(unittest.TestCase):
    """Agents whose sessions work in a folder of their own (a DAG step's clone), against a fake that behaves as
    OpenCode 1.18 (checked on the real server): such a session is reached with ?directory= and its events come only on
    GET /global/event."""

    def setUp(self):
        self.fake = FakeOpenCode(password="pw", global_events=True).start()
        self.client = OpenCode(self.fake.url, password="pw")
        self.tmp = tempfile.TemporaryDirectory()
        rules = RULES + [{"permission": "edit", "action": "allow"}]
        self.hub = Hub(self.client, Policy(rules, default="ask"), state_path=os.path.join(self.tmp.name, "state.json"),
                       clock=Clock(), run=lambda fn: fn())
        self.stop, _ = start_stream_thread(self.client, self.hub.on_event, self.hub.on_stream_state)
        wait_for(lambda: self.fake.stream_count() == 1, what="event stream")

    def tearDown(self):
        self.stop.set()
        self.fake.stop()
        self.hub.close()
        self.tmp.cleanup()

    def calls(self, method, path):
        return [d for m, p, d in self.fake.requests if m == method and p == path]

    def test_an_agent_in_a_folder_is_reached_there_and_followed_on_the_global_stream(self):
        sid = self.hub.start("a", "do it", directory="/work/step-1")["session_id"]
        self.assertEqual(self.fake.sessions[sid]["directory"], "/work/step-1")
        self.assertEqual(self.calls("POST", f"/session/{sid}/prompt_async"), ["/work/step-1"])
        self.assertEqual(self.calls("GET", "/global/event"), [None])  # one stream for every folder
        self.fake.turn(sid, "done")
        wait_for(lambda: self.hub.get("a")["state"] == "idle", what="idle from the global stream")
        self.assertEqual(self.hub.transcript("a")[-1]["text"], "done")
        self.assertEqual(self.calls("GET", f"/session/{sid}/message"), ["/work/step-1"])
        self.hub.abort("a")
        self.assertEqual(self.calls("POST", f"/session/{sid}/abort"), ["/work/step-1"])
        self.assertEqual(self.hub.get("a")["directory"], "/work/step-1")

    def test_a_permission_in_a_folder_is_answered_there(self):
        sid = self.hub.start("a", "do it", directory="/work/step-1")["session_id"]
        rid = self.fake.ask_permission(sid, "bash", "ls")
        wait_for(lambda: self.fake.replies, what="the policy's answer")
        self.assertEqual(self.fake.replies[0][:2], (rid, "once"))
        self.assertEqual(self.calls("POST", f"/permission/{rid}/reply"), ["/work/step-1"])

    def test_denied_kinds_are_refused_before_the_policy_is_asked(self):
        sid = self.hub.start("r", "look only", directory="/work/step-2", deny=["edit", "bash"])["session_id"]
        rid = self.fake.ask_permission(sid, "edit", patterns=["deck.json"])  # the policy would allow this edit
        wait_for(lambda: self.fake.replies, what="the refusal")
        self.assertEqual(self.fake.replies[0][:2], (rid, "reject"))
        self.assertIn("only reads", self.fake.replies[0][2])
        self.assertEqual(self.hub.agent("r").decisions[-1][-1], "agent.deny")
        other = self.hub.start("w", "write", directory="/work/step-3")["session_id"]
        rid2 = self.fake.ask_permission(other, "edit", patterns=["deck.json"])
        wait_for(lambda: len(self.fake.replies) == 2, what="the policy's answer")
        self.assertEqual(self.fake.replies[1][:2], (rid2, "once"))  # without deny the policy decides

    def test_resync_asks_every_folder_in_use(self):
        home = self.hub.start("h", "here")["session_id"]
        away = self.hub.start("f", "there", directory="/work/step-1")["session_id"]
        self.fake.drop_streams()
        self.fake.status[away] = {"type": "busy"}
        rid = self.fake.ask_permission(away, "bash", "make", announce=False)  # asked while the stream was down
        wait_for(lambda: self.fake.stream_count() == 1, what="reconnect")
        wait_for(lambda: self.hub.get("f")["state"] == "blocked", what="the missed request")
        self.assertIn("/work/step-1", self.calls("GET", "/session/status"))
        self.assertIn(None, self.calls("GET", "/session/status"))
        self.assertEqual([p["id"] for p in self.hub.pending("f")], [rid])
        self.assertEqual(self.hub.get("h")["state"], "starting")  # the other folder's status did not touch it
        self.assertNotEqual(home, away)

    def test_the_state_file_keeps_each_agents_folder_and_refusals(self):
        self.hub.start("r", "look only", directory="/work/step-2", deny=["edit"])
        self.hub.save()
        again = Hub(self.client, Policy(RULES), state_path=os.path.join(self.tmp.name, "state.json"), clock=Clock(), run=lambda fn: fn())
        self.assertEqual(again.load(), 1)
        view = again.get("r")
        self.assertEqual((view["directory"], view["deny"]), ("/work/step-2", ["edit"]))
        again.close()
HERDR_PY_EOF
cat > tests/test_dag.py <<'HERDR_PY_EOF'
"""DAG dispatch (dag.py): plans are checked before anything runs; a step starts only after every step it needs has
passed, works in its own clone that holds the output commits of exactly those steps, and is judged by a program the
member cannot change; failures retry from the failed commit, block what needs them, or stop the run when the setup
broke; a run can be resumed without running passed steps again, and re-judged in fresh clones.
Members here are programs (command members), so no model is called."""
import contextlib
import io
import json
import os
import shutil
import subprocess
import sys
import tempfile
import textwrap
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.dirname(HERE))

from herdr_py import dag  # noqa: E402

HAVE_GIT = shutil.which("git") is not None

# A member program: what it does is written per step and attempt in DAG_TEST_SCRIPT; every prompt goes to DAG_TEST_LOG.
MEMBER = r'''
import json, os, re, subprocess, sys, time
prompt = sys.stdin.read()
node = re.search(r"doing step (\S+) of the plan", prompt).group(1)
log = os.environ["DAG_TEST_LOG"]
os.makedirs(log, exist_ok=True)
n = len([f for f in os.listdir(log) if f.startswith(node + "-")])
with open(os.path.join(log, "%s-%d.txt" % (node, n + 1)), "w") as handle:
    handle.write(prompt)
plan = json.load(open(os.environ["DAG_TEST_SCRIPT"])).get(node, [])
act = plan[min(n, len(plan) - 1)] if plan else {}
time.sleep(act.get("sleep", 0))
seen = []
for name, text in act.get("write", {}).items():
    with open(name, "w") as handle:
        handle.write(text)
for args in act.get("git", []):
    subprocess.run(["git"] + args, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                   env=dict(os.environ, GIT_AUTHOR_NAME="m", GIT_AUTHOR_EMAIL="m@x", GIT_COMMITTER_NAME="m", GIT_COMMITTER_EMAIL="m@x"))
if act.get("look"):
    refs = subprocess.run(["git", "for-each-ref", "--format=%(refname)"], stdout=subprocess.PIPE, universal_newlines=True).stdout.split()
    seen = ["refs: " + " ".join(sorted(refs)), "files: " + " ".join(sorted(f for f in os.listdir(".") if not f.startswith(".")))]
if act.get("append_to"):
    with open(act["append_to"], "a") as handle:
        handle.write("\n# changed by a member\n")
print(act.get("reply", "did " + node))
print("\n".join(seen))
sys.exit(act.get("exit", 0))
'''

# A judge: its rules per step come from DAG_TEST_JUDGE; the reply file is the last argument (coop.py's contract).
JUDGE = r'''
import json, os, sys
rules = json.loads(os.environ.get("DAG_TEST_JUDGE", "{}")).get(os.environ["HERDR_DAG_NODE"], {})
reply = open(sys.argv[-1]).read()
if rules.get("garbage"):
    print("not json")
    sys.exit(0)
if rules.get("status"):
    print(json.dumps({"status": rules["status"], "score": 1}))
    sys.exit(0)
problems = []
for name, text in rules.get("files", {}).items():
    if not os.path.isfile(name) or text not in open(name).read():
        problems.append("%s should contain %r" % (name, text))
for name in rules.get("absent", []):
    if os.path.exists(name):
        problems.append("%s should not be there" % name)
if rules.get("reply") and rules["reply"] not in reply:
    problems.append("the reply should say %r" % rules["reply"])
if rules.get("env") and not os.environ.get(rules["env"]):
    problems.append("%s is not set" % rules["env"])
print(json.dumps({"status": "invalid" if problems else "valid", "score": 1 if not problems else 0,
                  "detail": "; ".join(problems) or "ok"}))
'''


def sh(cwd, *args):
    return subprocess.run(list(args), cwd=cwd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                          universal_newlines=True, env=dict(os.environ, GIT_AUTHOR_NAME="t", GIT_AUTHOR_EMAIL="t@x",
                                                            GIT_COMMITTER_NAME="t", GIT_COMMITTER_EMAIL="t@x")).stdout.strip()


class Base(unittest.TestCase):
    def setUp(self):
        self.dir = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.dir, True)
        self.plans = os.path.join(self.dir, "plan")
        os.makedirs(os.path.join(self.plans, "tasks"))
        for name, body in (("member.py", MEMBER), ("judge.py", JUDGE)):
            with open(os.path.join(self.plans, name), "w") as handle:
                handle.write(textwrap.dedent(body))
        self.log = os.path.join(self.dir, "prompts")
        self.script_path = os.path.join(self.dir, "script.json")
        saved = {k: os.environ.get(k) for k in ("DAG_TEST_LOG", "DAG_TEST_SCRIPT", "DAG_TEST_JUDGE", "FLAKY")}
        self.addCleanup(lambda: [os.environ.pop(k, None) if v is None else os.environ.__setitem__(k, v) for k, v in saved.items()])
        os.environ.update(DAG_TEST_LOG=self.log, DAG_TEST_SCRIPT=self.script_path)
        self.script({})
        self.judge_rules({})

    def script(self, steps):
        with open(self.script_path, "w") as handle:
            json.dump(steps, handle)

    def judge_rules(self, rules):
        os.environ["DAG_TEST_JUDGE"] = json.dumps(rules)

    def repo(self):
        repo = os.path.join(self.dir, "repo")
        os.makedirs(repo)
        sh(repo, "git", "init", "-q")
        sh(repo, "git", "symbolic-ref", "HEAD", "refs/heads/main")  # the same branch name whatever git's default is (CI's is master)
        with open(os.path.join(repo, "base.txt"), "w") as handle:
            handle.write("base\n")
        sh(repo, "git", "add", "-A")
        sh(repo, "git", "commit", "-q", "-m", "base")
        return repo

    def plan(self, nodes, repo=True, name="p", **extra):
        for n in nodes:
            n.setdefault("member", "m%s=command:%s -B member.py" % (n["id"], sys.executable))
            n.setdefault("judge", "%s -B judge.py" % sys.executable)
            n.setdefault("task", "tasks/%s.md" % n["id"])
            path = os.path.join(self.plans, n["task"])
            if not os.path.exists(path):
                with open(path, "w") as handle:
                    handle.write("Do step %s well.\n" % n["id"])
        body = dict(extra, name=name, nodes=nodes)
        if repo:
            body["repo"] = os.path.relpath(self.repo() if repo is True else repo, self.plans)
        path = os.path.join(self.plans, "plan.json")
        with open(path, "w") as handle:
            json.dump(body, handle)
        return path

    def run_main(self, *args):
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = dag.main(list(args))
        return code, out.getvalue(), err.getvalue()

    def prompts(self, node):
        return [open(os.path.join(self.log, f)).read() for f in sorted(os.listdir(self.log)) if f.startswith(node + "-")]

    def events(self, out):
        with open(os.path.join(out, "events.jsonl")) as handle:
            return [json.loads(line) for line in handle]

    def summary(self, out):
        with open(os.path.join(out, "summary.json")) as handle:
            return json.load(handle)


class PlanTest(Base):
    def test_every_mistake_in_a_plan_is_reported_at_once(self):
        path = os.path.join(self.plans, "bad.json")
        with open(path, "w") as handle:
            json.dump({"nodes": [
                {"id": "A", "member": "a=codex", "task": "tasks/none.md", "judge": "x", "retries": -1, "colour": "red"},
                {"id": "A", "member": "a=codex", "task": "t", "judge": "x"},
                {"id": "B", "member": "a=claude", "task": "t", "needs": ["B", "Z"], "access": "admin", "judge_mode": "loud"},
                {"id": "9C", "member": "c=codex", "task": "t", "judge": "x"},
                {"id": "D", "member": "nobody", "task": "t", "judge": ""},
                {"id": "E", "member": "e=codex", "task": "t", "judge": "x", "needs": ["D"], "start": "merge"},
                {"id": "F", "member": "f=codex", "task": "t", "judge": "x", "start": "Q"}]}, handle)
        with self.assertRaises(dag.PlanError) as caught:
            dag.load_plan(path)
        said = str(caught.exception)
        for words in ("task file tasks/none.md not found", "retries is a whole number", "unknown fields colour",
                      "two nodes have this id", "judge is required", "needs itself", "needs Z, which is not a node",
                      "access is write or read", "judge_mode is json or exit", "node 4: the id is letters",
                      "member a is not the same as in node A", "NAME=BACKEND", "node E: start merge needs two or more",
                      "node F: start is base, merge or one of its needs", "start only means something with a repo"):
            self.assertIn(words, said)

    def test_a_cycle_is_refused_and_named(self):
        path = self.plan([{"id": "A", "needs": ["C"]}, {"id": "B", "needs": ["A"]}, {"id": "C", "needs": ["B"]}], repo=False)
        with self.assertRaises(dag.PlanError) as caught:
            dag.load_plan(path)
        self.assertIn("the needs make a cycle: A -> C -> B -> A", str(caught.exception))

    def test_levels_and_the_check_command(self):
        path = self.plan([{"id": "A"}, {"id": "B", "needs": ["A"]}, {"id": "C", "needs": ["A"]}, {"id": "D", "needs": ["C", "B"]}],
                         repo=False)
        plan = dag.load_plan(path)
        self.assertEqual(dag.levels(plan), {"A": 0, "B": 1, "C": 1, "D": 2})
        code, out, _ = self.run_main(path, "--check")
        self.assertEqual(code, 0)
        self.assertIn("level 2: D (mD, after C, B)", out)

    def test_judge_and_member_files_resolve_against_the_plan_folder(self):
        plan = dag.load_plan(self.plan([{"id": "A", "judge": "python3 judge.py --strict"}], repo=False))
        node = plan["nodes"]["A"]
        self.assertEqual(node["judge_argv"], ["python3", os.path.join(self.plans, "judge.py"), "--strict"])
        self.assertIn(os.path.join(self.plans, "member.py"), node["member"]["command"])  # run in a clone, found anyway

    def test_a_repository_is_checked_and_opencode_members_can_use_one(self):
        with self.assertRaises(dag.PlanError) as caught:
            dag.load_plan(self.plan([{"id": "A"}], repo=os.path.join(self.dir, "plan")))
        # a machine without git (the RHEL 8 test image) is told so instead of crashing
        self.assertIn("is not a git repository" if HAVE_GIT else "git is not installed", str(caught.exception))
        if HAVE_GIT:
            plan = dag.load_plan(self.plan([{"id": "A", "member": "o=opencode"}]))
            self.assertEqual(plan["nodes"]["A"]["member"]["backend"], "opencode")


@unittest.skipUnless(HAVE_GIT, "git is not installed")
class RunTest(Base):
    def test_two_independent_steps_then_one_that_builds_on_both(self):
        self.script({"W1": [{"write": {"a.txt": "A\n"}, "look": True, "sleep": 1, "reply": "wrote a.txt"}],
                     "W2": [{"write": {"b.txt": "B\n"}, "look": True, "sleep": 1, "reply": "wrote b.txt"}],
                     "W3": [{"look": True, "git": [["merge", "-q", "--no-edit", "refs/dag/W1", "refs/dag/W2"]], "reply": "merged"}]})
        self.judge_rules({"W1": {"files": {"a.txt": "A"}, "absent": ["b.txt"]}, "W2": {"files": {"b.txt": "B"}, "absent": ["a.txt"]},
                          "W3": {"files": {"a.txt": "A", "b.txt": "B", "base.txt": "base"}}})
        path = self.plan([{"id": "W1"}, {"id": "W2"}, {"id": "W3", "needs": ["W1", "W2"]}])
        repo = os.path.join(self.dir, "repo")
        refs_before = sh(repo, "git", "for-each-ref")
        out = os.path.join(self.dir, "run")
        code, said, err = self.run_main(path, "--out", out, "--parallel", "2")
        self.assertEqual(code, 0, said + err)
        s = self.summary(out)
        self.assertEqual((s["passed"], s["failed"], s["blocked"], s["released_early"], s["dispatched_after_pass"]), (3, 0, 0, 0, 0))
        events = self.events(out)
        seq = {(e["kind"], e.get("node")): e["seq"] for e in events}
        # W1 and W2 ran at the same time; W3 started only after both had passed
        self.assertLess(seq[("node.dispatch", "W2")], seq[("node.return", "W1")])
        self.assertGreater(seq[("node.dispatch", "W3")], max(seq[("node.pass", "W1")], seq[("node.pass", "W2")]))
        self.assertGreater(s["parallelism"], 1.2)
        # isolation: W1's clone held no other step's branch and no file of W2; its prompt never named W2
        w1 = self.prompts("W1")[0]
        self.assertNotIn("W2", w1)
        w1_pass = [e for e in events if e["kind"] == "node.pass" and e["node"] == "W1"][0]
        with open(os.path.join(out, "replies", w1_pass["reply"] + ".txt")) as handle:
            w1_reply = handle.read()
        refs = [line for line in w1_reply.splitlines() if line.startswith("refs: ")][0]
        self.assertEqual(refs, "refs: refs/heads/dag-work refs/heads/main")  # its own branch and the base repository's
        self.assertIn("files: a.txt base.txt", w1_reply)  # its own file and the base's: nothing of W2
        # W3 saw exactly its two upstream commits, with their summaries and diffs
        w3 = self.prompts("W3")[0]
        for words in ("It builds on W1, W2.", "Step W1 (done by mW1) passed the judge with score 1", "wrote a.txt",
                      "refs/dag/W1", "+A", "refs/dag/W2", "+B"):
            self.assertIn(words, w3)
        sha3 = s["nodes"]["W3"]["sha"]
        tree = sh(os.path.join(out, "workspaces", "W3-1"), "git", "ls-tree", "--name-only", sha3).split()
        self.assertEqual(sorted(tree), ["a.txt", "b.txt", "base.txt"])
        self.assertEqual(sh(repo, "git", "for-each-ref"), refs_before)  # the user's repository got nothing
        page = open(os.path.join(out, "view.html")).read()
        for words in ("DAG p", ">W1<", ">W3<", "edge done", "3 passed"):
            self.assertIn(words, page)
        self.assertEqual(sh(os.path.join(out, "workspaces", "W1-1"), "git", "remote"), "")  # nothing to push to

    def test_where_a_steps_files_start(self):
        self.script({"A": [{"write": {"a.txt": "A\n"}, "look": True}], "B": [{"write": {"b.txt": "B\n"}, "look": True}],
                     "AB": [{"look": True}], "M": [{"look": True}], "PickA": [{"look": True}], "Next": [{"look": True}]})
        out = os.path.join(self.dir, "run")
        code, said, err = self.run_main(self.plan([
            {"id": "A"}, {"id": "B"},
            {"id": "AB", "needs": ["A", "B"]},                     # several needs: the base, to compare and combine
            {"id": "M", "needs": ["A", "B"], "start": "merge"},    # merged first by the program
            {"id": "PickA", "needs": ["A", "B"], "start": "A"},
            {"id": "Next", "needs": ["PickA"]}]), "--out", out)   # one need: continue from its output
        self.assertEqual(code, 0, said + err)
        looked = {}
        for e in self.events(out):
            if e["kind"] == "node.pass":
                with open(os.path.join(out, "replies", e["reply"] + ".txt")) as handle:
                    looked[e["node"]] = [line for line in handle.read().splitlines() if line.startswith("files: ")][0]
        self.assertEqual(looked, {"A": "files: a.txt base.txt", "B": "files: b.txt base.txt", "AB": "files: base.txt",
                                  "M": "files: a.txt b.txt base.txt", "PickA": "files: a.txt base.txt",
                                  "Next": "files: a.txt base.txt"})
        self.assertIn("(the outputs of A and B merged)", self.prompts("M")[0])
        self.assertIn("(the output of step PickA)", self.prompts("Next")[0])
        self.assertIn("(the base commit)", self.prompts("AB")[0])

    def test_outputs_that_do_not_merge_fail_the_step_and_name_the_files(self):
        self.script({"A": [{"write": {"base.txt": "from A\n"}}], "B": [{"write": {"base.txt": "from B\n"}}]})
        out = os.path.join(self.dir, "run")
        code, said, _ = self.run_main(self.plan([{"id": "A"}, {"id": "B"}, {"id": "M", "needs": ["A", "B"], "start": "merge"}]),
                                      "--out", out)
        self.assertEqual(code, 1)  # the plan's problem, not a broken setup
        s = self.summary(out)
        self.assertEqual((s["nodes"]["M"]["state"], s["stopped"]), ("failed", None))
        self.assertIn("do not merge cleanly (conflicts in base.txt)", s["nodes"]["M"]["detail"])
        self.assertEqual(self.prompts("M"), [])

    def test_a_failed_attempt_is_tried_again_from_its_commit_with_the_judges_words(self):
        self.script({"A": [{"write": {"a.txt": "wrong\n"}}, {"write": {"a.txt": "right\n"}, "look": True}]})
        self.judge_rules({"A": {"files": {"a.txt": "right"}}})
        out = os.path.join(self.dir, "run")
        code, said, err = self.run_main(self.plan([{"id": "A", "retries": 1}]), "--out", out)
        self.assertEqual(code, 0, said + err)
        first, second = self.prompts("A")
        self.assertNotIn("previous attempt", first)
        self.assertIn("Your previous attempt did not pass the judge: a.txt should contain 'right'", second)
        self.assertIn("starts from that attempt's commit", second)
        events = self.events(out)
        retry = [e for e in events if e["kind"] == "node.retry"][0]
        second_start = [e for e in events if e["kind"] == "node.dispatch" and e["attempt"] == 2][0]["start"]
        self.assertEqual(second_start, retry["prev"]["sha"])  # built on the failed attempt, not on the base
        self.assertEqual(self.summary(out)["nodes"]["A"]["attempts"], 2)

    def test_a_step_that_fails_blocks_what_needs_it_and_the_rest_goes_on(self):
        self.script({"A": [{"write": {"a.txt": "wrong\n"}}], "C": [{"write": {"c.txt": "C\n"}}]})
        self.judge_rules({"A": {"files": {"a.txt": "right"}}, "C": {"files": {"c.txt": "C"}}})
        out = os.path.join(self.dir, "run")
        code, said, _ = self.run_main(self.plan([{"id": "A"}, {"id": "B", "needs": ["A"]}, {"id": "D", "needs": ["B"]},
                                                 {"id": "C"}]), "--out", out, "--parallel", "1")
        self.assertEqual(code, 1)
        s = self.summary(out)
        self.assertEqual({n: v["state"] for n, v in s["nodes"].items()},
                         {"A": "failed", "B": "blocked", "D": "blocked", "C": "passed"})
        self.assertEqual(self.prompts("B"), [])  # never dispatched
        self.assertIn("did not pass after 1 attempt(s): a.txt should contain 'right'", said)

    def test_a_broken_backend_stops_new_steps_unless_keep_going(self):
        self.script({"A": [{"exit": 3}], "B": [{}]})
        path = self.plan([{"id": "A"}, {"id": "B"}])
        out = os.path.join(self.dir, "run")
        code, said, _ = self.run_main(path, "--out", out, "--parallel", "1")
        self.assertEqual(code, 3)
        s = self.summary(out)
        self.assertEqual((s["nodes"]["A"]["state"], s["nodes"]["B"]["state"]), ("failed", "waiting"))
        self.assertIn("the member's backend ended error", s["stopped"])
        code, _, _ = self.run_main(path, "--out", os.path.join(self.dir, "run2"), "--parallel", "1", "--keep-going")
        s = self.summary(os.path.join(self.dir, "run2"))
        self.assertEqual((code, s["nodes"]["B"]["state"], s["stopped"]), (1, "passed", None))

    def test_a_judge_that_breaks_is_a_judge_error_not_a_fail(self):
        self.judge_rules({"A": {"garbage": True}})
        out = os.path.join(self.dir, "run")
        code, _, _ = self.run_main(self.plan([{"id": "A", "retries": 2}]), "--out", out)
        self.assertEqual(code, 3)
        fail = [e for e in self.events(out) if e["kind"] == "node.fail"][0]
        self.assertTrue(fail["infra"])
        self.assertIn("the judge failed", fail["why"])
        self.assertEqual(len(self.prompts("A")), 1)  # a broken judge is not a reason to try the member again

    def test_a_judge_status_other_than_valid_or_invalid_is_a_judge_error(self):
        self.judge_rules({"A": {"status": "maybe"}})
        out = os.path.join(self.dir, "run")
        self.assertEqual(self.run_main(self.plan([{"id": "A"}]), "--out", out)[0], 3)
        self.assertIn("the judge said status 'maybe'", self.summary(out)["nodes"]["A"]["detail"])

    def test_a_member_over_its_time_limit_fails_its_attempt_not_the_run(self):
        self.script({"A": [{"sleep": 5}], "B": [{}]})
        out = os.path.join(self.dir, "run")
        code, said, _ = self.run_main(self.plan([{"id": "A", "timeout": 1}, {"id": "B"}]), "--out", out, "--parallel", "1")
        self.assertEqual(code, 1)  # the member's problem: the run went on (exit 3 would mean the setup broke)
        s = self.summary(out)
        self.assertEqual((s["nodes"]["A"]["state"], s["nodes"]["B"]["state"], s["stopped"]), ("failed", "passed", None))
        self.assertIn("the member's turn ended timeout (limit 1 s)", s["nodes"]["A"]["detail"])

    def test_a_step_sees_only_the_steps_it_needs(self):
        self.script({"A": [{"write": {"a.txt": "A\n"}, "reply": "made a"}], "B": [{"write": {"b.txt": "B\n"}, "reply": "made b"}],
                     "C": [{"look": True}]})
        out = os.path.join(self.dir, "run")
        code, said, err = self.run_main(self.plan([{"id": "A"}, {"id": "B"}, {"id": "C", "needs": ["A"]}]), "--out", out,
                                        "--parallel", "1")  # A and B have both passed when C starts
        self.assertEqual(code, 0, said + err)
        c = self.prompts("C")[0]
        self.assertIn("Step A (done by mA)", c)
        self.assertNotIn("made b", c)
        self.assertNotIn("Step B", c)
        c_pass = [e for e in self.events(out) if e["kind"] == "node.pass" and e["node"] == "C"][0]
        with open(os.path.join(out, "replies", c_pass["reply"] + ".txt")) as handle:
            looked = handle.read()
        self.assertIn("refs/dag/A", looked)
        self.assertNotIn("refs/dag/B", looked)
        self.assertIn("files: a.txt base.txt", looked)

    def test_a_judge_changed_during_the_run_is_caught(self):
        judge = os.path.join(self.plans, "judge.py")
        self.script({"A": [{"append_to": judge}]})  # a member that reaches the judge (a command member can)
        out = os.path.join(self.dir, "run")
        code, _, _ = self.run_main(self.plan([{"id": "A"}]), "--out", out)
        self.assertEqual(code, 3)
        self.assertIn("changed during the run", self.summary(out)["nodes"]["A"]["detail"])

    def test_resume_runs_again_only_what_did_not_pass(self):
        self.script({"A": [{"write": {"a.txt": "A\n"}}], "B": [{"exit": 3}], "C": [{}]})
        path = self.plan([{"id": "A"}, {"id": "B", "needs": ["A"]}, {"id": "C", "needs": ["B"]}])
        out = os.path.join(self.dir, "run")
        self.assertEqual(self.run_main(path, "--out", out)[0], 3)
        code, _, err = self.run_main(path, "--out", out)
        self.assertEqual(code, 2)  # a folder that holds a run is not reused without --resume
        self.assertIn("already holds a run", err)
        self.script({"A": [{"write": {"a.txt": "A\n"}}], "B": [{}], "C": [{}]})  # the backend works again
        code, said, err = self.run_main(path, "--out", out, "--resume")
        self.assertEqual(code, 0, said + err)
        s = self.summary(out)
        self.assertEqual((s["passed"], s["dispatched_after_pass"], s["released_early"]), (3, 0, 0))
        self.assertEqual(len(self.prompts("A")), 1)  # passed before the resume: not run again
        self.assertEqual([e["attempt"] for e in self.events(out) if e["kind"] == "node.dispatch" and e["node"] == "B"], [1, 2])
        with open(os.path.join(self.plans, "tasks", "C.md"), "a") as handle:
            handle.write("changed\n")
        code, _, err = self.run_main(path, "--out", out, "--resume")
        self.assertEqual(code, 2)
        self.assertIn("the plan or a task file changed", err)

    def test_recheck_finds_a_verdict_that_does_not_hold_in_a_fresh_clone(self):
        self.script({"A": [{"write": {"a.txt": "A\n"}}], "B": [{"write": {"b.txt": "B\n"}}]})
        self.judge_rules({"A": {"files": {"a.txt": "A"}}, "B": {"env": "FLAKY"}})  # B's verdict hangs on the environment
        os.environ["FLAKY"] = "1"
        out = os.path.join(self.dir, "run")
        self.assertEqual(self.run_main(self.plan([{"id": "A"}, {"id": "B", "needs": ["A"]}]), "--out", out)[0], 0)
        del os.environ["FLAKY"]
        rows = {r["node"]: r for r in dag.recheck(out)}
        self.assertEqual((rows["A"]["now"], rows["B"]["now"]), ("valid", "invalid"))
        code, said, _ = self.run_main("--recheck", out)
        self.assertEqual(code, 1)
        self.assertIn("2 passed steps judged again, 1 did not hold", said)

    def test_a_read_step_keeps_no_changes(self):
        self.script({"R": [{"write": {"scratch.txt": "x\n"}, "reply": "looked"}], "W": [{"look": True}]})
        self.judge_rules({"W": {"absent": ["scratch.txt"]}})
        out = os.path.join(self.dir, "run")
        code, said, err = self.run_main(self.plan([{"id": "R", "access": "read"}, {"id": "W", "needs": ["R"]}]), "--out", out)
        self.assertEqual(code, 0, said + err)
        s = self.summary(out)
        self.assertEqual(s["nodes"]["R"]["sha"], s["base"])  # its output is where it started
        self.assertIn("A judge program checks your reply", self.prompts("R")[0])


class TextPlanTest(Base):
    def test_without_a_repository_the_reply_is_the_output(self):
        self.script({"A": [{"reply": "the answer is 42"}], "B": [{"reply": "B read it"}]})
        self.judge_rules({"A": {"reply": "42"}, "B": {"reply": "read"}})
        out = os.path.join(self.dir, "run")
