"""The live dashboard: the state model built from a fixture run, its HTTP endpoints (token, Server-Sent Events, files
inside the run only, no writes), the command, and the page's script (run data never parsed as markup)."""
import http.client
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import threading
import time
import unittest

from herdr_py import dashboard as D
from herdr_py.client import ClientError
from herdr_py.opencode import OpenCode
from herdr_py.policy import Policy
from herdr_py.server import Daemon

from fake_opencode import FakeOpenCode
from test_core import wait_for

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
FIXTURE = os.path.join(HERE, "fixtures", "dashboard_run")
WEB = os.path.join(ROOT, "herdr_py", "web", "dashboard")
sys.path.insert(0, os.path.join(ROOT, "examples", "slide_team"))
import imgcmp  # noqa: E402

TOKEN = "test-token-123"


def no_nan(text):
    """json.loads that refuses NaN/Infinity, as a browser's JSON.parse does."""
    def refuse(name):
        raise ValueError(f"{name} is not JSON")
    return json.loads(text, parse_constant=refuse)


def copy_fixture(test):
    tmp = tempfile.mkdtemp()
    test.addCleanup(shutil.rmtree, tmp, True)
    run = os.path.join(tmp, "run")
    shutil.copytree(FIXTURE, run)
    return tmp, run


def append(path, *items):
    with open(path, "a", encoding="utf-8") as handle:
        for item in items:
            handle.write(json.dumps(item) + "\n")


def points(rows):
    return {r["row"]: [(p["turn"], p["drawer"], p["kind"], p["valid"], p["accepted"]) for p in r["points"]] for r in rows}


class ModelTest(unittest.TestCase):
    def test_progress_names_the_art_director_while_it_reviews(self):
        folder = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, folder)
        os.makedirs(os.path.join(folder, "work"))
        lines = [(1000.0, "manager", "drawA", "message", "round 3: row 2 draft from the checklist"),
                 (1010.0, "drawA", "supervisor", "message", "22 components: r2.title"),
                 (1011.0, "picture", "team", "check", "row 2: match 0.834, 0 labels missing: first version kept"),
                 (1012.0, "render", "art", "check", "row 2: original and ours ready")]
        with open(os.path.join(folder, "work", "chat.jsonl"), "w") as handle:
            for t, who, to, kind, text in lines:
                handle.write(json.dumps({"t": t, "from": who, "to": to, "kind": kind, "text": text}) + "\n")
        run = D.RunFolder(folder)
        run.refresh()
        self.assertEqual(run.state()["run"]["progress"], {"round": 3, "row": 2, "kind": "review", "member": "art", "t": 1012.0})
        with open(os.path.join(folder, "work", "chat.jsonl"), "a") as handle:  # the notes arrive: back to the drawer of the round
            handle.write(json.dumps({"t": 1050.0, "from": "art", "to": "drawB", "kind": "message", "text": "DIFF: x"}) + "\n")
        run.refresh()
        self.assertEqual(run.state()["run"]["progress"]["member"], "drawA")

    def test_a_strict_run_shows_its_strict_score_and_what_decided(self):
        folder = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, folder)
        shutil.copytree(os.path.join(FIXTURE, "work"), os.path.join(folder, "work"))
        path = os.path.join(folder, "work", "summary.json")
        with open(path) as handle:
            summary = json.load(handle)
        summary["final"].update(strict=0.8728, score_mode="strict")
        with open(path, "w") as handle:
            json.dump(summary, handle)
        run = D.RunFolder(folder)
        run.refresh()
        self.assertEqual({k: run.state()["final"][k] for k in ("match", "strict", "score_mode")},
                         {"match": 0.6551, "strict": 0.8728, "score_mode": "strict"})
        with open(os.path.join(D.WEB_DIR, "dashboard.js"), encoding="utf-8") as handle:
            self.assertIn('"Strict score"', handle.read())  # the page has a tile for it

    def test_the_fixture_pictures_are_16_by_16_pngs(self):
        for name in ("01-row1-draft.png", "row1-original.png"):
            self.assertEqual(imgcmp.read_png(os.path.join(FIXTURE, "work", "renders", name))[:2], (16, 16))

    def test_state_of_the_fixture_run(self):
        run = D.RunFolder(FIXTURE)
        run.refresh()
        s = run.state()
        no_nan(json.dumps(s, allow_nan=False))
        self.assertEqual((s["run"]["work"], s["run"]["ended"], s["run"]["summary"], s["run"]["bad_lines"]), ("work", True, True, 0))
        self.assertEqual(s["run"]["progress"], {"round": 5, "row": 2, "kind": "revise", "member": "drawA", "t": 1070.0})
        self.assertEqual((s["chat_total"], s["chat"][0]["from"], s["chat"][-1]["kind"]), (33, "supervisor", "end"))
        members = {m["name"]: m for m in s["members"]}
        self.assertEqual(s["run"]["members_from"], "codex")
        self.assertEqual([(m["name"], m["state"], m["tokens"], m["turns"], m["sessions"]) for m in s["members"]],
                         [("drawA", "idle", 12000, 3, 2), ("drawB", "error", 8000, 2, 1), ("art", "aborted", 3000, 3, None)])
        self.assertEqual((members["drawA"]["words"], members["drawA"]["words_from"]), ("(no reply)", "stream"))
        self.assertEqual(members["drawB"]["words_from"], "chat")  # nothing streamed: its last line in the conversation
        self.assertTrue(members["drawB"]["words"].startswith("10 components: r2.longPrompt"))
        self.assertEqual(points(s["rows"]), {1: [(1, "drawA", "draft", True, True), (2, "drawB", "revise", True, False),
                                                 (3, "drawA", "revise", True, True)],
                                             2: [(4, "drawB", "draft", True, True), (5, "drawA", "revise", False, False)]})
        row1, row2 = s["rows"]
        self.assertEqual(([p["match"] for p in row1["points"]], row1["kept"], row1["best"]), ([0.6121, 0.5984, 0.7012], [0.6121, 0.6121, 0.7012], 0.7012))
        self.assertEqual((row2["points"][1]["match"], row2["kept"], row2["points"][0]["missing"]), (None, [0.5403, 0.5403], ["WAIT", "Chunk 3"]))
        self.assertEqual(s["final"], {"match": 0.6551, "psnr": 14.21, "missing": ["WAIT", "Chunk 3", "KV copy"]})
        self.assertEqual(s["lessons"], [{"text": "a revision that lowered the picture match was rejected: change only what the notes ask", "count": 1},
                                        {"text": "the reply had no ```json block with a JSON list", "count": 2}])

    def test_pictures_are_found_inside_the_run_even_when_it_was_moved(self):
        run = D.RunFolder(FIXTURE)
        run.refresh()
        first, second, third = run.state()["pictures"]
        # written as /elsewhere/runs/demo/work/renders/01-row1-draft.png: the folder moved, so renders/<name> is used
        self.assertEqual(first["ours"], {"path": "work/renders/01-row1-draft.png", "size": [16, 16]})
        self.assertEqual(first["original"], {"path": "work/renders/row1-original.png", "size": [16, 16]})
        self.assertEqual((first["round"], first["row"], first["drawer"], first["kind"], first["match"]), (1, 1, "drawA", "draft", 0.6121))
        self.assertEqual((second["ours"], second["name"], second["original"]["path"]), (None, "03-row1-rev.png", "work/renders/row1-original.png"))
        self.assertEqual((third["row"], third["ours"], third["original"]), (2, None, None))  # no crop of row 2 in the folder

    def test_live_rows_from_the_conversation_agree_with_the_summary(self):
        _, run_dir = copy_fixture(self)
        final = D.RunFolder(run_dir)
        final.refresh()
        from_summary = final.state()
        os.remove(os.path.join(run_dir, "work", "summary.json"))  # as during the run: summary.json comes at the end
        live = D.RunFolder(run_dir)
        live.refresh()
        from_chat = live.state()
        self.assertFalse(from_chat["run"]["summary"])
        self.assertEqual(points(from_chat["rows"]), points(from_summary["rows"]))
        self.assertEqual([p["pending"] for r in from_chat["rows"] for p in r["points"]], [False] * 5)  # the run has ended
        for a, b in zip(from_chat["rows"], from_summary["rows"]):
            for p, q in zip(a["points"], b["points"]):
                self.assertEqual(p["missing_count"], q["missing_count"], p)
                if q["match"] is None:
                    self.assertIsNone(p["match"])
                else:
                    self.assertAlmostEqual(p["match"], q["match"], delta=0.0005)  # the chat rounds to three decimals
            self.assertEqual([k is None for k in a["kept"]], [k is None for k in b["kept"]])
            for k, m in zip(a["kept"], b["kept"]):
                if m is not None:
                    self.assertAlmostEqual(k, m, delta=0.0005)
        self.assertEqual([(l["text"], l["count"]) for l in from_chat["lessons"]],
                         [("a revision that lowered the picture match was rejected", None),
                          ("the reply had no ```json block with a JSON list", None)])
        self.assertIsNone(from_chat["final"])

    def test_a_turn_without_a_picture_is_pending_until_the_next_turn_or_the_end(self):
        def line(frm, to, text, kind="message"):
            return {"t": 1.0, "from": frm, "to": to, "kind": kind, "text": text}
        chat = [line("manager", "drawA", "round 1: row 1 draft from the checklist"),
                line("check", "drawA", "2 errors: r1.a: missing \"y\"", "check")]
        (row,) = D.rows_from_chat(chat, ended=False)
        self.assertEqual([(p["pending"], p["valid"]) for p in row["points"]], [(True, False)])
        (row,) = D.rows_from_chat(chat, ended=True)  # the run ended without a picture: that turn could not be drawn
        self.assertEqual([(p["pending"], p["valid"]) for p in row["points"]], [(False, False)])
        chat.append(line("manager", "drawB", "round 2: row 1 revise drawA's version: 0 art notes, 1 program notes"))
        (row,) = D.rows_from_chat(chat, ended=False)
        self.assertEqual([(p["pending"], p["valid"]) for p in row["points"]], [(False, False), (True, False)])
        chat.append(line("picture", "team", "row 1: match 0.400, 0 labels missing: first version kept", "check"))
        (row,) = D.rows_from_chat(chat, ended=True)
        self.assertEqual([(p["pending"], p["valid"], p["accepted"], p["match"]) for p in row["points"]],
                         [(False, False, False, None), (False, True, True, 0.4)])
        self.assertEqual(row["kept"], [None, 0.4])

    def test_a_rerun_in_the_same_folder_leaves_the_old_summary_and_pictures_out(self):
        _, run_dir = copy_fixture(self)
        append(os.path.join(run_dir, "work", "chat.jsonl"),
               {"t": 2000.0, "from": "supervisor", "to": "team", "kind": "control", "text": "task: rebuild the infographic again"},
               {"t": 2001.0, "from": "manager", "to": "drawA", "kind": "message", "text": "round 1: row 1 draft from the checklist"})
        run = D.RunFolder(run_dir)
        run.refresh()
        s = run.state()
        self.assertEqual((s["run"]["ended"], s["run"]["summary"], s["run"]["earlier_lines"], s["final"]), (False, False, 33, None))
        self.assertEqual(points(s["rows"]), {1: [(1, "drawA", "draft", False, False)]})
        self.assertTrue(s["rows"][0]["points"][0]["pending"])
        self.assertEqual(s["pictures"], [])  # every picture in the manifest is older than the new run
        self.assertEqual(s["chat_total"], 35)  # the conversation itself keeps both runs

    def test_lines_wait_for_the_newline_skip_bad_lines_and_start_over_when_replaced(self):
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp)
        path = os.path.join(tmp, "x.jsonl")
        with open(path, "w") as handle:
            handle.write('{"a": 1}\n{"b": ')
        lines = D.Lines(tmp, ["x.jsonl"])
        self.assertTrue(lines.read())
        self.assertEqual(lines.items, [{"a": 1}])
        self.assertFalse(lines.read())
        with open(path, "a") as handle:
            handle.write('2}\nnot json\n[1]\n')
        self.assertTrue(lines.read())
        self.assertEqual((lines.items, lines.bad, lines.resets), ([{"a": 1}, {"b": 2}], 2, 0))
        with open(path + ".new", "w") as handle:
            handle.write('{"c": 3}\n')
        os.replace(path + ".new", path)
        self.assertTrue(lines.read())
        self.assertEqual((lines.items, lines.bad, lines.resets), ([{"c": 3}], 0, 1))
        os.remove(path)
        self.assertTrue(lines.read())
        self.assertEqual((lines.items, lines.resets), ([], 2))

    def test_a_half_written_json_file_keeps_the_last_good_value(self):
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp)
        path = os.path.join(tmp, "summary.json")
        with open(path, "w") as handle:
            handle.write('{"final": {"match": 0.5}}')
        summary = D.JsonFile(tmp, ["summary.json"])
        self.assertTrue(summary.read())
        with open(path, "w") as handle:
            handle.write('{"final": {"ma')  # json.dump is still writing it
        self.assertFalse(summary.read())
        self.assertEqual(summary.value, {"final": {"match": 0.5}})
        with open(path, "w") as handle:
            handle.write('{"final": {"match": 0.75}}')
        self.assertTrue(summary.read())
        self.assertEqual(summary.value, {"final": {"match": 0.75}})

    def test_an_infinite_psnr_reaches_the_page_as_text(self):
        _, run_dir = copy_fixture(self)
        path = os.path.join(run_dir, "work", "summary.json")
        with open(path) as handle:
            summary = json.load(handle)
        summary["final"]["psnr"] = float("inf")  # identical pictures; json.dump writes Infinity, which JSON.parse rejects
        with open(path, "w") as handle:
            json.dump(summary, handle)
        run = D.RunFolder(run_dir)
        run.refresh()
        state = run.state()
        self.assertEqual(state["final"]["psnr"], "inf")
        no_nan(json.dumps(state, allow_nan=False))


class FakeClient:
    def __init__(self, agents):
        self.agents, self.error = agents, None

    def call(self, method, **params):
        if self.error:
            raise self.error
        return {"agents": self.agents}


class DaemonMembersTest(unittest.TestCase):
    def test_sessions_pending_requests_and_counters_from_agent_views(self):
        views = [{"name": "a", "state": "blocked", "tokens": 5, "turns": 2, "since": 100.5, "past_sessions": ["s1", "s2"],
                  "pending": [{"id": "per_1", "description": "bash: curl x"}], "stream": {"kind": "reasoning", "text": "hmm"},
                  "compactions": 2, "truncated_turns": 0, "counters": {"reasoning_only_turns": 1, "retries": 4, "flag": True}},
                 {"name": "b", "state": "working", "tokens": 1, "turns": 9, "past_sessions": ["s"] * 5},
                 {"name": "c", "state": "idle", "tokens": 0, "turns": 1, "sessions": 9, "past_sessions": []}]
        run = D.RunFolder(FIXTURE, socket_path=os.path.join(FIXTURE, "no.sock"))
        run.client = FakeClient(views)
        run.refresh()
        s = run.state()
        a, b, c = s["members"]
        self.assertEqual(s["run"]["members_from"], "daemon")
        self.assertEqual((a["state"], a["sessions"], a["sessions_more"], a["since"], a["pending"], a["words"], a["words_kind"]),
                         ("blocked", 3, False, 100.5, ["bash: curl x"], "hmm", "reasoning"))
        self.assertEqual([(x["label"], x["value"]) for x in a["counters"]],
                         [("compactions", 2), ("truncated turns", 0), ("reasoning-only turns", 1), ("retries", 4)])
        self.assertEqual((b["sessions"], b["sessions_more"], b["counters"]), (6, True, []))  # the view lists 5 earlier sessions at most
        self.assertEqual((c["sessions"], c["sessions_more"]), (9, False))

    def test_a_daemon_that_stops_answering_keeps_the_last_members(self):
        run = D.RunFolder(FIXTURE, socket_path=os.path.join(FIXTURE, "no.sock"), member_poll_s=0)
        run.client = FakeClient([{"name": "a", "state": "working"}])
        run.refresh()
        run.client.error = ClientError("server_not_running", "no herdr-py daemon")
        run.refresh()
        s = run.state()
        self.assertEqual([m["name"] for m in s["members"]], ["a"])
        self.assertIn("server_not_running", s["run"]["members_error"])

    def test_members_from_a_running_daemon(self):
        fake = FakeOpenCode().start()
        self.addCleanup(fake.stop)
        tmp = tempfile.mkdtemp(dir="/tmp")  # AF_UNIX paths are limited to ~104 bytes on macOS
        self.addCleanup(shutil.rmtree, tmp, True)
        daemon = Daemon(OpenCode(fake.url), Policy([], default="ask"), tmp)
        daemon.start()
        self.addCleanup(daemon.stop)
        wait_for(lambda: fake.stream_count() == 1, what="event stream")
        daemon.call("agent.start", {"name": "w", "prompt": "go"})
        run = D.RunFolder(FIXTURE, socket_path=daemon.socket_path)
        run.refresh()
        (w,) = run.state()["members"]
        self.assertEqual((w["name"], w["state"], w["turns"], w["sessions"]), ("w", "starting", 1, 1))


class ServerTest(unittest.TestCase):
    def setUp(self):
        self.tmp, self.run_dir = copy_fixture(self)
        renders = os.path.join(self.run_dir, "work", "renders")
        with open(os.path.join(self.tmp, "secret.png"), "wb") as handle:  # outside the run folder
            handle.write(b"\x89PNG\r\n\x1a\nSECRET-OUTSIDE")
        os.makedirs(os.path.join(self.run_dir, "state"))
        with open(os.path.join(self.run_dir, "state", "token"), "w") as handle:  # run_demo.py keeps the daemon state here
            handle.write("SECRET-TOKEN")
        with open(os.path.join(renders, ".hidden.png"), "wb") as handle:
            handle.write(b"SECRET-HIDDEN")
        os.symlink(os.path.join(self.tmp, "secret.png"), os.path.join(renders, "link.png"))
        os.symlink("01-row1-draft.png", os.path.join(renders, "inside.png"))
        os.symlink(self.tmp, os.path.join(self.run_dir, "work", "up"))
        os.mkfifo(os.path.join(renders, "pipe.png"))
        self.dash = D.Dashboard(self.run_dir, port=0, token=TOKEN, poll_s=0.05, keepalive_s=0.3).start()
        self.addCleanup(self.dash.stop)
        self.port = self.dash.web.server_address[1]

    def get(self, path, token=True, method="GET", headers=None):
        conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=5)
        try:
            sep = "&" if "?" in path else "?"
            conn.request(method, path + (f"{sep}token={TOKEN}" if token else ""), headers=headers or {})
            resp = conn.getresponse()
            return resp.status, dict(resp.getheaders()), resp.read()
        finally:
            conn.close()

    def test_the_page_needs_no_token_and_is_sent_with_a_strict_policy(self):
        status, headers, body = self.get("/", token=False)
        self.assertEqual(status, 200)
        self.assertIn(b"dashboard.js", body)
        self.assertIn("default-src 'none'", headers["Content-Security-Policy"])
        self.assertIn("script-src 'self'", headers["Content-Security-Policy"])
        self.assertEqual(headers["X-Content-Type-Options"], "nosniff")
        for path in ("/dashboard.js", "/dashboard.css", "/icon.svg"):
            self.assertEqual(self.get(path, token=False)[0], 200, path)

    def test_the_api_needs_the_token(self):
        self.assertEqual(self.get("/api/state", token=False)[0], 401)
        self.assertEqual(self.get("/api/state?token=wrong", token=False)[0], 401)
        self.assertEqual(self.get("/files/work/renders/01-row1-draft.png", token=False)[0], 401)
        self.assertEqual(self.get("/api/state", token=False, headers={"Authorization": "Bearer " + TOKEN})[0], 200)

    def test_api_state_is_the_runs_state_as_json(self):
        status, headers, body = self.get("/api/state")
        self.assertEqual(status, 200)
        self.assertTrue(headers["Content-Type"].startswith("application/json"))
        state = no_nan(body.decode())
        self.assertEqual((state["chat_total"], len(state["chat"]), state["run"]["name"]), (33, 33, "run"))
        self.assertEqual([r["row"] for r in state["rows"]], [1, 2])
        self.assertEqual(state["pictures"][0]["ours"]["path"], "work/renders/01-row1-draft.png")

    def read_event(self, resp, deadline=5.0):
        """The next `data:` event of a Server-Sent Events stream (comments and retry lines are skipped)."""
        data, end = [], time.time() + deadline
        while time.time() < end:
            line = resp.readline().decode()
            if not line:
                raise AssertionError("the event stream ended")
            line = line.rstrip("\n")
            if line.startswith("data: "):
                data.append(line[6:])
            elif line == "" and data:
                return no_nan("\n".join(data))
        raise AssertionError("no event in time")

    def test_events_start_with_a_snapshot_and_then_send_new_lines(self):
        conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=5)
        self.addCleanup(conn.close)
        conn.request("GET", "/api/events?token=" + TOKEN)
        resp = conn.getresponse()
        self.assertEqual(resp.status, 200)
        self.assertTrue(resp.getheader("Content-Type").startswith("text/event-stream"))
        first = self.read_event(resp)
        self.assertEqual((first["type"], first["chat_from"], first["chat_total"], len(first["chat"])), ("snapshot", 0, 33, 33))
        append(os.path.join(self.run_dir, "work", "chat.jsonl"),
               {"t": 1100.0, "from": "operator", "to": "team", "kind": "control", "text": "a new line"})
        update = self.read_event(resp)
        self.assertEqual((update["type"], update["chat_from"], update["chat_total"]), ("update", 33, 34))
        self.assertEqual([c["text"] for c in update["chat"]], ["a new line"])
        with open(os.path.join(self.run_dir, "work", "chat.jsonl"), "w") as handle:  # the conversation starts over
            handle.write(json.dumps({"t": 1.0, "from": "supervisor", "to": "team", "kind": "control", "text": "task: again"}) + "\n")
        again = self.read_event(resp)
        self.assertEqual((again["type"], again["chat_from"], again["chat_total"]), ("snapshot", 0, 1))

    def test_files_serves_images_inside_the_run(self):
        status, headers, body = self.get("/files/work/renders/01-row1-draft.png")
        self.assertEqual((status, headers["Content-Type"]), (200, "image/png"))
        with open(os.path.join(self.run_dir, "work", "renders", "01-row1-draft.png"), "rb") as handle:
            self.assertEqual(body, handle.read())
        status, _, body = self.get("/files/work/renders/01-row1-draft.png", headers={"If-None-Match": headers["ETag"]})
        self.assertEqual((status, body), (304, b""))

    def test_files_refuses_traversal_symlinks_hidden_files_fifos_and_non_images(self):
        refused = ["/files/../secret.png", "/files/work/../../secret.png", "/files/%2e%2e/secret.png",
                   "/files/work/renders/..%2f..%2f..%2fsecret.png", "/files//etc/passwd", "/files/" + self.tmp + "/secret.png",
                   "/files/work/up/secret.png",              # a symlinked folder that leads out
                   "/files/work/renders/link.png",           # a symlink out of the run folder
                   "/files/work/renders/inside.png",         # any symlink, even one that stays inside
                   "/files/work/renders/.hidden.png", "/files/state/token", "/files/work/chat.jsonl",
                   "/files/work/renders/pipe.png",           # a FIFO must not hang the server
                   "/files/work/renders/missing.png", "/files/work/renders", "/files/"]
        for path in refused:
            status, _, body = self.get(path)
            self.assertEqual(status, 404, path)
            self.assertNotIn(b"SECRET", body, path)

    def test_there_are_no_write_endpoints(self):
        before = sorted(os.path.join(d, f) for d, _, files in os.walk(self.run_dir) for f in files)
        for method in ("POST", "PUT", "PATCH", "DELETE"):
            for path in ("/api/state", "/files/work/renders/01-row1-draft.png", "/"):
                self.assertEqual(self.get(path, method=method)[0], 405, (method, path))
        after = sorted(os.path.join(d, f) for d, _, files in os.walk(self.run_dir) for f in files)
        self.assertEqual(before, after)

    def test_it_listens_on_loopback_by_default(self):
        a = D.parse_args(["RUN"])
        self.assertEqual((a.host, a.port, a.socket), ("127.0.0.1", 8770, None))
        dash = D.Dashboard(self.run_dir, port=0)
        self.addCleanup(dash.web.server_close)
        self.assertEqual(dash.web.server_address[0], "127.0.0.1")


class CommandTest(unittest.TestCase):
    def test_the_command_prints_a_link_with_the_token_and_serves_it(self):
        env = dict(os.environ, PYTHONPATH=ROOT, PYTHONDONTWRITEBYTECODE="1")
        proc = subprocess.Popen([sys.executable, "-m", "herdr_py.dashboard", FIXTURE, "--port", "0"], stdout=subprocess.PIPE,
                                stderr=subprocess.DEVNULL, universal_newlines=True, env=env)

        def stop():
            proc.terminate()
            proc.wait(10)
            proc.stdout.close()
        self.addCleanup(stop)
        lines = []
        reader = threading.Thread(target=lambda: lines.extend(iter(proc.stdout.readline, "")), daemon=True)
        reader.start()
        wait_for(lambda: any(l.startswith("open: ") for l in lines), timeout=20, what="the printed link")
        link = [l for l in lines if l.startswith("open: ")][0].split()[1]
        found = re.match(r"http://127\.0\.0\.1:(\d+)/#token=([\w-]+)$", link)
        self.assertTrue(found, link)
        conn = http.client.HTTPConnection("127.0.0.1", int(found.group(1)), timeout=5)
        conn.request("GET", "/api/state?token=" + found.group(2))
        resp = conn.getresponse()
        self.assertEqual((resp.status, no_nan(resp.read().decode())["chat_total"]), (200, 33))
        conn.close()

    def test_a_missing_folder_is_an_error(self):
        env = dict(os.environ, PYTHONPATH=ROOT, PYTHONDONTWRITEBYTECODE="1")
        p = subprocess.run([sys.executable, "-m", "herdr_py.dashboard", os.path.join(FIXTURE, "missing")], stdout=subprocess.PIPE,
                           stderr=subprocess.PIPE, universal_newlines=True, env=env, timeout=30)
        self.assertEqual(p.returncode, 2)
        self.assertIn("is not a folder", p.stderr)


class PageTest(unittest.TestCase):
    def read(self, name):
        with open(os.path.join(WEB, name), encoding="utf-8") as handle:
            return handle.read()

    def test_the_script_never_turns_data_into_markup(self):
        """Run data is model output: it may only enter the page as text (textContent, createElement, setAttribute)."""
        script = re.sub(r"//[^\n]*", "", self.read("dashboard.js"))  # comments may name what is forbidden
        for pattern in (r"\binnerHTML\b", r"\bouterHTML\b", r"insertAdjacentHTML", r"document\.write", r"DOMParser",
                        r"createContextualFragment", r"\beval\s*\(", r"\bnew\s+Function\b", r"setAttribute\(\s*[\"']on",
                        r"\bsrcdoc\b", r"javascript:", r"setAttribute\(\s*[\"']style"):
            self.assertIsNone(re.search(pattern, script), pattern)
        self.assertIn("textContent", script)

    def test_the_page_loads_nothing_from_elsewhere(self):
        page, css, script = self.read("index.html"), self.read("dashboard.css"), self.read("dashboard.js")
        self.assertIsNone(re.search(r"https?://", page))
        self.assertIsNone(re.search(r"<script(?![^>]*\bsrc=)", page))        # no inline script
        self.assertIsNone(re.search(r"\son[a-z]+\s*=", page))                # no inline event handlers
        self.assertIsNone(re.search(r"style\s*=", page))                     # no inline styles (the policy forbids them)
        self.assertIsNone(re.search(r"url\(|@import", css))
        self.assertEqual(re.findall(r"https?://[^\"'\s]+", script), ["http://www.w3.org/2000/svg"])  # the SVG namespace only


if __name__ == "__main__":
    unittest.main()


class SavedPageTest(unittest.TestCase):
    """--html: the page and the run as one file that opens from disk (no server, no token, no updates)."""

    def save(self, run):
        out = os.path.join(os.path.dirname(run), "saved.html")
        result = D.save_html(run, out)
        with open(out, encoding="utf-8") as handle:
            return result, handle.read()

    @staticmethod
    def embedded(page):
        found = re.search(r'<script type="application/json" id="run-data">(.*?)</script>', page, re.S)
        return json.loads(found.group(1))

    def test_everything_the_page_needs_is_inside(self):
        _, run = copy_fixture(self)
        result, page = self.save(run)
        self.assertNotIn('href="dashboard.css"', page)
        self.assertNotIn('src="dashboard.js"', page)
        self.assertIn("function fileUrl", page)  # the script is inline
        data = self.embedded(page)
        self.assertEqual(data["state"]["chat_total"], 33)
        wanted = D.saved_pictures(data["state"], set())
        self.assertTrue(wanted)
        self.assertEqual(set(data["files"]), wanted)
        self.assertTrue(all(v.startswith("data:image/png;base64,") for v in data["files"].values()))
        self.assertEqual(result["pictures"], len(wanted))

    def test_model_text_cannot_end_the_data_or_reach_the_token(self):
        _, run = copy_fixture(self)
        os.makedirs(os.path.join(run, "state"))
        with open(os.path.join(run, "state", "token"), "w") as handle:
            handle.write("SECRET-TOKEN-123")
        append(os.path.join(run, "work", "chat.jsonl"),
               {"t": 1100.0, "from": "drawA", "to": "supervisor", "kind": "message", "text": "</script><script>alert(1)</script> <!-- & >"})
        _, page = self.save(run)
        self.assertEqual(page.count("</script>"), 2)  # the data's and the script's own, nothing from the chat
        self.assertNotIn("<!--", page.split('id="run-data">', 1)[1].split("</script>", 1)[0])
        self.assertNotIn("SECRET-TOKEN-123", page)
        last = self.embedded(page)["state"]["chat"][-1]["text"]
        self.assertEqual(last, "</script><script>alert(1)</script> <!-- & >")  # escaped in the file, intact once parsed

    def test_the_command_saves_and_exits(self):
        tmp, run = copy_fixture(self)
        out = os.path.join(tmp, "run.html")
        env = dict(os.environ, PYTHONPATH=ROOT, PYTHONDONTWRITEBYTECODE="1")
        p = subprocess.run([sys.executable, "-m", "herdr_py.dashboard", run, "--html", out], stdout=subprocess.PIPE,
                           stderr=subprocess.PIPE, universal_newlines=True, env=env, timeout=60)
        self.assertEqual(p.returncode, 0, p.stderr)
        self.assertIn("saved: " + out, p.stdout)
        self.assertTrue(os.path.getsize(out) > 0)
        bad = subprocess.run([sys.executable, "-m", "herdr_py.dashboard", os.path.join(tmp, "missing"), "--html", out],
                             stdout=subprocess.PIPE, stderr=subprocess.PIPE, universal_newlines=True, env=env, timeout=60)
        self.assertEqual(bad.returncode, 2)

    def test_the_script_reads_a_saved_page_without_the_server(self):
        with open(os.path.join(D.WEB_DIR, "dashboard.js"), encoding="utf-8") as handle:
            script = handle.read()
        self.assertIn('document.getElementById("run-data")', script)
        self.assertIn("if (app.files) return app.files[path]", script)
        self.assertIn('setConn("saved"', script)
HERDR_PY_EOF
cat > tests/test_diagnose.py <<'HERDR_PY_EOF'
"""herdr_py.diagnose: the flight recorder and its rules, against small hand-written run folders (tests/fixtures/diagnose).

Each pattern folder is an excerpt in the formats the daemon (state/events.jsonl), codex_agents.py (work/codex/events.jsonl)
and the slide teams (work/chat.jsonl) write. Each must give exactly its finding, pointing at the line that proves it;
the clean runs must give none.
"""
import contextlib
import io
import json
import os
import shutil
import subprocess
import sys
import tempfile
import unittest

from herdr_py import diagnose

FIXTURES = os.path.join(os.path.dirname(os.path.abspath(__file__)), "fixtures", "diagnose")

# fixture -> (code, member, row, turns, text on the first line the finding points at)
EXPECTED = {
    "turn_error": ("turn_error", "art", None, [1], '"exit": 1'),
    "turn_error_opencode": ("turn_error", "drawA", None, [1], '"name": "APIError"'),
    "compacted_reply": ("compacted_reply", "drawA", None, [1], '"type": "session.compacted"'),
    "output_limit": ("output_limit", "art", None, [1], '"reason": "length"'),
    "reasoning_only": ("reasoning_only", "drawA", None, [1], '"reason": "stop"'),
    "time_limit": ("time_limit", "drawB", None, [1], '"reason": "turn time limit"'),
    "time_limit_codex": ("time_limit", "drawA", None, [1], '"exit": -9'),
    "wrong_format": ("wrong_format", "drawA", None, [1], "Reply with ONLY one ```json block"),
    "wrong_format_codex": ("wrong_format", "drawB", None, [1], "1 errors: the reply had no ```json block"),  # no prompt in Codex logs
    "no_change": ("no_change", "drawA", None, [1], "rewrite the WHOLE make_deck.py with the write tool"),
    "claimed_success": ("claimed_success", "drawB", None, [1], "All required labels added"),
    "repeated_tool_error": ("repeated_tool_error", "drawA", None, [1, 1, 1], "Could not find oldString"),
    "repeated_rejection": ("repeated_rejection", "drawA", None, [1, 1, 1], '"reply": "reject"'),
    "revisions_rejected": ("revisions_rejected", "drawB", None, [1, 3], "rejected, kept the better version"),
    "revisions_rejected_row": ("revisions_rejected", None, 1, [None, None], "rejected, kept the better version"),
}


def fixture(name):
    return os.path.join(FIXTURES, name)


def line_of(run, ref):
    path, _, number = ref.rpartition(":")
    with open(os.path.join(run, path), encoding="utf-8") as handle:
        return handle.read().splitlines()[int(number) - 1]


def copy_fixture(test, name):
    tmp = tempfile.mkdtemp()
    test.addCleanup(shutil.rmtree, tmp)
    run = os.path.join(tmp, name)
    shutil.copytree(fixture(name), run)
    return run


def turn_of(run, member, number):
    return next(t for t in diagnose.load(run)["turns"] if t.member == member and t.number == number)


def rewrite(run, rel, old=None, new="", drop=None):
    """Edit a copied fixture: replace text, or drop the lines that contain `drop`. Returns how many lines were dropped."""
    path = os.path.join(run, rel)
    with open(path, encoding="utf-8") as handle:
        lines = handle.read().splitlines()
    kept = [l.replace(old, new) if old else l for l in lines if not (drop and drop in l)]
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(kept) + "\n")
    return len(lines) - len(kept)


class FindingsTest(unittest.TestCase):
    def test_each_pattern_gives_exactly_its_finding(self):
        for name, (code, member, row, turns, _) in EXPECTED.items():
            with self.subTest(name):
                found = diagnose.findings(fixture(name))
                self.assertEqual([(f["code"], f["member"], f["row"], f["turns"]) for f in found], [(code, member, row, turns)])
                self.assertTrue(found[0]["suggestion"])

    def test_clean_runs_give_none(self):
        for name in ("clean", "clean_codex"):
            with self.subTest(name):
                self.assertEqual(diagnose.findings(fixture(name)), [])

    def test_evidence_points_at_the_record_that_proves_it(self):
        for name, (_, _, _, _, proof) in EXPECTED.items():
            with self.subTest(name):
                run = fixture(name)
                evidence = diagnose.findings(run)[0]["evidence"]
                self.assertIn(proof, line_of(run, evidence[0]["refs"][0]))
                for item in evidence:
                    self.assertTrue(item["detail"])
                    for ref in item["refs"]:
                        self.assertTrue(line_of(run, ref).startswith("{"), ref)

    def test_a_claim_and_the_check_that_disproves_it_are_both_cited(self):
        evidence = diagnose.findings(fixture("claimed_success"))[0]["evidence"][0]
        self.assertEqual(evidence["refs"], ["state/events.jsonl:11", "work/chat.jsonl:5"])
        self.assertIn("9 missing", evidence["detail"])

    def test_one_outcome_per_turn_the_most_specific_first(self):
        # the compacted turn also hit the time limit and had no JSON block: those rules match it too, but only the
        # compaction (the cause) is reported, so the suggestion is the one that helps
        turn = turn_of(fixture("compacted_reply"), "drawA", 1)
        self.assertTrue(diagnose.time_limit(turn))
        self.assertTrue(diagnose.wrong_format(turn))
        self.assertEqual([f["code"] for f in diagnose.findings(fixture("compacted_reply"))], ["compacted_reply"])
        turn = turn_of(fixture("output_limit"), "art", 1)  # the program also wrote "(no DIFF lines)"
        self.assertTrue(diagnose.wrong_format(turn))
        self.assertIsNone(diagnose.reasoning_only(turn))  # stopped by the limit, not by itself

    def test_findings_are_json_ready(self):
        found = diagnose.findings(fixture("repeated_rejection"))
        self.assertEqual(json.loads(json.dumps(found))[0]["code"], "repeated_rejection")
        self.assertEqual(set(found[0]), {"code", "member", "row", "title", "count", "turns", "first", "evidence", "suggestion"})
        self.assertIn("python3 ... && python3 ...", found[0]["title"])
        self.assertIn("one command per call", found[0]["suggestion"])

    def test_known_tool_errors_get_their_own_suggestion(self):
        found = diagnose.findings(fixture("repeated_tool_error"))[0]
        self.assertTrue(found["suggestion"].startswith("Rewrite whole files with the write tool"))

    def test_the_member_with_accepted_revisions_is_named(self):
        self.assertIn("give the revisions to drawA", diagnose.findings(fixture("revisions_rejected"))[0]["suggestion"])
        self.assertIn("2 of these 2 revisions came with no art notes", diagnose.findings(fixture("revisions_rejected_row"))[0]["suggestion"])

    def test_one_below_each_threshold_is_not_a_pattern(self):
        cases = (("repeated_tool_error", "state/events.jsonl", "call_e3"),            # 2 of the same tool error
                 ("repeated_rejection", "state/events.jsonl", '"hub": "decision", "agent": "drawA", "request": "per_3"'),  # 2 rejections
                 ("revisions_rejected", "work/chat.jsonl", "0.853 -> 0.821"),         # 1 rejected revision of drawB
                 ("revisions_rejected_row", "work/chat.jsonl", "0.763 -> 0.711"))     # 1 rejected revision of row 1
        for name, rel, line in cases:
            with self.subTest(name):
                run = copy_fixture(self, name)
                self.assertEqual(rewrite(run, rel, drop=line), 1)
                self.assertEqual(diagnose.findings(run), [])

    def test_both_records_of_a_time_limit_are_cited(self):
        evidence = diagnose.findings(fixture("time_limit"))[0]["evidence"][0]
        self.assertEqual(evidence["refs"], ["state/events.jsonl:9", "work/chat.jsonl:2"])

    def test_a_compaction_summary_is_a_wrong_reply_even_when_no_format_was_asked(self):
        run = copy_fixture(self, "compacted_reply")
        rewrite(run, "state/events.jsonl", "into a JSON list of components", "into a short description")
        rewrite(run, "state/events.jsonl", "Reply with ONLY one ```json block that contains the list.", "Describe the row in a few lines.")
        self.assertEqual(rewrite(run, "work/chat.jsonl", drop="no ```json block"), 3)
        self.assertEqual(diagnose.asked_format(turn_of(run, "drawA", 1)), (None, None))
        found = diagnose.findings(run)
        self.assertEqual([f["code"] for f in found], ["compacted_reply"])
        self.assertIn("the reply after it is the compaction summary", found[0]["evidence"][0]["detail"])

    def test_a_check_written_as_the_next_turn_starts_belongs_to_the_turn_it_checks(self):
        # chat keeps 2 decimals and the daemon 3: in a real run the picture check and the next prompt had the same time
        run = copy_fixture(self, "clean")
        rewrite(run, "work/chat.jsonl", '"t": 1791400038.1,', '"t": 1791400038.6,')  # the art director's prompt time
        self.assertEqual([m["from"] for m in turn_of(run, "drawA", 1).checks], ["check", "picture"])
        self.assertEqual(turn_of(run, "art", 1).checks, [])

    def test_change_requests_in_the_example_prompts(self):
        asks = ("Edit make_deck.py, then run python3 make_deck.py and python3 -m open_slide_py validate deck.json",
                "Rewrite the WHOLE make_deck.py with the write tool (keep what is already there)",
                "How: write make_deck.py (Python standard library only) that builds the deck as Python dicts",
                "Fix the problems above, run python3 check.py yourself, update NOTES.md, and stop when the check passes.")
        others = ("Do not write code, do not use tools, do not skip lines.",
                  "Fix exactly these problems, keep the rest, and reply with ONLY one ```json block that contains the whole list.",
                  'Keep a file NOTES.md with two short sections, "Done" and "Next", and update it as you go',
                  "You are the verifier. You must not edit files.")
        for text in asks:
            self.assertTrue(diagnose.CHANGE_ASKED.search(text), text)
        for text in others:
            self.assertIsNone(diagnose.CHANGE_ASKED.search(text), text)


class ClaimsTest(unittest.TestCase):
    def turn(self, reply, *checks):
        turn = diagnose.Turn("drawA", "opencode", 1.0, "state/events.jsonl:2")
        turn.reply, turn.reply_ref, turn.end = reply, "state/events.jsonl:9", 2.0
        turn.checks = [{"t": 3.0, "from": sender, "text": text, "ok": ok, "ref": f"work/chat.jsonl:{i + 1}"}
                       for i, (sender, text, ok) in enumerate(checks)]
        return turn

    def test_a_claim_is_judged_only_by_the_checks_that_can_disprove_it(self):
        lint_ok, missing = ("lint", "OK", True), ("content", "21 missing: Prefill, Decode", False)
        self.assertIsNone(diagnose.claimed_success(self.turn("The validation passed with no errors.", lint_ok, missing)))
        self.assertTrue(diagnose.claimed_success(self.turn("All required labels added.", lint_ok, missing)))
        self.assertTrue(diagnose.claimed_success(self.turn("Done.", lint_ok, missing)))
        self.assertIsNone(diagnose.claimed_success(self.turn("Done.", lint_ok)))

    def test_negations_code_blocks_and_headings_are_not_claims(self):
        self.assertEqual(diagnose.claims_of("Not done yet: the labels are still missing."), [])
        self.assertEqual(diagnose.claims_of("```\nCompleted: base layout\n```"), [])
        self.assertEqual(diagnose.claims_of("## Work State\n### Completed\n- Row 1"), [])
        self.assertEqual(diagnose.claims_of("I placed the title.\nValidation passed."),
                         [("Validation passed.", ("check", "build", "lint"))])


class HelpersTest(unittest.TestCase):
    def test_shape_keeps_programs_and_operators(self):
        self.assertEqual(diagnose.shape("python3 make_deck.py && python3 -m open_slide_py validate deck.json"), "python3 ... && python3 ...")
        self.assertEqual(diagnose.shape("/bin/sh -c 'ls'"), "sh ...")
        self.assertEqual(diagnose.shape("ls"), "ls")
        self.assertEqual(diagnose.shape("cat a | grep b; ls"), "cat ... | grep ... ; ls")

    def test_signature_blanks_what_varies(self):
        self.assertEqual(diagnose.signature("No file 'a.py' at /work/x/a.py line 12\nmore"), "No file '_' at PATH line N")

    def test_json_detection_matches_what_the_layout_team_parses(self):
        self.assertTrue(diagnose.has_json('```json\n[{"id": "r1.a"}]\n```'))
        self.assertTrue(diagnose.has_json('Here: [{"id": "r1.a"}] done'))
        self.assertFalse(diagnose.has_json("I placed the title."))
        self.assertFalse(diagnose.has_json('```json\n[{"id": }]\n```'))


class RecorderTest(unittest.TestCase):
    def test_an_opencode_turn(self):
        r = turn_of(fixture("repeated_tool_error"), "drawA", 1).record()
        self.assertTrue(r["prompt_head"].startswith("You are drawA, a slide drawer. drawB made the current version"))
        self.assertEqual(len(r["prompt_head"]), 303)  # the first 300 characters and "..."
        self.assertEqual(r["reply"], "I rewrote make_deck.py with the write tool; the Decode box now sits 40 px further left.")
        self.assertEqual([(c["tool"], c["status"]) for c in r["tools"]], [("edit", "error")] * 3 + [("write", "completed")])
        self.assertEqual(r["tools"][0]["input"], "/work/make_deck.py (oldString 22 chars)")
        self.assertEqual(r["tools"][3]["output"], "Wrote file successfully.")
        self.assertEqual(r["tokens"], {"in": 6725 + 7290 + 7520 + 7700 + 7990, "out": 472 + 190 + 181 + 250 + 50})
        self.assertEqual((r["finish"], r["end_state"], r["duration_s"]), ("stop", "idle", 160.7))
        self.assertEqual([(c["from"], c["ok"]) for c in r["checks"]], [("build", True), ("lint", True), ("content", True)])

    def test_the_prompt_part_is_not_the_reply_and_attachments_are_listed(self):
        run = fixture("clean")
        draw = turn_of(run, "drawA", 1).record()
        self.assertTrue(draw["reply"].startswith("```json"))
        self.assertEqual(draw["reasoning_chars"], len("Two checklist lines: one text component and one tokens component."))
        self.assertEqual(turn_of(run, "art", 1).record()["files"], ["row1-original.png", "row1-ours-01.png"])

    def test_compaction_abort_and_summary(self):
        r = turn_of(fixture("compacted_reply"), "drawA", 1).record()
        self.assertEqual(len(r["compactions"]), 1)
        self.assertTrue(r["reply_is_compaction_summary"])
        self.assertTrue(r["reply"].startswith("## Objective"))
        self.assertEqual((r["end_state"], r["aborts"][0]["reason"], r["errors"]), ("aborted", "turn time limit", []))
        self.assertEqual(r["checks"][0]["text"], "1 errors: the reply had no ```json block with a JSON list")

    def test_a_codex_turn(self):
        run = fixture("clean_codex")
        r = turn_of(run, "drawA", 1).record()
        self.assertEqual((r["backend"], r["session"], r["finish"], r["end_state"]), ("codex", "thread-drawA-1", "completed", "idle"))
        self.assertEqual((r["tokens"], r["reasoning_tokens"]), ({"in": 20537, "out": 1117}, 233))
        self.assertEqual((r["prompt_head"], r["prompt_source"]), ("round 1: row 1 draft from the checklist", "chat (manager)"))
        self.assertTrue(r["reply"].startswith('```json\n[{"id": "r1.longPrompt"'))
        self.assertEqual(turn_of(run, "art", 1).record()["files"], ["row1-original.png", "row1-ours-01.png"])
        self.assertEqual(turn_of(run, "drawB", 1).record()["duration_s"], 117.4)

    def test_a_subagent_works_for_its_member_but_does_not_answer_for_it(self):
        run = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, run)
        os.makedirs(os.path.join(run, "state"))
        part = lambda sid, t, **p: {"t": t, "opencode": {"type": "message.part.updated", "properties": {"sessionID": sid, "part": dict(p, sessionID=sid)}}}
        rows = [{"t": 10.0, "hub": "start", "agent": "drawA", "session": "ses_root"},
                {"t": 10.0, "hub": "prompt", "agent": "drawA", "source": "start", "text": "Edit make_deck.py, then run python3 make_deck.py."},
                {"t": 10.1, "hub": "state", "agent": "drawA", "state": "working", "reason": "busy"},
                {"t": 11.0, "opencode": {"type": "session.created", "properties": {"sessionID": "ses_child", "info": {"id": "ses_child", "parentID": "ses_root"}}}},
                part("ses_child", 12.0, id="prt_c1", messageID="msg_c1", type="tool", tool="edit", callID="call_c1",
                     state={"status": "completed", "input": {"filePath": "/work/make_deck.py"}, "output": "Edit applied successfully."}),
                part("ses_child", 13.0, id="prt_c2", messageID="msg_c1", type="text", text="Subagent: edited make_deck.py."),
                {"t": 14.0, "hub": "state", "agent": "drawA", "state": "idle", "reason": "idle"}]
        with open(os.path.join(run, "state", "events.jsonl"), "w", encoding="utf-8") as handle:
            handle.write("".join(json.dumps(r) + "\n" for r in rows))
        r = turn_of(run, "drawA", 1).record()
        self.assertEqual(r["reply"], "")
        self.assertEqual([(c["tool"], c["status"], c["child"]) for c in r["tools"]], [("edit", "completed", True)])
        self.assertEqual(diagnose.findings(run), [])  # the subagent's edit is a change

    def test_a_failed_codex_turn(self):
        r = turn_of(fixture("turn_error"), "art", 1).record()
        self.assertEqual((r["end_state"], r["errors"][0]["name"], r["errors"][0]["message"]), ("error", "exit 1", "No prompt provided via stdin."))

    def test_members_table(self):
        rows = {m["member"]: m for m in diagnose.diagnose(fixture("revisions_rejected"))["members"]}
        self.assertEqual((rows["drawA"]["accepted"], rows["drawA"]["revisions"], rows["drawB"]["accepted"], rows["drawB"]["revisions"]), (2, 2, 0, 2))
        self.assertEqual((rows["drawB"]["turns"], rows["drawB"]["valid"], rows["drawB"]["judged"]), (3, 3, 3))


class DamagedLogsTest(unittest.TestCase):
    def test_a_half_written_line_is_skipped_and_said(self):
        run = copy_fixture(self, "wrong_format")
        with open(os.path.join(run, "state", "events.jsonl"), "a", encoding="utf-8") as handle:
            handle.write('{"t": 1791402042.0, "hub": "pro')
        result = diagnose.diagnose(run)
        self.assertEqual([f["code"] for f in result["findings"]], ["wrong_format"])
        self.assertIn("state/events.jsonl: 1 unreadable line(s) skipped", result["notes"])

    def test_an_unfinished_turn_is_noted_not_judged(self):
        run = copy_fixture(self, "wrong_format")
        path = os.path.join(run, "state", "events.jsonl")
        with open(path, encoding="utf-8") as handle:
            lines = handle.read().splitlines()
        with open(path, "w", encoding="utf-8") as handle:
            handle.write("\n".join(lines[:-2]) + "\n")  # the log ends before the turn did
        result = diagnose.diagnose(run)
        self.assertEqual(result["findings"], [])
        self.assertIn("drawA turn 1 has no end in the log (still running, or the log was cut)", result["notes"])

    def test_a_restarted_daemon_has_no_start_record_and_state_json_names_the_session(self):
        run = copy_fixture(self, "output_limit")
        path = os.path.join(run, "state", "events.jsonl")
        with open(path, encoding="utf-8") as handle:
            lines = handle.read().splitlines()
        with open(path, "w", encoding="utf-8") as handle:
            handle.write("\n".join(lines[1:]) + "\n")
        blind = diagnose.diagnose(run)
        self.assertNotIn("output_limit", [f["code"] for f in blind["findings"]])
        self.assertTrue(any("left out" in note for note in blind["notes"]), blind["notes"])
        with open(os.path.join(run, "state", "state.json"), "w", encoding="utf-8") as handle:
            json.dump({"version": 1, "agents": [{"name": "art", "session_id": "ses_art1", "past_sessions": []}]}, handle)
        self.assertEqual([f["code"] for f in diagnose.findings(run)], ["output_limit"])


class CommandLineTest(unittest.TestCase):
    def run_main(self, *args):
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stderr(err):
            code = diagnose.main(list(args), out=out)
        return code, out.getvalue()

    def test_table_and_findings(self):
        code, text = self.run_main(fixture("revisions_rejected"))
        self.assertEqual(code, 0)
        cells = {line.split()[0]: line.split() for line in text.splitlines() if line.startswith(("member ", "drawA ", "drawB "))}
        self.assertEqual(cells["member"], ["member", "backend", "turns", "tokens", "in/out", "valid", "revisions", "accepted"])
        self.assertEqual(cells["drawB"], ["drawB", "codex", "3", "176,812/24,872", "3/3", "0/2"])
        self.assertEqual(cells["drawA"], ["drawA", "codex", "3", "142,629/16,833", "3/3", "2/2"])
        self.assertIn("[1] revisions_rejected  drawB: all 2 of drawB's revisions rejected (no progress)", text)
        self.assertIn("work/chat.jsonl:9", text)
        self.assertIn("    do: Its revisions never beat the kept version", text)

    def test_a_clean_run_says_so(self):
        code, text = self.run_main(fixture("clean"))
        self.assertEqual(code, 0)
        self.assertIn("0 findings (nothing matched the rules)", text)

    def test_json(self):
        code, text = self.run_main(fixture("no_change"), "--json")
        self.assertEqual(code, 0)
        data = json.loads(text)
        self.assertEqual(data["findings"], json.loads(json.dumps(diagnose.findings(fixture("no_change")))))
        self.assertEqual(data["members"][0]["member"], "drawA")

    def test_one_turn_in_full(self):
        code, text = self.run_main(fixture("repeated_tool_error"), "--member", "drawA", "--turn", "1")
        self.assertEqual(code, 0)
        for part in ("drawA turn 1 (opencode, session ses_drawA1)", "reply (87 chars):", "tools (4):", "1. edit error",
                     "4. write completed", "     -> Wrote file successfully.", "checks:", "build: make_deck.py ran; deck.json rebuilt",
                     "repeated_tool_error: the same edit error 3 times"):
            self.assertIn(part, text)
        code, text = self.run_main(fixture("repeated_tool_error"), "--member", "drawA", "--turn", "1", "--json")
        self.assertEqual((code, json.loads(text)["tools"][3]["tool"], json.loads(text)["findings"][0]["code"]), (0, "write", "repeated_tool_error"))

    def test_one_member(self):
        code, text = self.run_main(fixture("revisions_rejected"), "--member", "drawB")
        self.assertEqual(code, 0)
        self.assertIn("drawB: 3 turns", text)
        self.assertIn("finding revisions_rejected", text)

    def test_output_survives_a_terminal_that_cannot_show_the_reply(self):
        # replies hold characters like "≈" and curly quotes; Python 3.6 under LANG=C can only write ASCII to stdout
        run = copy_fixture(self, "wrong_format")
        rewrite(run, "state/events.jsonl", "in the middle of the row", "at x≈640, “middle”")
        env = dict(os.environ, LANG="C", LC_ALL="C")
        env.pop("PYTHONIOENCODING", None)
        root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
        p = subprocess.run([sys.executable, "-m", "herdr_py.diagnose", run, "--member", "drawA", "--turn", "1"], cwd=root, env=env,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        self.assertEqual(p.returncode, 0, p.stderr.decode("utf-8", "replace"))
        self.assertIn(b"wrong_format: reply without the asked format", p.stdout)

    def test_mistakes_are_reported(self):
        with self.assertRaises(SystemExit):
            self.run_main(fixture("clean"), "--turn", "1")
        self.assertEqual(self.run_main(fixture("clean"), "--member", "nobody")[0], 1)
        self.assertEqual(self.run_main(fixture("clean"), "--member", "drawA", "--turn", "9")[0], 1)
        empty = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, empty)
        code, text = self.run_main(empty)
        self.assertEqual(code, 1)
        self.assertIn("no logs in", text)


