        self.assertIn("this would leave 3 todos open; at most 2", " ".join(wakes[0]["problems"]))  # one over: sent back

    def test_a_todo_being_worked_on_cannot_be_dropped(self):
        drop_taken = {"add": [], "drop": ["$taken"], "done": False}
