    def takes(self):
        path = os.path.join(self.out, "kb", "events.jsonl")
        if not os.path.exists(path):
            return 0
        with open(path) as handle:
            return sum(1 for line in handle if '"op": "take"' in line)

    def steer(self, *commands):
        """Send (delay, command, value[, until]) in a thread once the run has begun; until(): wait for it first."""
        import threading
        def go():
            deadline = time.time() + 10
            while not os.path.exists(os.path.join(self.out, "engine.jsonl")) and time.time() < deadline:
                time.sleep(0.02)
            for delay, command, value, *until in commands:
                time.sleep(delay)
                while until and not until[0]() and time.time() < deadline + 10:
                    time.sleep(0.02)
                if command == "garbage":
                    with open(os.path.join(self.out, "control.jsonl"), "a") as handle:
                        handle.write("not json\n")
                else:
                    engine.send_control(self.out, command, value, by="test")
        threading.Thread(target=go, daemon=True).start()

    def test_a_person_can_pause_resume_and_stop_a_run(self):
        self.script(planner=[add(*["t%d" % i for i in range(6)]), add()],
                    members={"a": [{"answer": "1", "sleep": 0.8}], "b": [{"answer": "2", "sleep": 0.8}]})
        # pause once a todo is taken (the turns already taken finish), resume 1.5 s later, stop once work went on
        before = []
        self.steer((0.0, "garbage", None, lambda: self.takes() >= 1), (0.0, "pause", None),
                   (1.5, "resume", None, lambda: before.append(self.takes()) or True),
                   (0.0, "stop", None, lambda: self.takes() > before[0]))
        code, said, err = self.run_main("--turns", "12", "--max-open", "6")
        s = self.summary()
        self.assertEqual(s["stopped"], "stopped by a person")
        controls = [e for e in self.records("engine.jsonl") if e["kind"] == "control"]
        self.assertEqual([c["command"] for c in controls], [None, "pause", "resume", "stop"])
        self.assertIn("not a command", controls[0]["refused"])
        paused, resumed = controls[1]["t"], controls[2]["t"]
        turns = self.records("run.jsonl")
        self.assertFalse([t["turn"] for t in turns if paused < t["start"] < resumed])  # nothing started while paused
        self.assertTrue([t for t in turns if t["start"] >= resumed])  # work went on (taken in the same millisecond, too)
        self.assertGreater(s["paused_seconds"], 1.0)
        self.assertLess(s["turns"], 12)
        self.assertTrue(all(v < s["seconds"] - 1.0 for v in s["idle_seconds"].values()), s)  # paused time is not waiting

    def test_a_pause_stops_the_waiting_clock_of_a_free_member(self):
        import types
        now = {"t": 100.0}
        engine.time = types.SimpleNamespace(time=time.time, monotonic=lambda: now["t"], sleep=time.sleep,
                                            strftime=time.strftime, localtime=time.localtime)
        self.addCleanup(setattr, engine, "time", time)
        run = engine.EngineRun("t", None, None, ["a", "b"], "plan", self.out, 4)
        self.addCleanup(run.elog.close)
        self.addCleanup(run.log.close)
        run.free, run.idle_since, run.idle = {"a": True, "b": False}, {"a": 90.0, "b": None}, {"a": 0.0, "b": 0.0}
        engine.send_control(self.out, "pause")
        run.read_control()  # at 100 s: a has waited 10 s for work; b works
        self.assertEqual((run.paused, run.idle["a"], run.idle_since["a"]), (True, 10.0, None))
        now["t"] = 160.0
        engine.send_control(self.out, "resume")
        run.read_control()  # the 60 s paused are not waiting: a's clock starts again now
        self.assertEqual((run.paused, run.paused_seconds, run.idle["a"], run.idle_since["a"]), (False, 60.0, 10.0, 160.0))
        self.assertEqual(run.idle_since["b"], None)  # b was busy all along: untouched

    def test_a_person_can_change_the_turns_and_the_time_limit(self):
        self.script(planner=[add(*["t%d" % i for i in range(6)]), add()],
                    members={"a": [{"answer": "1", "sleep": 0.3}], "b": [{"answer": "2", "sleep": 0.3}]})
        self.steer((0.0, "turns", 3))
        self.run_main("--turns", "12", "--max-open", "6")
        s = self.summary()
        self.assertEqual((s["turn_budget"], s["turns"], s["stopped"]), (3, 3, "the member turns are used up"))
        shutil.rmtree(self.out)
        shutil.rmtree(self.log)
        self.steer((0.0, "time_limit", 0.5))
        started = time.time()
        self.run_main("--turns", "12", "--max-open", "6")
        self.assertEqual(self.summary()["stopped"], "the time limit of 0.5 s was reached")
        self.assertLess(time.time() - started, 4)

    def test_commands_are_checked_and_can_be_sent_from_the_command_line(self):
        os.makedirs(self.out)
        with open(os.path.join(self.out, "engine.jsonl"), "w") as handle:
            handle.write(json.dumps({"t": 1.0, "kind": "start", "members": ["a"], "planner": "plan", "turns": 3}) + "\n")
        for args, why in ((("jump",), "command: one of"), (("turns",), "turns: give a number"), (("turns", "0"), "more than 0"),
                          (("pause", "3"), "pause takes no value")):
            with self.assertRaises(ValueError) as caught:
                engine.send_control(self.out, *args)
            self.assertIn(why, str(caught.exception))
        with self.assertRaises(ValueError):
            engine.send_control(os.path.join(self.dir, "no-run-here"), "pause")
        said = io.StringIO()
        with contextlib.redirect_stdout(said):
            self.assertEqual(engine.main(["--control", self.out, "time-limit", "30"]), 0)
        with contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(engine.main(["--control", self.out, "jump"]), 2)
        with open(os.path.join(self.out, "control.jsonl")) as handle:
            rows = [json.loads(line) for line in handle]
        self.assertEqual([(r["command"], r["value"]) for r in rows], [("time_limit", 30.0)])
        self.assertTrue(rows[0]["by"].startswith("cli:"))

    def test_a_wall_clock_that_jumps_back_does_not_bend_the_durations(self):
        # seen on RHEL in a VM: the guest's clock was stepped back mid-run and b's waiting time came out as -1.0 s
        import threading
        import types
        real, shift = time.time, {"by": 0.0}
        engine.time = types.SimpleNamespace(time=lambda: real() - shift["by"], monotonic=time.monotonic, sleep=time.sleep,
                                            strftime=time.strftime, localtime=time.localtime)
        self.addCleanup(setattr, engine, "time", time)
        threading.Timer(0.5, lambda: shift.__setitem__("by", 5.0)).start()  # the wall clock jumps 5 s back
        self.script(planner=[add("t1", "t2"), add()], members={"a": [{"answer": "1", "sleep": 1.0}], "b": [{"answer": "2"}]})
        code, said, err = self.run_main("--turns", "2")
        self.assertEqual(code, 0, said + err)
        s = self.summary()
        self.assertTrue(all(v >= 0 for v in s["idle_seconds"].values()), s["idle_seconds"])
        self.assertGreater(s["idle_seconds"]["b"], 0.5)  # b waited for a about 1 s
        self.assertTrue(s["seconds"] > 0.9 and all(t["seconds"] >= 0 for t in self.records("run.jsonl")))

    def test_a_review_is_not_given_to_whoever_made_what_it_reviews(self):
        review = {"text": "review it", "for": None, "parents": [], "after": ["#1"], "review": True}
        self.script(planner=[add({"text": "make it", "for": "a"}, {"text": "other work", "for": "b"}, review), add()],
                    members={"a": [{"answer": "1"}], "b": [{"answer": "2", "sleep": 0.6}, {"answer": "3"}]})
        code, said, err = self.run_main("--turns", "3", "--max-open", "3")
        self.assertEqual(code, 0, said + err)
        todos = {t["text"]: t for t in TeamKB(os.path.join(self.out, "kb")).todo_list()}
        self.assertEqual(todos["review it"]["taken_by"], "b")  # a was free first, but a made what it reviews
        self.assertGreaterEqual(todos["review it"]["taken_t"], todos["other work"]["ended_t"])
        self.assertEqual(todos["review it"]["not_for"], ["a"])
        with open(os.path.join(self.out, "board", "TEAM_BOARD.md")) as handle:
            self.assertIn("(after %s) (a review, not for a)" % todos["make it"]["id"], handle.read())
        prompt = self.read_log("planner-01.txt")
        self.assertIn('gets "review": true: it is never given to whoever made its parents', prompt)
        self.assertIn('"review": false}]', prompt)

    def test_a_review_for_its_own_author_or_for_nobody_is_sent_back(self):
        bad = {"add": [{"text": "make", "for": "a"}, {"text": "check", "for": "a", "after": ["#1"], "review": True},
                       {"text": "make more", "for": "b"}, {"text": "check both", "after": ["#1", "#3"], "review": True},
                       {"text": "maybe", "review": "yes"}], "drop": [], "done": False}
        self.script(planner=[bad, add(done=True)], members={"a": [{"answer": "5"}]})
        self.run_main("--turns", "1", "--planner-wakes", "1", "--max-open", "5")
        problems = " | ".join([w for w in self.records("engine.jsonl") if w["kind"] == "wake"][0]["problems"])
        self.assertIn('add 2: a review for a, who makes what it reviews: leave "for" null or give it to someone else', problems)
        self.assertIn("add 4: a review nobody could take: a, b make what it reviews", problems)
        self.assertIn('add 5: "review" is true or false', problems)
        self.assertNotIn("add 1:", problems)
        self.assertNotIn("add 3:", problems)

    def test_a_review_nobody_can_take_wakes_the_planner_and_then_stops_the_run(self):
        review = {"text": "review it", "for": None, "parents": [], "after": ["#1"], "review": True}
        self.script(planner=[add("make it", review), add()], members={"a": [{"answer": "1"}]})
        code, said, err = self.run_main("--turns", "3", "--planner-wakes", "3", "--time-limit", "8", members=("a",))
        wakes = [w for w in self.records("engine.jsonl") if w["kind"] == "wake"]
        tid = next(t["id"] for t in TeamKB(os.path.join(self.out, "kb")).todo_list() if t["text"] == "review it")
        self.assertEqual(wakes[2]["reason"], "nobody can take the open todos (%s) and no one is working" % tid)
        self.assertEqual(self.summary()["stopped"], "the planner's wakes are used up and nobody can take the open todos (%s)" % tid)


class PartsTest(Base):
    def test_arguments_are_checked(self):
        self.script(planner=[add()], members={})
        code, _, err = self.run_main("--about", "zed=x")
        self.assertEqual(code, 2)
        self.assertIn("--about: no member called zed", err)
        argv = ["--task", "task.md", "--judge", "j", "--planner", "a=claude", "--member", "a=claude", "--out", self.out]
        with contextlib.redirect_stderr(io.StringIO()) as e:
            self.assertEqual(engine.main(argv), 2)
        self.assertIn("a is also a member", e.getvalue())

    def test_a_run_can_start_from_an_earlier_runs_verified_entries(self):
        self.script([add({"text": "give a number", "for": "a", "parents": []}, {"text": "give one too", "for": "b", "parents": []}),
                     add(done=True)], {"a": [{"answer": "5"}], "b": [{"answer": "not a number"}]})
        self.assertEqual(self.run_main("--turns", "2", members=("a", "b"))[0], 0)
        first = {e["id"]: e for e in TeamKB(os.path.join(self.out, "kb")).entries()}
        good = next(i for i, e in first.items() if e["status"] == "valid")
        earlier, self.out = self.out, os.path.join(self.dir, "run2")
        shutil.rmtree(self.log)
        self.script([add({"text": "do better than $best", "for": "a", "parents": ["$best"]}), add(done=True)],
                    {"a": [{"answer": "3"}]})
        code, out, err = self.run_main("--turns", "1", "--seed-from", earlier, members=("a",))
        self.assertEqual(code, 0, err)
        self.assertIn("carried 1 verified entries", out)
        start = self.records("engine.jsonl")[0]
        self.assertEqual(start["seeded"]["carried"], [good])
        self.assertEqual(start["seeded"]["left_out"], {"not valid": 1})
        self.assertIn(good, self.read_log("planner-01.txt"))  # the planner sees what was carried
        self.assertIn(good, self.read_log("a-01.prompt"))  # and so does the member told to build on it
        s = self.summary()
        self.assertEqual((s["seeded"], s["valid"], s["best"]), (1, 1, 3.0))  # this run's own answers, not the carried 5
        made = {e["id"]: e for e in TeamKB(os.path.join(self.out, "kb")).entries()}
        self.assertEqual(next(e for e in made.values() if not e.get("seeded_from"))["parents"], [good])
        third, self.out = self.out, os.path.join(self.dir, "run3")
        shutil.rmtree(self.log)  # the stand-ins count their turns in the log: start them again
        self.script([add("give a number"), add(done=True)], {"a": [{"answer": "4"}]})
        code, out, err = self.run_main("--turns", "1", "--seed-from", third, "--carry", "skill", members=("a",))
        self.assertEqual(code, 0, err)
        self.assertEqual(self.records("engine.jsonl")[0]["seeded"]["carried"], [])  # only skills carry on: these were numbers
        self.assertEqual(self.records("engine.jsonl")[0]["seeded"]["left_out"], {"other kind": 2})

    def test_a_picked_entry_is_carried_whatever_its_kind_or_run(self):
        self.script([add("give a number"), add(done=True)], {"a": [{"answer": "5"}]})
        self.assertEqual(self.run_main("--turns", "1", members=("a",))[0], 0)
        first, picked = self.out, next(e["id"] for e in TeamKB(os.path.join(self.out, "kb")).entries())
        for name, extra, want_picked in (("kept", ["--seed-from", first, "--carry", "skill", "--seed-keep", picked], []),
                                         ("other run", ["--seed-entry", first, picked], [picked])):
            self.out = os.path.join(self.dir, name)
            shutil.rmtree(self.log)
            self.script([add("give a number"), add(done=True)], {"a": [{"answer": "6"}]})
            code, _, err = self.run_main("--turns", "1", *extra, members=("a",))
            self.assertEqual(code, 0, err)
            seeded = self.records("engine.jsonl")[0]["seeded"]
            self.assertEqual((seeded["carried"], seeded["picked"]), ([picked], want_picked), name)

    def member_records(self):
        return [r for r in self.records("run.jsonl") if r.get("member")]

    def test_an_answer_turned_down_is_repaired_in_the_same_turn_when_asked(self):
        self.script(planner=[add("give a number"), add(done=True)], members={"a": [{"answer": "oops"}, {"answer": "7"}]})
        code, said, err = self.run_main("--turns", "1", "--repairs", "2", members=("a",))
        self.assertEqual(code, 0, said + err)
        turn = self.member_records()[0]
        self.assertEqual((turn["status"], turn["score"], turn["best_of"]), ("valid", 7.0, 2))
        first = turn["repairs"][0]["of"]
        kb = {e["id"]: e for e in TeamKB(os.path.join(self.out, "kb")).entries()}
        self.assertEqual((kb[first]["status"], kb[turn["entry"]]["parents"]), ("invalid", [first]))  # it builds on what it fixes
        self.assertIn("not a number: 'oops'", self.read_log("a-02.prompt"))  # told what the judge said
        self.assertEqual(self.read_log("a-02.where").split("\n")[2], "1")  # as a repair of the turn
        self.assertEqual(self.summary()["turns"], 1)  # a repair is no new turn
        todo = TeamKB(os.path.join(self.out, "kb")).todo_list()[0]
        self.assertEqual((todo["state"], todo.get("entry")), ("done", turn["entry"]))

    def test_without_repairs_an_answer_turned_down_ends_the_turn(self):
        self.script(planner=[add("give a number"), add(done=True)], members={"a": [{"answer": "oops"}, {"answer": "7"}]})
        self.run_main("--turns", "1", members=("a",))
        turn = self.member_records()[0]
        self.assertEqual(turn["status"], "invalid")
        self.assertNotIn("repairs", turn)
        self.assertEqual(self.logged(".prompt"), ["a-01.prompt"])

    def test_a_low_score_is_repaired_and_the_turn_ends_with_its_best_version(self):
        self.script(planner=[add("give a number"), add(done=True)], members={"a": [{"answer": "40"}, {"answer": "oops"}, {"answer": "90"}]})
        self.run_main("--turns", "1", "--repairs", "3", "--repair-below", "100", members=("a",))
        turn = self.member_records()[0]
        self.assertEqual([r["status"] for r in turn["repairs"]], ["invalid", "valid", "valid"])  # 90 is still under 100
        self.assertEqual((turn["score"], turn["best_of"]), (90.0, 4))
        self.out = os.path.join(self.dir, "worse")
        shutil.rmtree(self.log)
        self.script(planner=[add("give a number"), add(done=True)], members={"a": [{"answer": "40"}, {"answer": "oops"}]})
        self.run_main("--turns", "1", "--repairs", "1", "--repair-below", "100", members=("a",))
        turn = self.member_records()[0]
        self.assertEqual((turn["status"], turn["score"], turn["best_of"]), ("valid", 40.0, 2))  # a worse repair is not kept as the turn's

    def test_the_bar_is_only_for_the_kinds_it_names_and_no_progress_stops_the_repairs(self):
        self.script(planner=[add("give a number"), add(done=True)],
                    members={"a": [{"answer": "ARTIFACT: skill\n20"}, {"answer": "ARTIFACT: skill\n20.5"}]})
        self.run_main("--turns", "1", "--repairs", "2", "--repair-below", "100", "--repair-kind", "code", members=("a",))
        turn = self.member_records()[0]
        self.assertEqual((turn["artifact_kind"], turn["score"]), ("skill", 20.0))
        self.assertNotIn("repairs", turn)  # a skill is not repaired toward a bar set for code
        self.out = os.path.join(self.dir, "flat")
        shutil.rmtree(self.log)
        self.script(planner=[add("give a number"), add(done=True)], members={"a": [{"answer": "40"}, {"answer": "40.0"}, {"answer": "90"}]})
        self.run_main("--turns", "1", "--repairs", "3", "--repair-below", "100", members=("a",))
        turn = self.member_records()[0]
        self.assertEqual(([r["score"] for r in turn["repairs"]], turn["score"]), ([40.0], 40.0))  # no better: stop there

    def test_a_repair_that_says_the_same_again_stops_the_repairs(self):
        self.script(planner=[add("give a number"), add(done=True)], members={"a": [{"answer": "oops"}]})
        self.run_main("--turns", "1", "--repairs", "3", members=("a",))
        turn = self.member_records()[0]
        self.assertEqual([r.get("repeat") for r in turn["repairs"]], [True])  # the same answer: nothing more to try
