        kb = [{"type": "propose", "id": "kskill000000", "t": 50.0, "member": "a", "summary": "how to draw walking", "parents": [],
               "kind": "result", "artifact": "artifacts/s.txt"}, {"type": "verdict", "id": "kskill000000", "status": "valid", "score": 8},
